    local cardW=math.floor((rw-94)/6); for i,c in ipairs(cards) do self:DrawMiniStat(root,"LedgerMini"..i,rx+20+(i-1)*(cardW+10),y+58,cardW,74,c[1],c[2],c[3],c[3]) end
