  function TML:Initialize(addonName)
    if OldInitialize83 then OldInitialize83(self, addonName) end
    self.version = "2.0.16.83"
    self.addOnVersion = 21683
    self.lastUpdated = "06/15/2026 09:15 UTC"
    self.icon = "TamrielMasterLedger/textures/tamrielmasterledger_icon.dds"
    self.displayTitle = "|c00D9FFTamriel Master Ledger|r"
    self:EnsureDataDefaults()
    if self.RegisterGamepadMainMenuEntry then
      zo_callLater(function() if TML and TML.RegisterGamepadMainMenuEntry then TML:RegisterGamepadMainMenuEntry() end end, 250)
    end
    if d then d("Tamriel Master Ledger v"..self.version.." public-release shared sales/networth/scroll/footer fix loaded.") end
  end
end
TML_21683_Patch()

-- =========================================================
-- v2.0.16.84 ROLLBACK BASELINE TRACKER ACCURACY / SESSION FIX
-- Built from v2.0.16.83. No menu/scene/input registration changes.
-- - Daily Quest Tracker scans journal-visible repeatable/daily quests and separates Skill/Guild dailies.
-- - Net Worth visibly shows Crown Rate, Crowns, and Crown Gold value.
-- - Fishing Tracker is session-delta only with Start/Stop/Resume/Reset.
-- - Personal Gold Ledger 24H Net uses wallet snapshot coverage plus verified rows and unmatched change.
-- - Personal Sales Tracker adds gross/fee/net, 24H review handling, per-guild breakdown, and coverage notes.
-- =========================================================
local function TML_21684_Patch()
  TML.version = "2.0.16.84"
  TML.addOnVersion = 21684
  TML.lastUpdated = "06/22/2026 06:45 UTC"
  TML.icon = "TamrielMasterLedger/textures/tamrielmasterledger_icon.dds"
  TML.displayTitle = "|c00D9FFTamriel Master Ledger|r"

  local function Now84()
    if type(WNow) == "function" then return WNow() end
    if type(GetTimeStamp) == "function" then local ok,v = pcall(GetTimeStamp); if ok and v then return tonumber(v) or 0 end end
    return math.floor(os.time and os.time() or 0)
  end
  local function Day84() return tonumber(WORKING_SECONDS_DAY) or 86400 end
  local function Key84(v) return string.lower(tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")) end
  local function SameUser84(a,b) local aa,bb = Key84(a), Key84(b); return aa ~= "" and aa == bb end
  local function ValidTimestamp84(ts)
    ts = tonumber(ts) or 0
    local now = Now84()
    return ts > 0 and ts <= now + 300 and (now - ts) <= ((tonumber(WORKING_HISTORY_DAYS) or 30) * Day84())
  end
  local function Is24H84(ts) return ValidTimestamp84(ts) and (Now84() - (tonumber(ts) or 0)) <= Day84() end
  local function Fee84(g) g = tonumber(g) or 0; return math.floor(g * 0.07 + 0.5) end
  local function Tax84(g) g = tonumber(g) or 0; return math.floor(g * 0.035 + 0.5) end
  local function Net84(g) g = tonumber(g) or 0; return math.max(0, g - Fee84(g)) end
  local function Cell84(text, color) if type(VCell) == "function" then return VCell(text, color) end; return tostring(text or "") end
  local function Limit84(s,n) if type(WLimit) == "function" then return WLimit(s,n) end; s=tostring(s or ""); n=tonumber(n) or 30; return (#s>n) and (s:sub(1,n-3).."...") or s end
  local function Gold84(n) if type(WFormatGold) == "function" then return WFormatGold(n) end; return tostring(math.floor(tonumber(n) or 0)).."g" end
  local function Num84(n) if type(WFormatNumber) == "function" then return WFormatNumber(n) end; return tostring(math.floor(tonumber(n) or 0)) end
  local function Rel84(ts) if type(WRelTime) == "function" then return WRelTime(ts) end; return tostring(ts or "N/A") end
  local function NA84() if type(WNA) == "function" then return WNA() end; return "N/A" end
  local function ItemKey84(link)
    if type(WItemKey) == "function" then local k = WItemKey(link); if k and k ~= "" then return k end end
    return tostring(link or "")
  end
  local function ItemName84(link)
    if type(WGetItemName) == "function" then return WGetItemName(link) end
    return tostring(link or NA84())
  end
  local function Lower84(s) if type(Lower) == "function" then return Lower(s) end; return string.lower(tostring(s or "")) end

  local OldEnsure84 = TML.EnsureDataDefaults
  function TML:EnsureDataDefaults()
    if OldEnsure84 then OldEnsure84(self) end
    self.saved = self.saved or self:Defaults()
    self.saved.scanStatus = self.saved.scanStatus or {}
    self.saved.scrollOffsets = self.saved.scrollOffsets or {}
    self.saved.salesEvents = self.saved.salesEvents or {}
    self.saved.salesCoverage = self.saved.salesCoverage or { guilds = {}, lastScan = 0, review = 0 }
    self.saved.personalSalesFilter = self.saved.personalSalesFilter or "All-Time"
    if self.saved.personalSalesFilter == "Top Sellers" then self.saved.personalSalesFilter = "Best Sellers" end
    self.saved.personalGoldEvents = self.saved.personalGoldEvents or {}
    self.saved.personalGoldReview = self.saved.personalGoldReview or {}
    self.saved.goldSnapshots = self.saved.goldSnapshots or {}
    self.saved.goldSnapshots.history = self.saved.goldSnapshots.history or {}
    self.saved.daily = self.saved.daily or {}
    self.saved.dailyManual = self.saved.dailyManual or {}
    self.saved.dailyScan = self.saved.dailyScan or { quests = {}, questByKey = {}, lastScan = 0, journalCount = 0, active = 0, ready = 0, review = 0 }
    self.saved.dailyFilter = self.saved.dailyFilter or "All"
    self.saved.fishingSession = self.saved.fishingSession or { state = "not_started", baseline = {}, rows = {}, startedAt = 0, resumedAt = 0, stoppedAt = 0, activeSeconds = 0, lastUpdate = 0, baitUsed = 0 }
    self.saved.fishingFilter = self.saved.fishingFilter or "Session"
  end

  -- ---------- Personal Sales Tracker accuracy ----------
  local function NormalizeSale84(e)
    if not e then return nil end
    if type(V21669_NormalizeSaleRow) == "function" then V21669_NormalizeSaleRow(e) end
    local gross = tonumber(e.grossAmount or e.salePrice or e.price or e.amount) or 0
    local fee = tonumber(e.feeAmount) or Fee84(gross)
    local tax = tonumber(e.guildTax or e.tax) or Tax84(gross)
    local net = tonumber(e.netAmount) or tonumber(e.amount) or Net84(gross)
    e.grossAmount = gross
    e.feeAmount = fee
    e.guildTax = tax
    e.netAmount = net
    e.amount = net
    return e
  end
  local OldScanGuildSales84 = TML.ScanGuildSales
  function TML:ScanGuildSales(g)
    self:EnsureDataDefaults()
    local n = 0
    if OldScanGuildSales84 then n = tonumber(OldScanGuildSales84(self, g)) or 0 end
    local gid = g and g.id or 0
    if gid ~= 0 then
      self.saved.salesCoverage.guilds[tostring(gid)] = {
        id = gid,
        name = g and g.name or tostring(gid),
        rows = n,
        lastScan = Now84(),
        status = n > 0 and "Loaded" or "No new rows - verify Guild History is loaded"
      }
    end
    return n
  end
  function TML:ScanAllGuildSales(noRender)
    self:EnsureDataDefaults()
    local total, guilds = 0, 0
    self:EachGuild(function(g)
      guilds = guilds + 1
      local raw=self:ScanGuildSales(g); total = total + (tonumber(raw) or 0)
    end)
    self.saved.salesCoverage.lastScan = Now84()
    self.saved.salesCoverage.review = #(self:GetSalesReviewRows(true) or {})
    self.saved.scanStatus.sales = "All guild sales scan: "..tostring(total).." rows / "..tostring(guilds).." guilds / "..tostring(self.saved.salesCoverage.review or 0).." review"
    if self.RebuildPriceCacheFromSales then self:RebuildPriceCacheFromSales() end
    if not noRender then self:RenderTool(self.state and self.state.activeTool or "personal_sales") end
    return total
  end
  function TML:ScanPersonalSales(noRender)
    self:ScanAllGuildSales(true)
    local rows = self:GetSalesRows(0, true)
    local review = self:GetSalesReviewRows(true)
    self.saved.scanStatus.sales = "Personal sales scan: "..tostring(#rows).." verified @UserID rows / "..tostring(#review).." review"
    if not noRender then self:RenderTool("personal_sales") end
    return #rows
  end
  function TML:GetSalesRows(guildId, onlyMe)
    self:EnsureDataDefaults()
    local rows = {}
    local my = Key84(self:GetUserDisplayName())
    for _,e in pairs(self.saved.salesEvents or {}) do
      NormalizeSale84(e)
      local okGuild = (not guildId or guildId == 0 or e.guildId == guildId)
      local okUser = (not onlyMe) or (Key84(e.seller) == my)
      if okGuild and okUser and ValidTimestamp84(e.timestamp) and (tonumber(e.netAmount or e.amount) or 0) > 0 then rows[#rows+1] = e end
    end
    table.sort(rows, function(a,b) return (tonumber(a.timestamp) or 0) > (tonumber(b.timestamp) or 0) end)
    return rows
  end
  function TML:GetSalesRows24H(guildId, onlyMe)
    local rows = {}
    for _,e in ipairs(self:GetSalesRows(guildId, onlyMe)) do if Is24H84(e.timestamp) then rows[#rows+1] = e end end
    return rows
  end
  function TML:GetSalesReviewRows(onlyMe)
    self:EnsureDataDefaults()
    local rows = {}; local my = Key84(self:GetUserDisplayName())
    for _,e in pairs(self.saved.salesEvents or {}) do
      NormalizeSale84(e)
      local reason = nil
      if onlyMe and Key84(e.seller) ~= my then reason = nil
      elseif not ValidTimestamp84(e.timestamp) then reason = "Bad/missing time"
      elseif (tonumber(e.netAmount or e.amount) or 0) <= 0 then reason = "Missing gold"
      elseif tostring(e.seller or "") == "" then reason = "Missing seller"
      end
      if reason then e.reviewReason = reason; rows[#rows+1] = e end
    end
    table.sort(rows, function(a,b) return (tonumber(a.timestamp) or 0) > (tonumber(b.timestamp) or 0) end)
    return rows
  end
  function TML:ComputeSalesStats(guildId, onlyMe)
    local rows = self:GetSalesRows(guildId, onlyMe)
    local st = { sales24 = 0, salesToday = 0, totalSales = 0, allTimeSales = 0, items = 0, tax = 0, fees = 0, gross = 0, net = 0, topEarner = NA84(), topAmount = 0, deltaPct = nil, rowCount = #rows, review = #(self:GetSalesReviewRows(onlyMe) or {}), guilds = 0 }
    local sellers, guilds = {}, {}
    for _,e in ipairs(rows) do
      local net = tonumber(e.netAmount or e.amount) or 0
      local gross = tonumber(e.grossAmount) or net
      local fee = tonumber(e.feeAmount) or Fee84(gross)
      local tax = tonumber(e.guildTax or e.tax) or Tax84(gross)
      if Is24H84(e.timestamp) then st.sales24 = st.sales24 + net; st.salesToday = st.salesToday + net end
      st.totalSales = st.totalSales + net; st.allTimeSales = st.allTimeSales + net
      st.gross = st.gross + gross; st.fees = st.fees + fee; st.tax = st.tax + tax; st.net = st.net + net
      st.items = st.items + (tonumber(e.quantity) or 1)
      sellers[e.seller or NA84()] = (sellers[e.seller or NA84()] or 0) + net
      guilds[tostring(e.guildId or 0)] = true
    end
    for u,v in pairs(sellers) do if v > st.topAmount then st.topAmount = v; st.topEarner = u end end
    for _ in pairs(guilds) do st.guilds = st.guilds + 1 end
    if st.totalSales > 0 then st.deltaPct = (st.sales24 / st.totalSales) * 100 end
    return st
  end
  function TML:GetPersonalSalesGuildBreakdown()
    local by = {}
    for _,e in ipairs(self:GetSalesRows(0, true)) do
      local gid = tostring(e.guildId or 0)
      local r = by[gid] or { guildId=e.guildId, guild=self:GetGuildName(e.guildId), net24=0, net=0, gross=0, fees=0, items=0, highest=0, last=0, rows=0, status="Loaded" }
      local net = tonumber(e.netAmount or e.amount) or 0
      r.net = r.net + net; r.gross = r.gross + (tonumber(e.grossAmount) or net); r.fees = r.fees + (tonumber(e.feeAmount) or 0); r.items = r.items + (tonumber(e.quantity) or 1); r.rows = r.rows + 1
      if Is24H84(e.timestamp) then r.net24 = r.net24 + net end
      if net > r.highest then r.highest = net end
      if (tonumber(e.timestamp) or 0) > r.last then r.last = tonumber(e.timestamp) or 0 end
      by[gid] = r
    end
    for gid,cov in pairs(self.saved.salesCoverage.guilds or {}) do if not by[gid] then by[gid] = { guildId=tonumber(gid), guild=cov.name or self:GetGuildName(tonumber(gid)), net24=0, net=0, gross=0, fees=0, items=0, highest=0, last=cov.lastScan or 0, rows=0, status=cov.status or "No Rows" } end end
    local rows = {}; for _,r in pairs(by) do rows[#rows+1] = r end
    table.sort(rows, function(a,b) return (a.net or 0) > (b.net or 0) end)
    return rows
  end
  function TML:GetPersonalBestSellerRows()
    local by = {}
    for _,e in ipairs(self:GetSalesRows(0, true)) do
      local key = tostring(e.itemLink or e.itemName or "item")..":"..tostring(e.guildId or 0)
      local r = by[key] or { itemLink=e.itemLink, itemName=e.itemName or ItemName84(e.itemLink), guild=e.guildId, qty=0, gross=0, fees=0, gold=0, highest=0, rows=0 }
      local net = tonumber(e.netAmount or e.amount) or 0
      r.qty = r.qty + (tonumber(e.quantity) or 1); r.gross = r.gross + (tonumber(e.grossAmount) or net); r.fees = r.fees + (tonumber(e.feeAmount) or 0); r.gold = r.gold + net; r.rows = r.rows + 1
      if net > r.highest then r.highest = net end
      by[key] = r
    end
    local rows = {}; for _,r in pairs(by) do r.avg = r.rows > 0 and math.floor((r.gold or 0) / r.rows) or 0; rows[#rows+1] = r end
    table.sort(rows, function(a,b) return (a.gold or 0) > (b.gold or 0) end)
    return rows
  end
  function TML:CyclePersonalSalesFilter()
    self:EnsureDataDefaults()
    local list = {"All-Time", "24H", "High Ticket", "Best Sellers", "Guild Breakdown", "Review"}
    local cur = self.saved.personalSalesFilter or list[1]; local idx = 1
    for i,v in ipairs(list) do if v == cur then idx = i end end
    self.saved.personalSalesFilter = list[(idx % #list) + 1]
    self:RenderTool("personal_sales")
  end
  local OldRenderSales84 = TML.RenderOldSales
  function TML:RenderOldSales(root,x,y,w,h,accent,guildMode)
    if guildMode then if OldRenderSales84 then return OldRenderSales84(self,root,x,y,w,h,accent,guildMode) end end
    local rx, rw = x, w
    local filter = self.saved.personalSalesFilter or "All-Time"
    local st = self:ComputeSalesStats(0, true)
    self:DrawLegacyPanel(root,"PersonalSalesStats84",rx,y,rw,174,"PERSONAL SALES TRACKER",accent)
    local cards = {{"24H Net",Gold84(st.sales24),VGreen},{"All-Time Net",Gold84(st.totalSales),VYellow},{"Gross",Gold84(st.gross),C.gold},{"ESO Fees",Gold84(st.fees),VRed},{"Review",Num84(st.review),st.review>0 and C.red or C.cyanSoft}}
    local cw = math.floor((rw - 78) / 5)
    for i,c in ipairs(cards) do self:DrawMiniStat(root,"PersonalSalesCard84"..i,rx+20+(i-1)*(cw+10),y+58,cw,78,c[1],c[2],c[3],c[3]) end
    local status = self.saved.scanStatus.sales or "Press Scan Sales. Load Guild History first if rows are missing."
    self:Label("PersonalSalesStatus84",root,status,rx+24,y+138,rw-48,26,C.cyanSoft,FONTS.panelSmall,TEXT_ALIGN_CENTER)
    local rows, title, headers, widths = {}, "", {}, nil
    if filter == "Guild Breakdown" then
      title = "YOUR SALES BY GUILD - NET AFTER ESO FEES"; headers = {"Guild","24H Net","All-Time Net","Items","Highest","Status"}; widths = {1.65,1,1,0.65,1,1.25}
      for _,r in ipairs(self:GetPersonalSalesGuildBreakdown()) do rows[#rows+1] = {Limit84(r.guild,24),Cell84(Gold84(r.net24),VGreen),Cell84(Gold84(r.net),VYellow),Num84(r.items),Cell84(Gold84(r.highest),VYellow),r.status or "Loaded"} end
    elseif filter == "Best Sellers" then
      title = "BEST SELLERS - PERSONAL"; headers = {"Item","Guild","Qty","Gross","Fees","Net"}; widths = {2.1,1.25,.55,1,0.85,1}
      for _,e in ipairs(self:GetPersonalBestSellerRows()) do rows[#rows+1] = {self:FormatItemCell(e.itemLink,e.itemName,26),self:GetGuildName(e.guild),Num84(e.qty),Gold84(e.gross),Cell84(Gold84(e.fees),VRed),Cell84(Gold84(e.gold),VYellow)} end
    elseif filter == "High Ticket" then
      title = "HIGH TICKET PERSONAL SALES"; headers = {"Item","Guild","Qty","Gross","Fee","Net","When"}; widths = {1.75,1.1,.45,.85,.75,.9,.9}
      local source = self:GetSalesRows(0,true); table.sort(source,function(a,b) return (tonumber(a.netAmount or a.amount) or 0) > (tonumber(b.netAmount or b.amount) or 0) end)
      for _,e in ipairs(source) do rows[#rows+1] = {self:FormatItemCell(e.itemLink,e.itemName,22),self:GetGuildName(e.guildId),Num84(e.quantity),Gold84(e.grossAmount),Cell84(Gold84(e.feeAmount),VRed),Cell84(Gold84(e.netAmount or e.amount),VYellow),Rel84(e.timestamp)} end
    elseif filter == "Review" then
      title = "REVIEW ROWS - NOT USED IN 24H TOTALS"; headers = {"Item","Guild","Seller","Gold","Reason","When"}; widths = {1.85,1.1,1,0.8,1.2,.8}
      for _,e in ipairs(self:GetSalesReviewRows(true)) do rows[#rows+1] = {self:FormatItemCell(e.itemLink,e.itemName,22),self:GetGuildName(e.guildId),Limit84(e.seller,18),Gold84(e.netAmount or e.amount),e.reviewReason or "Review",Rel84(e.timestamp)} end
    else
      local source = (filter == "24H") and self:GetSalesRows24H(0,true) or self:GetSalesRows(0,true)
      title = (filter == "24H") and "24H PERSONAL SALES - VERIFIED TIMESTAMPS ONLY" or "ALL-TIME PERSONAL SALES - NET AFTER ESO FEES"
      headers = {"Item","Guild","Qty","Gross","Fee","Net","When"}; widths = {1.75,1.1,.45,.85,.75,.9,.9}
      for _,e in ipairs(source) do rows[#rows+1] = {self:FormatItemCell(e.itemLink,e.itemName,22),self:GetGuildName(e.guildId),Num84(e.quantity),Gold84(e.grossAmount),Cell84(Gold84(e.feeAmount),VRed),Cell84(Gold84(e.netAmount or e.amount),VYellow),Rel84(e.timestamp)} end
    end
    self:DrawLegacyTable(root,"PersonalSalesRows84",rx,y+196,rw,h-274,title,headers,self:RowsOrNA(rows,#headers,"Press Scan Sales"),accent,widths)
    local by = y + h - 64; local bw = math.floor((rw - 36) / 4)
    self:ToolButton(root,"PersonalSalesScan84",rx,by,bw,48,"Scan Sales",accent,function() TML:ScanPersonalSales() end)
    self:ToolButton(root,"PersonalSalesAll84",rx+bw+12,by,bw,48,"Scan All",accent,function() TML:ScanAllGuildSales() end)
    self:ToolButton(root,"PersonalSalesFilter84",rx+(bw+12)*2,by,bw,48,"Filter: "..filter,accent,function() TML:CyclePersonalSalesFilter() end)
    self:ToolButton(root,"PersonalSalesReset84",rx+(bw+12)*3,by,bw,48,"Reset",C.gold,function() TML:ResetPageData("personal_sales") end)
  end

  -- ---------- Personal Gold Ledger 24H snapshot accuracy ----------
  local function CurrentGoldSnapshot84(self)
    local carried = tonumber(self:GetCarriedGoldLive()) or 0
    local bank = tonumber(self:GetBankGoldLive())
    local total = carried + (bank or 0)
    return { carriedGold = carried, bankedGold = bank, total = total, timestamp = Now84() }
  end
  local function SaveGoldSnapshot84(self)
    self.saved.goldSnapshots = self.saved.goldSnapshots or {}; self.saved.goldSnapshots.history = self.saved.goldSnapshots.history or {}
    local snap = CurrentGoldSnapshot84(self)
    local hist = self.saved.goldSnapshots.history
    hist[#hist+1] = snap
    table.sort(hist, function(a,b) return (tonumber(a.timestamp) or 0) < (tonumber(b.timestamp) or 0) end)
    local cutoff = Now84() - (7 * Day84())
    local kept = {}; for _,s in ipairs(hist) do if (tonumber(s.timestamp) or 0) >= cutoff then kept[#kept+1] = s end end
    self.saved.goldSnapshots.history = kept
    self.saved.goldSnapshots.personalLast = snap
    return snap
  end
  function TML:V21684_AddPersonalGoldRow(temp, source, amount, direction, note, timestamp, keyExtra)
    amount = tonumber(amount) or 0; timestamp = tonumber(timestamp) or 0
    if amount <= 0 or not ValidTimestamp84(timestamp) then return false end
    local key = tostring(source)..":"..tostring(direction)..":"..tostring(timestamp)..":"..tostring(amount)..":"..tostring(keyExtra or "")
    if temp[key] then return false end
    temp[key] = { timestamp = timestamp, user = self:GetUserDisplayName(), source = source, amount = amount, direction = direction, note = note or source }
    return true
  end
  function TML:ScanPersonalGoldLedger()
    self:EnsureDataDefaults()
    local snap = SaveGoldSnapshot84(self)
    self:ScanAllGuildSales(true)
    self:EachGuild(function(g) self:ScanGuildGold(g) end)
    if self.RebuildDonationEvents then self:RebuildDonationEvents() end
    local temp, review = {}, {}
    local my = self:GetUserDisplayName(); local added, excluded = 0, 0
    for _,s in pairs(self.saved.salesEvents or {}) do
      NormalizeSale84(s)
      if SameUser84(s.seller, my) then
        if self:V21684_AddPersonalGoldRow(temp,"Guild Trader Sale",tonumber(s.netAmount or s.amount) or 0,"in",self:GetGuildName(s.guildId),s.timestamp,"sale:"..tostring(s.guildId)..":"..tostring(s.eventId or s.itemLink or s.itemName)) then added = added + 1 else excluded = excluded + 1; review[#review+1] = {source="Guild Trader Sale", reason="Bad time/duplicate/zero", amount=tonumber(s.netAmount or s.amount) or 0, timestamp=s.timestamp} end
      end
    end
    for _,e in pairs(self.saved.guildGoldEvents or {}) do
      if SameUser84(e.user, my) then
        local b = tostring(e.bucket or ""); local amt = tonumber(e.amount) or 0
        if e.action == "deposit" and (b == "Donation" or b == "Ticket" or b == "Giveaway Ticket" or b == "Reset") then
          if self:V21684_AddPersonalGoldRow(temp,"Guild Bank Deposit",amt,"out",b,e.timestamp,"gold:"..tostring(e.guildId)..":"..tostring(amt)..":"..b) then added = added + 1 else excluded = excluded + 1 end
        elseif e.action == "withdraw" and (b == "Withdrawal" or b == "Withdraw") then
          if self:V21684_AddPersonalGoldRow(temp,"Guild Bank Withdrawal",amt,"in",b,e.timestamp,"gold:"..tostring(e.guildId)..":"..tostring(amt)..":"..b) then added = added + 1 else excluded = excluded + 1 end
        else
          excluded = excluded + 1
        end
      end
    end
    self.saved.personalGoldEvents = temp
    self.saved.personalGoldReview = review
    self.saved.personalGoldTotals = { moves = added, excluded = excluded, snapshotTotal = snap.total }
    self.saved.scanStatus.personalGold = "Refresh complete: "..tostring(added).." verified rows / "..tostring(excluded).." review. 24H Net uses wallet snapshots when available."
    if self.MarkScanned then self:MarkScanned(added>0 and "Scanned" or "Partial", added>0) end
  end
  function TML:GetPersonalGoldRows(filter)
    self:EnsureDataDefaults(); local rows = {}; filter = filter or self.saved.personalGoldFilter or "Recent"
    for _,e in pairs(self.saved.personalGoldEvents or {}) do
      if filter == "Gold In" then if e.direction == "in" then rows[#rows+1] = e end
      elseif filter == "Gold Out" then if e.direction == "out" then rows[#rows+1] = e end
      elseif filter == "24H" then if Is24H84(e.timestamp) then rows[#rows+1] = e end
      else rows[#rows+1] = e end
    end
    if filter == "Gold In" or filter == "Gold Out" then table.sort(rows,function(a,b) return (tonumber(a.amount) or 0) > (tonumber(b.amount) or 0) end) else table.sort(rows,function(a,b) return (tonumber(a.timestamp) or 0) > (tonumber(b.timestamp) or 0) end) end
    return rows
  end
  function TML:CyclePersonalGoldFilter()
    self:EnsureDataDefaults(); local list = {"Recent","24H","Gold In","Gold Out"}; local cur = self.saved.personalGoldFilter or list[1]; local idx = 1
    for i,v in ipairs(list) do if v == cur then idx = i end end
    self.saved.personalGoldFilter = list[(idx % #list) + 1]
    self:RenderTool("gold_ledger_personal")
  end
  function TML:ComputePersonalGoldStats()
    self:EnsureDataDefaults()
    local snap = CurrentGoldSnapshot84(self)
    local st = { current=snap.carriedGold, bank=snap.bankedGold, total=snap.total, in24=0, out24=0, verifiedNet24=0, net24=0, allIn=0, allOut=0, allNet=0, actualNet24=nil, unmatched24=nil, coverage="Need 24H Baseline", scanned=(self.saved.scanStatus and self.saved.scanStatus.personalGold ~= nil) }
    for _,e in ipairs(self:GetPersonalGoldRows("Recent")) do
      local amt = tonumber(e.amount) or 0
      if e.direction == "in" then st.allIn = st.allIn + amt; if Is24H84(e.timestamp) then st.in24 = st.in24 + amt end
      elseif e.direction == "out" then st.allOut = st.allOut + amt; if Is24H84(e.timestamp) then st.out24 = st.out24 + amt end end
    end
    st.verifiedNet24 = st.in24 - st.out24
    st.allNet = st.allIn - st.allOut
    local hist = self.saved.goldSnapshots and self.saved.goldSnapshots.history or {}
    local target = Now84() - Day84(); local base = nil; local earliest = nil
    for _,s in ipairs(hist) do
      if tonumber(s.total) and tonumber(s.timestamp) then
        if not earliest or (tonumber(s.timestamp) or 0) < (tonumber(earliest.timestamp) or 0) then earliest = s end
        if (tonumber(s.timestamp) or 0) <= target and ((not base) or (tonumber(s.timestamp) or 0) > (tonumber(base.timestamp) or 0)) then base = s end
      end
    end
    if base then st.actualNet24 = snap.total - (tonumber(base.total) or 0); st.coverage = "Full 24H" elseif earliest and (Now84() - (tonumber(earliest.timestamp) or 0)) > 60 then local hours = math.floor((Now84() - (tonumber(earliest.timestamp) or 0)) / 3600); st.actualNet24 = snap.total - (tonumber(earliest.total) or 0); st.coverage = "Partial "..tostring(hours).."h" end
    if st.actualNet24 ~= nil then st.net24 = st.actualNet24; st.unmatched24 = st.actualNet24 - st.verifiedNet24 else st.net24 = st.verifiedNet24; st.unmatched24 = nil end
    return st
  end
  local OldRenderLedger84 = TML.RenderOldLedger
  function TML:RenderOldLedger(root,x,y,w,h,accent,guildMode)
    if guildMode then if OldRenderLedger84 then return OldRenderLedger84(self,root,x,y,w,h,accent,guildMode) end end
    local st = self:ComputePersonalGoldStats(); local topH = 246
    self:DrawLegacyPanel(root,"PersonalGoldStats84",x,y,w,topH,"PERSONAL GOLD LEDGER",accent)
    local bankText = st.bank == nil and "Bank N/A" or Gold84(st.bank)
    local unmatchedText = st.unmatched24 == nil and "Need Data" or Gold84(st.unmatched24)
    local cards = {{"Current Gold",Gold84(st.current),C.gold},{"Bank Gold",bankText,C.gold},{"24H Verified In",Gold84(st.in24),VGreen},{"24H Verified Out",Gold84(st.out24),VRed},{"24H Net",Gold84(st.net24),st.net24>=0 and VGreen or VRed},{"Unmatched 24H",unmatchedText,(st.unmatched24 or 0)>=0 and VGreen or VRed},{"All-Time Net",Gold84(st.allNet),st.allNet>=0 and VGreen or VRed},{"Coverage",st.coverage,C.cyanSoft}}
    local cardW = math.floor((w - 90) / 4)
    for i,c in ipairs(cards) do local col=(i-1)%4; local row=math.floor((i-1)/4); self:DrawMiniStat(root,"PersonalGoldCard84"..i,x+24+col*(cardW+14),y+58+row*78,cardW,68,c[1],c[2],c[3],c[3]) end
    self:Label("PersonalGoldNote84",root,tostring(self.saved.scanStatus.personalGold or "Press Refresh Ledger. 24H Net becomes Full after a 24H snapshot baseline."),x+26,y+topH-34,w-52,30,C.yellowDim,FONTS.panelSmall,TEXT_ALIGN_CENTER)
    local filter = self.saved.personalGoldFilter or "Recent"; local rows = {}
    for _,e in ipairs(self:GetPersonalGoldRows(filter)) do rows[#rows+1] = {Rel84(e.timestamp),Limit84(e.user,18),e.source or NA84(),e.direction=="in" and Cell84("+"..Gold84(e.amount),VGreen) or Cell84("-"..Gold84(e.amount),VRed),e.note or NA84()} end
    self:DrawLegacyTable(root,"PersonalGoldRows84",x,y+topH+20,w,h-topH-92,"PERSONAL GOLD HISTORY - "..string.upper(filter),{"Date","UserID","Source","Amount","Note"},self:RowsOrNA(rows,5,"Press Refresh Ledger"),accent,{1,1.1,1.8,1,1.3})
    local by=y+h-64; local bw=math.floor((w-36)/4)
    self:ToolButton(root,"PersonalGoldRefresh84",x,by,bw,48,"Refresh Ledger",accent,function() TML:ScanPersonalGoldLedger(); TML:RenderTool("gold_ledger_personal") end)
    self:ToolButton(root,"PersonalGoldFilter84",x+bw+12,by,bw,48,"Filter: "..filter,accent,function() TML:CyclePersonalGoldFilter() end)
    self:ToolButton(root,"PersonalGoldBack84",x+(bw+12)*2,by,bw,48,"Back",C.cyan,function() TML:Back() end)
    self:ToolButton(root,"PersonalGoldExit84",x+(bw+12)*3,by,bw,48,"Exit",C.red,function() TML:ReturnToESOMenu() end)
  end

