  local function QuestInfo84(index)
    if type(GetJournalQuestInfo) ~= "function" then return nil end
    local r = {pcall(GetJournalQuestInfo, index)}
    if not r[1] then return nil end
    local name = r[2]
    if not name or name == "" then return nil end
    local text = tostring(r[3] or "").." "..tostring(r[4] or "").." "..tostring(r[5] or "").." "..tostring(r[6] or "")
    local completed = (r[7] == true)
    local questType = r[11]
    local locText = ""
    if type(GetJournalQuestLocationInfo) == "function" then
      local ok,a,b,c,d = pcall(GetJournalQuestLocationInfo,index)
      if ok then locText = tostring(a or "").." "..tostring(b or "").." "..tostring(c or "").." "..tostring(d or "") end
    end
    local repeatable = false
    if type(IsJournalQuestRepeatable) == "function" then local ok,v = pcall(IsJournalQuestRepeatable,index); if ok then repeatable = (v == true) end end
    if not repeatable and _G.QUEST_REPEAT_DAILY and questType == _G.QUEST_REPEAT_DAILY then repeatable = true end
    if not repeatable and _G.QUEST_TYPE_DAILY and questType == _G.QUEST_TYPE_DAILY then repeatable = true end
    return { index=index, name=tostring(name), text=text, loc=locText, completed=completed, repeatable=repeatable, questType=questType }
  end
  function TML:V21684_ClassifyDailyQuest(q)
    local hay = Lower84(tostring(q.name or "").." "..tostring(q.text or "").." "..tostring(q.loc or ""))
    for _,def in ipairs(self:V21684_DailyDefinitions()) do
      for _,p in ipairs(def.patterns or {}) do if hay:find(Lower84(p),1,true) then return def end end
    end
    if q.repeatable or hay:find("daily",1,true) then return {key="journal:"..Key84(q.name),section="Journal Daily",zone="Journal Daily",focus="Active daily quest",reward="Quest reward",patterns={}} end
    return nil
  end
  function TML:ScanDailyQuests(noRender)
    self:EnsureDataDefaults()
    local scan = { quests = {}, questByKey = {}, lastScan = Now84(), journalCount = 0, active = 0, ready = 0, review = 0 }
    if type(GetNumJournalQuests) == "function" then
      local ok,n = pcall(GetNumJournalQuests); n = ok and (tonumber(n) or 0) or 0
      for i=1,n do
        local q = QuestInfo84(i)
        if q then
          scan.journalCount = scan.journalCount + 1
          local def = self:V21684_ClassifyDailyQuest(q)
          if def then
            local status = q.completed and "Ready to Turn In" or "Active"
            local row = { key=def.key, name=q.name, section=def.section, zone=def.zone, focus=def.focus, reward=def.reward, status=status, questIndex=i, timestamp=Now84() }
            scan.quests[#scan.quests+1] = row; scan.questByKey[def.key] = row
            if q.completed then scan.ready = scan.ready + 1 else scan.active = scan.active + 1 end
          end
        end
      end
    end
    self.saved.dailyScan = scan
    self.saved.scanStatus.daily = "Journal scan: "..tostring(scan.active).." active / "..tostring(scan.ready).." ready / "..tostring(scan.journalCount).." journal quests checked"
    if self.MarkScanned then self:MarkScanned("Scanned", true) end
    if not noRender then self:RenderTool("daily_quests") end
  end
  function TML:CycleDailyFilter()
    self:EnsureDataDefaults(); local list={"All","Zone","Skill/Guild","Active/Ready","Manual Done"}; local cur=self.saved.dailyFilter or list[1]; local idx=1
    for i,v in ipairs(list) do if v==cur then idx=i end end
    self.saved.dailyFilter = list[(idx % #list)+1]
    self:RenderTool("daily_quests")
  end
  function TML:V21684_ToggleDailyVisible(index)
    self:EnsureDataDefaults(); local rows = self.lastDailyRows84 or self:GetDailyRows(); local row = rows[tonumber(index) or 1]
    if row and row.__key then self.saved.dailyManual[row.__key] = not self.saved.dailyManual[row.__key]; self:RenderTool("daily_quests") end
  end
  function TML:ResetDailies()
    self:EnsureDataDefaults(); self.saved.dailyManual = {}; self.saved.daily = {}; self.saved.dailyScan = { quests={}, questByKey={}, lastScan=0, journalCount=0, active=0, ready=0, review=0 }; self.saved.scanStatus.daily = "Reset complete - press Scan Dailies"; self:RenderTool("daily_quests")
  end
  function TML:GetDailyRows()
    self:EnsureDataDefaults()
    local filter = self.saved.dailyFilter or "All"
    local scan = self.saved.dailyScan or {questByKey={}}
    local rows = {}
    local function include(section,status,key)
      if filter == "All" then return true end
      if filter == "Zone" then return section == "Zone / DLC / Chapter" or section == "PvP" end
      if filter == "Skill/Guild" then return section == "Skill-Line / Guild" end
      if filter == "Active/Ready" then return status == "Active" or status == "Ready to Turn In" end
      if filter == "Manual Done" then return self.saved.dailyManual and self.saved.dailyManual[key] end
      return true
    end
    for _,def in ipairs(self:V21684_DailyDefinitions()) do
      local found = scan.questByKey and scan.questByKey[def.key]
      local status = found and found.status or (self.saved.dailyManual[def.key] and "Completed / Manual" or "Unknown / Manual Check")
      if include(def.section,status,def.key) then local r={def.section,def.zone,def.focus,def.reward,status,"Daily 10:00 UTC"}; r.__key=def.key; r.__status=status; rows[#rows+1]=r end
    end
    for _,q in ipairs(scan.quests or {}) do
      if tostring(q.key or ""):find("journal:",1,true) and include(q.section,q.status,q.key) then local r={q.section,q.name,q.focus or "Active daily",q.reward or "Quest reward",q.status,"Daily 10:00 UTC"}; r.__key=q.key; r.__status=q.status; rows[#rows+1]=r end
    end
    self.lastDailyRows84 = rows
    return rows
  end
  function TML:RenderOldDaily(root,x,y,w,h,accent)
    local rows = self:GetDailyRows(); local done,active,ready,manual = 0,0,0,0
    for _,r in ipairs(rows) do if r.__status == "Ready to Turn In" then ready=ready+1 elseif r.__status == "Active" then active=active+1 elseif r.__status == "Completed / Manual" then done=done+1; manual=manual+1 end end
    self:DrawLegacyPanel(root,"DailyStats84",x,y,w,166,"DAILY QUEST TRACKER",accent,C.yellow)
    local cards={{"Ready",ready,VGreen},{"Active",active,C.cyanSoft},{"Manual Done",manual,VGreen},{"Filter",self.saved.dailyFilter or "All",accent},{"Reset","Daily 10:00 UTC",C.gold}}
    local cardW=math.floor((w-76)/5); for i,c in ipairs(cards) do self:DrawMiniStat(root,"DailyCard84"..i,x+20+(i-1)*(cardW+10),y+60,cardW,74,c[1],tostring(c[2]),c[3],c[3]) end
    self:Label("DailyStatus84",root,tostring(self.saved.scanStatus.daily or "Press Scan Dailies. Turned-in quests that leave the journal require Manual Done."),x+24,y+136,w-48,24,C.yellowDim,FONTS.panelSmall,TEXT_ALIGN_CENTER)
    self:DrawLegacyTable(root,"DailyRows84",x,y+188,w,h-266,"ZONE DAILIES + SKILL-LINE / GUILD DAILIES",{"Section","Zone/Guild","Daily Focus","Reward","Status","Reset"},self:RowsOrNA(rows,6,"Press Scan Dailies"),accent,{1.05,1.35,1.55,1.35,1.15,.85})
    local by=y+h-64; local bw=math.floor((w-60)/6)
    self:ToolButton(root,"DailyScan84",x,by,bw,48,"Scan",accent,function() TML:ScanDailyQuests() end)
    self:ToolButton(root,"DailyFilter84",x+bw+10,by,bw,48,"Filter: "..(self.saved.dailyFilter or "All"),accent,function() TML:CycleDailyFilter() end)
    self:ToolButton(root,"DailyT184",x+(bw+10)*2,by,bw,48,"Toggle #1",accent,function() TML:V21684_ToggleDailyVisible(1) end)
    self:ToolButton(root,"DailyT284",x+(bw+10)*3,by,bw,48,"Toggle #2",accent,function() TML:V21684_ToggleDailyVisible(2) end)
    self:ToolButton(root,"DailyT384",x+(bw+10)*4,by,bw,48,"Toggle #3",accent,function() TML:V21684_ToggleDailyVisible(3) end)
    self:ToolButton(root,"DailyReset84",x+(bw+10)*5,by,bw,48,"Reset",C.red,function() TML:ResetDailies() end)
  end

  -- ---------- Fishing Tracker session delta only ----------
  local function IsFishItem84(name, link, bagId, slotIndex)
    local low = Lower84(name or link or "")
    local tokens = {"fish","bait","roe","perfect roe","wet gunny","gunny sack","worm","crawler","crawlers","guts","insect parts","chub","minnow","shad","fish roe"}
    for _,t in ipairs(tokens) do if low:find(t,1,true) then return true end end
    if link and type(GetItemLinkItemType) == "function" then
      local ok,a,b = pcall(GetItemLinkItemType, link)
      if ok then
        if _G.ITEMTYPE_FISH and a == _G.ITEMTYPE_FISH then return true end
        if _G.ITEMTYPE_LURE and a == _G.ITEMTYPE_LURE then return true end
        if _G.SPECIALIZED_ITEMTYPE_FISH and b == _G.SPECIALIZED_ITEMTYPE_FISH then return true end
      end
    end
    if bagId ~= nil and slotIndex ~= nil and type(GetItemType) == "function" then local ok,t = pcall(GetItemType,bagId,slotIndex); if ok and ((_G.ITEMTYPE_FISH and t==_G.ITEMTYPE_FISH) or (_G.ITEMTYPE_LURE and t==_G.ITEMTYPE_LURE)) then return true end end
    return false
  end
  function TML:V21684_ScanFishCounts()
    local counts = {}
    local function add(link, qty, bagId, slotIndex)
      if not link or link == "" then return end
      local name = ItemName84(link); if not IsFishItem84(name, link, bagId, slotIndex) then return end
      local key = ItemKey84(link); local r = counts[key] or {key=key,name=name,itemLink=link,qty=0}
      r.qty = (tonumber(r.qty) or 0) + (tonumber(qty) or 1); counts[key] = r
    end
    local function scanBag(bagId)
      if bagId == nil or type(GetBagSize) ~= "function" or type(GetItemLink) ~= "function" then return end
      local ok,size = pcall(GetBagSize,bagId); size = ok and tonumber(size) or 0
      for slot=0,math.max(0,size-1) do
        local okL,link = pcall(GetItemLink,bagId,slot)
        if okL and link and link ~= "" then
          local qty = 1; if type(GetSlotStackSize) == "function" then local okQ,q = pcall(GetSlotStackSize,bagId,slot); if okQ and q then qty = tonumber(q) or 1 end end
          add(link,qty,bagId,slot)
        end
      end
    end
    scanBag(_G.BAG_BACKPACK); scanBag(_G.BAG_VIRTUAL)
    return counts
  end
  function TML:V21684_UpdateFishingSession()
    self:EnsureDataDefaults(); local s = self.saved.fishingSession
    if s.state ~= "active" then return end
    local now = Now84(); local cur = self:V21684_ScanFishCounts(); s.baseline = s.baseline or {}; s.rows = s.rows or {}
    for key,row in pairs(cur) do
      local base = s.baseline[key] and tonumber(s.baseline[key].qty) or 0
      local delta = (tonumber(row.qty) or 0) - base
      if delta > 0 then local r = s.rows[key] or {key=key,name=row.name,itemLink=row.itemLink,qty=0,last=0}; r.qty = (tonumber(r.qty) or 0) + delta; r.last = now; s.rows[key] = r end
    end
    for key,baseRow in pairs(s.baseline or {}) do
      local curQty = cur[key] and tonumber(cur[key].qty) or 0
      local delta = curQty - (tonumber(baseRow.qty) or 0)
      if delta < 0 and IsFishItem84(baseRow.name, baseRow.itemLink) then s.baitUsed = (tonumber(s.baitUsed) or 0) + math.abs(delta) end
    end
    s.baseline = cur; s.lastUpdate = now
  end
  function TML:StartFishingSession()
    self:EnsureDataDefaults(); local s = self.saved.fishingSession
    s.state = "active"; s.baseline = self:V21684_ScanFishCounts(); s.rows = {}; s.startedAt = Now84(); s.resumedAt = Now84(); s.stoppedAt = 0; s.activeSeconds = 0; s.lastUpdate = Now84(); s.baitUsed = 0
    self.saved.scanStatus.fishing = "Fishing session started. Existing inventory was snapshotted and will not count."
    self:RenderTool("fishing")
  end
  function TML:StopFishingSession()
    self:EnsureDataDefaults(); local s = self.saved.fishingSession
    if s.state == "active" then self:V21684_UpdateFishingSession(); s.activeSeconds = (tonumber(s.activeSeconds) or 0) + math.max(0, Now84() - (tonumber(s.resumedAt) or Now84())); s.state = "stopped"; s.stoppedAt = Now84(); s.baseline = self:V21684_ScanFishCounts(); self.saved.scanStatus.fishing = "Fishing session stopped. Totals kept." end
    self:RenderTool("fishing")
  end
  function TML:ResumeFishingSession()
    self:EnsureDataDefaults(); local s = self.saved.fishingSession
    if s.state == "stopped" then s.state = "active"; s.resumedAt = Now84(); s.baseline = self:V21684_ScanFishCounts(); self.saved.scanStatus.fishing = "Fishing session resumed from a fresh baseline." end
    self:RenderTool("fishing")
  end
  function TML:ResetFishingSession()
    self:EnsureDataDefaults(); self.saved.fishingSession = {state="not_started",baseline={},rows={},startedAt=0,resumedAt=0,stoppedAt=0,activeSeconds=0,lastUpdate=0,baitUsed=0}; self.saved.fish = {}; self.saved.scanStatus.fishing = "Fishing session reset. Press Start Session."; self:RenderTool("fishing")
  end
  function TML:ScanFishingInventory()
    self:EnsureDataDefaults(); if self.saved.fishingSession.state == "active" then self:V21684_UpdateFishingSession(); self.saved.scanStatus.fishing = "Session refreshed: only deltas since Start/Resume counted." else self.saved.scanStatus.fishing = "Start or Resume a session before tracking fish deltas." end; self:RenderTool("fishing")
  end
  function TML:GetFishRows()
    self:EnsureDataDefaults(); local rows = {}; local s = self.saved.fishingSession or {}
    for _,r in pairs(s.rows or {}) do rows[#rows+1] = r end
    table.sort(rows,function(a,b) return (tonumber(a.qty) or 0) > (tonumber(b.qty) or 0) end)
    return rows
  end
  function TML:RenderOldFishing(root,x,y,w,h,accent)
