    local hours = elapsed > 0 and (elapsed / 3600) or 0; local perHour = hours > 0 and math.floor(total / hours) or 0
    self:DrawLegacyPanel(root,"FishingStatus84",x,y,leftW,h,"FISHING STATUS",accent)
