    self:DrawLegacyTable(root,"FishingRows84",x+leftW+32,y,w-leftW-32,h,"SESSION FISH / BAIT / ROE DELTAS",{"Fish / Bait","Source","Zone","Qty","Last"},self:RowsOrNA(rows,5,"Start a session to track new fish-related items only"),accent,{2.3,1.1,.75,.55,.9})
  end
  local OldInstallEvents84 = TML.InstallEventPipelines
