        if not selfLoot then return end
        if TML and TML.saved and TML.saved.fishingSession and TML.saved.fishingSession.state == "active" then
          if zo_callLater then zo_callLater(function() if TML and TML.V21684_UpdateFishingSession then TML:V21684_UpdateFishingSession() end end, 250) else TML:V21684_UpdateFishingSession() end
        end
      end)
    end
  end

