-- =========================================================
-- v2.0.16.85 ROLLBACK BASELINE STABILITY / DAILY COMPLETION / MODAL FIX
-- Built from v2.0.16.84. No menu/scene/input registration changes.
-- =========================================================
TML85 = TML85 or {}
function TML85.Now()
  if type(WNow) == "function" then return WNow() end
  if type(GetTimeStamp) == "function" then local ok,v = pcall(GetTimeStamp); if ok and v then return tonumber(v) or 0 end end
  return math.floor(os.time and os.time() or 0)
end
function TML85.Day() return tonumber(WORKING_SECONDS_DAY) or 86400 end
function TML85.Key(v) return string.lower(tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")) end
function TML85.Lower(v) return string.lower(tostring(v or "")) end
function TML85.Num(n) if type(WFormatNumber)=="function" then return WFormatNumber(n) end; return tostring(math.floor(tonumber(n) or 0)) end
function TML85.Rel(ts) if type(WRelTime)=="function" then return WRelTime(ts) end; return tostring(ts or "N/A") end
function TML85.Window() return math.floor((TML85.Now() - (10 * 3600)) / TML85.Day()) end
function TML85.Limit(s,n) if type(WLimit)=="function" then return WLimit(s,n) end; s=tostring(s or ""); n=tonumber(n) or 30; return (#s>n) and (s:sub(1,n-3).."...") or s end
function TML85.NA() if type(WNA)=="function" then return WNA() end; return "N/A" end

function TML85.EnsureDailyStore(self)
  self.saved = self.saved or self:Defaults()
  self.saved.scanStatus = self.saved.scanStatus or {}
  self.saved.dailyManual = self.saved.dailyManual or {}
  self.saved.dailyScan = self.saved.dailyScan or { quests={}, questByKey={}, lastScan=0, journalCount=0, active=0, ready=0, review=0 }
  self.saved.dailyCompleted = self.saved.dailyCompleted or { window=TML85.Window(), keys={}, quests={} }
  if self.saved.dailyCompleted.window ~= TML85.Window() then
    self.saved.dailyCompleted = { window=TML85.Window(), keys={}, quests={} }
    self.saved.dailyManual = {}
    self.saved.scanStatus.daily = "Daily reset detected - completion flags cleared. Press Scan Dailies."
  end
end
function TML85.DailyDefinitions(self)
  if self.V21684_DailyDefinitions then return self:V21684_DailyDefinitions() end
  return {}
end
function TML85.ClassifyDailyQuestName(self, name, zoneText)
  local hay = TML85.Lower(tostring(name or "").." "..tostring(zoneText or ""))
  for _,def in ipairs(TML85.DailyDefinitions(self)) do
    for _,pat in ipairs(def.patterns or {}) do if hay:find(TML85.Lower(pat),1,true) then return def end end
  end
  if hay ~= "" then return { key="journal:"..TML85.Key(name), section="Journal Daily", zone=tostring(name or "Daily Quest"), focus="Captured daily quest", reward="Quest reward", patterns={} } end
  return nil
end
function TML85.QuestInfo(index)
  if type(GetJournalQuestInfo) ~= "function" then return nil end
  local r = { pcall(GetJournalQuestInfo, index) }
  if not r[1] then return nil end
  local name = r[2]
  if not name or name == "" then return nil end
  local text = tostring(r[3] or "").." "..tostring(r[4] or "").." "..tostring(r[5] or "")
  local zone = ""
  if type(GetJournalQuestLocationInfo) == "function" then
    local ok,a,b,c,d = pcall(GetJournalQuestLocationInfo,index)
    if ok then zone = tostring(a or "").." "..tostring(b or "").." "..tostring(c or "").." "..tostring(d or "") end
  end
  local repeatable = false
  if type(IsJournalQuestRepeatable)=="function" then local ok,v=pcall(IsJournalQuestRepeatable,index); if ok then repeatable=(v==true) end end
  local complete = false
  if type(IsJournalQuestComplete)=="function" then local ok,v=pcall(IsJournalQuestComplete,index); if ok then complete=(v==true) end end
  return {index=index,name=name,text=text,zone=zone,repeatable=repeatable,complete=complete}
end
function TML85.MarkDailyCompleted(self, questName, manual, def)
  self:EnsureDataDefaults(); TML85.EnsureDailyStore(self)
  def = def or TML85.ClassifyDailyQuestName(self, questName)
  if not def or not def.key then return false end
  if self.saved.dailyCompleted.window ~= TML85.Window() then self.saved.dailyCompleted = { window=TML85.Window(), keys={}, quests={} } end
  self.saved.dailyCompleted.keys[tostring(def.key)] = { name=tostring(questName or def.zone or def.key), timestamp=TML85.Now(), manual=(manual==true), section=def.section, zone=def.zone, focus=def.focus, reward=def.reward }
  self.saved.dailyCompleted.quests[TML85.Key(questName or def.key)] = tostring(def.key)
  return true
end
function TML85.UnmarkDailyCompleted(self, key)
  self:EnsureDataDefaults(); TML85.EnsureDailyStore(self); key=tostring(key or "")
  if self.saved.dailyCompleted and self.saved.dailyCompleted.keys then self.saved.dailyCompleted.keys[key]=nil end
  if self.saved.dailyManual then self.saved.dailyManual[key]=nil end
end
function TML85.DailyStatus(self, def)
  self:EnsureDataDefaults(); TML85.EnsureDailyStore(self)
  local key = tostring(def.key or "")
  local comp = self.saved.dailyCompleted and self.saved.dailyCompleted.keys and self.saved.dailyCompleted.keys[key]
  if comp then return comp.manual and "Manual Complete" or "Completed Today" end
  if self.saved.dailyManual and self.saved.dailyManual[key] then return "Manual Complete" end
  local q = self.saved.dailyScan and self.saved.dailyScan.questByKey and self.saved.dailyScan.questByKey[key]
  if q then return q.status or "Active" end
  return "Not Seen / Unknown"
end
function TML85.IncludeDaily(filter, section, status)
  if filter == "All" then return true end
  if filter == "Zone" then return section == "Zone / DLC / Chapter" or section == "PvP" end
  if filter == "Skill/Guild" then return section == "Skill-Line / Guild" end
  if filter == "Active/Ready" then return status == "Active" or status == "Ready to Turn In" end
  if filter == "Completed" then return status == "Completed Today" or status == "Manual Complete" end
  if filter == "Unknown" then return status == "Not Seen / Unknown" end
  return true
end
function TML85.SaveGoldSnapshotLight(self)
  self:EnsureDataDefaults()
  local carried = 0; if self.GetCarriedGoldLive then carried = tonumber(self:GetCarriedGoldLive()) or 0 end
  local bank = nil; if self.GetBankGoldLive then bank = tonumber(self:GetBankGoldLive()) end
  local snap = { carriedGold=carried, bankedGold=bank, total=carried+(bank or 0), timestamp=TML85.Now(), source="money_update_light" }
  self.saved.goldSnapshots = self.saved.goldSnapshots or {}; self.saved.goldSnapshots.history = self.saved.goldSnapshots.history or {}
  local hist = self.saved.goldSnapshots.history
  if #hist == 0 or math.abs((tonumber(hist[#hist].timestamp) or 0)-snap.timestamp) >= 30 or tonumber(hist[#hist].total) ~= snap.total then hist[#hist+1] = snap end
  local cutoff = TML85.Now() - (7*TML85.Day()); local kept = {}; for _,s in ipairs(hist) do if (tonumber(s.timestamp) or 0) >= cutoff then kept[#kept+1]=s end end
  self.saved.goldSnapshots.history = kept; self.saved.goldSnapshots.personalLast = snap
end
function TML85.IsFishLootName(itemName)
  local low = TML85.Lower(itemName)
  for _,t in ipairs({"fish","bait","roe","perfect roe","wet gunny","gunny sack","worm","worms","crawler","crawlers","guts","insect parts","chub","minnow","shad","fish roe"}) do if low:find(t,1,true) then return true end end
  return false
end

TML85.OldEnsure = TML.EnsureDataDefaults
function TML:EnsureDataDefaults()
  if TML85.OldEnsure then TML85.OldEnsure(self) end
  TML85.EnsureDailyStore(self)
  self.saved.fishingSession = self.saved.fishingSession or {state="not_started",baseline={},rows={},startedAt=0,resumedAt=0,stoppedAt=0,activeSeconds=0,lastUpdate=0,baitUsed=0,nextLootScanAt=0}
  self.saved.goldSnapshots = self.saved.goldSnapshots or {}; self.saved.goldSnapshots.history = self.saved.goldSnapshots.history or {}
end
function TML:V21685_DailyDefinitions() return TML85.DailyDefinitions(self) end
