function TML:ScanDailyQuests(noRender)
  self:EnsureDataDefaults(); self.saved.dailyScan = { quests={}, questByKey={}, lastScan=TML85.Now(), journalCount=0, active=0, ready=0, review=0 }
  local scanned, ready, active, captured = 0,0,0,0
  if type(GetNumJournalQuests)=="function" then
    local ok,n=pcall(GetNumJournalQuests); n=ok and (tonumber(n) or 0) or 0
    for i=1,n do
      local q = TML85.QuestInfo(i)
      if q and (q.repeatable or TML85.Lower(q.name.." "..(q.text or "").." "..(q.zone or "")):find("daily",1,true)) then
        local def = TML85.ClassifyDailyQuestName(self, q.name, q.zone or q.text)
        if def then
          local status = q.complete and "Ready to Turn In" or "Active"
          if q.complete then ready=ready+1 else active=active+1 end
          local row = { key=def.key, name=q.name, section=def.section, zone=def.zone, focus=def.focus, reward=def.reward, status=status, timestamp=TML85.Now(), journalIndex=i }
          self.saved.dailyScan.quests[#self.saved.dailyScan.quests+1]=row; self.saved.dailyScan.questByKey[def.key]=row; scanned=scanned+1
        end
      end
    end
  end
  for _ in pairs((self.saved.dailyCompleted and self.saved.dailyCompleted.keys) or {}) do captured=captured+1 end
  self.saved.dailyScan.journalCount=scanned; self.saved.dailyScan.active=active; self.saved.dailyScan.ready=ready
  self.saved.scanStatus.daily="Scan complete: "..tostring(scanned).." journal-visible dailies / "..tostring(ready).." ready / "..tostring(captured).." completed today captured. Already turned-in quests require event capture or Manual Done."
  if not noRender then self:RenderTool("daily_quests") end
  return scanned
end
