    if not seen[key] then local status=comp.manual and "Manual Complete" or "Completed Today"; local section=comp.section or "Journal Daily"; if TML85.IncludeDaily(filter,section,status) then local r={section,comp.zone or comp.name or key,comp.focus or "Captured daily quest",comp.reward or "Quest reward",status,"Daily 10:00 UTC"}; r.__key=key; r.__status=status; r.__section=section; rows[#rows+1]=r end end
  end
  for _,q in ipairs((self.saved.dailyScan and self.saved.dailyScan.quests) or {}) do
    if q.key and not seen[q.key] then seen[q.key]=true; local status=q.status or "Active"; if TML85.IncludeDaily(filter,q.section,status) then local r={q.section or "Journal Daily",q.name or q.zone or q.key,q.focus or "Active daily",q.reward or "Quest reward",status,"Daily 10:00 UTC"}; r.__key=q.key; r.__status=status; r.__section=q.section; rows[#rows+1]=r end end
  end
  table.sort(rows,function(a,b) local o={ ["Completed Today"]=1,["Manual Complete"]=2,["Ready to Turn In"]=3,["Active"]=4,["Not Seen / Unknown"]=5 }; return (o[a.__status or ""] or 9)<(o[b.__status or ""] or 9) end)
  self.lastDailyRows85=rows; return rows
end
