function TML:InstallEventPipelines()
  if TML85.OldInstall then TML85.OldInstall(self) end
  if EVENT_MANAGER and EVENT_MANAGER.UnregisterForEvent then
    if _G.EVENT_MONEY_UPDATE then EVENT_MANAGER:UnregisterForEvent(self.name.."MoneyDelta", EVENT_MONEY_UPDATE); EVENT_MANAGER:UnregisterForEvent(self.name.."MoneySnapshot85", EVENT_MONEY_UPDATE) end
    if _G.EVENT_LOOT_RECEIVED then EVENT_MANAGER:UnregisterForEvent(self.name.."LootFish", EVENT_LOOT_RECEIVED); EVENT_MANAGER:UnregisterForEvent(self.name.."LootFish84", EVENT_LOOT_RECEIVED); EVENT_MANAGER:UnregisterForEvent(self.name.."LootFish85", EVENT_LOOT_RECEIVED) end
    if _G.EVENT_QUEST_COMPLETE then EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestComplete85", EVENT_QUEST_COMPLETE) end
  end
  if EVENT_MANAGER and _G.EVENT_MONEY_UPDATE then EVENT_MANAGER:RegisterForEvent(self.name.."MoneySnapshot85", EVENT_MONEY_UPDATE, function() if TML and TML.saved then TML85.SaveGoldSnapshotLight(TML) end end) end
  if EVENT_MANAGER and _G.EVENT_LOOT_RECEIVED then EVENT_MANAGER:RegisterForEvent(self.name.."LootFish85", EVENT_LOOT_RECEIVED, function(eventCode, receivedBy, itemName, quantity, itemSound, lootType, selfLoot)
    if not selfLoot then return end
    if not (TML and TML.saved and TML.saved.fishingSession and TML.saved.fishingSession.state=="active") then return end
    if not TML85.IsFishLootName(itemName) then return end
    local now=TML85.Now(); local s=TML.saved.fishingSession; if (tonumber(s.nextLootScanAt) or 0)>now then return end; s.nextLootScanAt=now+4
    if zo_callLater then zo_callLater(function() if TML and TML.V21684_UpdateFishingSession and TML.saved and TML.saved.fishingSession and TML.saved.fishingSession.state=="active" then TML:V21684_UpdateFishingSession() end end,1500) elseif TML.V21684_UpdateFishingSession then TML:V21684_UpdateFishingSession() end
  end) end
  if EVENT_MANAGER and _G.EVENT_QUEST_COMPLETE then EVENT_MANAGER:RegisterForEvent(self.name.."DailyQuestComplete85", EVENT_QUEST_COMPLETE, function(eventCode, ...)
    local questName=nil; local args={...}; for _,v in ipairs(args) do if type(v)=="string" and v~="" then questName=v; break end end
    if questName and TML then local def=TML85.ClassifyDailyQuestName(TML,questName); if def then TML85.MarkDailyCompleted(TML,questName,false,def); TML.saved.scanStatus.daily="Completed today captured: "..tostring(questName) end end
  end) end
end

