-- =========================================================
-- v2.0.16.86 PHASE 35 DAILY TRACKING / GOLD 24H DISPLAY / FOOTER CLEANUP
-- Built from v2.0.16.85 rollback line. No menu/scene/input registration changes.
-- =========================================================
TML86 = TML86 or {}
function TML86.Now()
  if type(WNow) == "function" then return WNow() end
  if type(GetTimeStamp) == "function" then local ok,v = pcall(GetTimeStamp); if ok and v then return tonumber(v) or 0 end end
  return math.floor(os.time and os.time() or 0)
end
function TML86.Day() return tonumber(WORKING_SECONDS_DAY) or 86400 end
function TML86.Key(v) return string.lower(tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")) end
function TML86.Lower(v) return string.lower(tostring(v or "")) end
function TML86.Num(n) if type(WFormatNumber)=="function" then return WFormatNumber(n) end; return tostring(math.floor(tonumber(n) or 0)) end
function TML86.Gold(n) if type(WFormatGold)=="function" then return WFormatGold(n) end; return tostring(math.floor(tonumber(n) or 0)).."g" end
function TML86.Rel(ts) if type(WRelTime)=="function" then return WRelTime(ts) end; return tostring(ts or "N/A") end
function TML86.NA() if type(WNA)=="function" then return WNA() end; return "N/A" end
function TML86.Limit(s,n) if type(WLimit)=="function" then return WLimit(s,n) end; s=tostring(s or ""); n=tonumber(n) or 30; if #s>n then return s:sub(1,n-3).."..." end; return s end
function TML86.DayWindow() return math.floor((TML86.Now() - (10 * 3600)) / TML86.Day()) end
function TML86.Cell(text,color) if type(VCell)=="function" then return VCell(text,color) end; return tostring(text or "") end

function TML86.EnsureDailyStore(self)
  self.saved = self.saved or self:Defaults()
  self.saved.scanStatus = self.saved.scanStatus or {}
  self.saved.dailyManual = self.saved.dailyManual or {}
  self.saved.dailyFilter = self.saved.dailyFilter or "All"
  self.saved.dailyScan = self.saved.dailyScan or { quests={}, questByKey={}, lastScan=0, journalCount=0, active=0, ready=0, review=0, repeatable=0 }
  self.saved.dailyCompleted = self.saved.dailyCompleted or { window=TML86.DayWindow(), keys={}, quests={} }
  if self.saved.dailyCompleted.window ~= TML86.DayWindow() then
    self.saved.dailyCompleted = { window=TML86.DayWindow(), keys={}, quests={} }
    self.saved.dailyManual = {}
    self.saved.scanStatus.daily = "Daily reset detected - completion flags cleared. Press Scan Dailies."
  end
end

function TML86.DailyDefinitions(self)
  if self and self.V21684_DailyDefinitions then return self:V21684_DailyDefinitions() end
  return {}
end

function TML86.GetRepeatType(index)
  if type(GetJournalQuestRepeatType) == "function" then
    local ok, rt = pcall(GetJournalQuestRepeatType, index)
    if ok then return rt end
  end
  return nil
end

function TML86.IsDailyRepeatType(rt)
  if rt == nil then return false end
  if _G.QUEST_REPEAT_DAILY ~= nil and rt == _G.QUEST_REPEAT_DAILY then return true end
  if _G.QUEST_REPEAT_REPEATABLE ~= nil and rt == _G.QUEST_REPEAT_REPEATABLE then return true end
  if _G.QUEST_REPEAT_DAILY_REPEATABLE ~= nil and rt == _G.QUEST_REPEAT_DAILY_REPEATABLE then return true end
  if type(rt) == "number" then return rt ~= 0 end
  return tostring(rt) ~= "" and tostring(rt) ~= "0"
end

function TML86.IsJournalQuestDaily(index)
  local rt = TML86.GetRepeatType(index)
  if TML86.IsDailyRepeatType(rt) then return true, rt end
  if type(IsJournalQuestRepeatable) == "function" then
    local ok, val = pcall(IsJournalQuestRepeatable, index)
    if ok and val == true then return true, rt end
  end
  return false, rt
end

function TML86.GetQuestLocationText(index)
  local parts = {}
  if type(GetJournalQuestLocationInfo) == "function" then
    local vals = { pcall(GetJournalQuestLocationInfo, index) }
    if vals[1] then
      for i=2,#vals do if type(vals[i]) == "string" and vals[i] ~= "" then parts[#parts+1] = vals[i] end end
    end
  end
  return table.concat(parts, " ")
end

function TML86.GetJournalQuest(index)
  if type(GetJournalQuestInfo) ~= "function" then return nil end
  local vals = { pcall(GetJournalQuestInfo, index) }
  if not vals[1] then return nil end
  local name = vals[2]
  if not name or name == "" then return nil end
  local allText = {}
  local complete = false
  for i=2,#vals do
    if type(vals[i]) == "string" and vals[i] ~= "" then allText[#allText+1] = vals[i] end
    if type(vals[i]) == "boolean" and vals[i] == true and i >= 5 then complete = true end
  end
  if type(IsJournalQuestComplete) == "function" then
    local ok, val = pcall(IsJournalQuestComplete, index)
    if ok then complete = (val == true) end
  end
  local daily, repeatType = TML86.IsJournalQuestDaily(index)
  local loc = TML86.GetQuestLocationText(index)
  return { index=index, name=name, text=table.concat(allText," "), zone=loc, complete=complete, daily=daily, repeatType=repeatType }
end

function TML86.DefFromJournalQuest(self, q)
  if not q or not q.name then return nil end
  local hay = TML86.Lower(tostring(q.name or "").." "..tostring(q.text or "").." "..tostring(q.zone or ""))
  for _,def in ipairs(TML86.DailyDefinitions(self)) do
    for _,pat in ipairs(def.patterns or {}) do
      if hay:find(TML86.Lower(pat), 1, true) then return def end
    end
  end
  local zone = tostring(q.zone or "")
  if zone == "" then zone = "Journal Daily" end
  return { key="journal:"..TML86.Key(q.name), section="Journal Repeatable", zone=zone, focus=q.name, reward="Quest reward", patterns={} }
end

function TML86.MarkDailyCompleted(self, questName, manual, def)
  self:EnsureDataDefaults(); TML86.EnsureDailyStore(self)
  def = def or TML86.DefFromJournalQuest(self, { name=questName, text="", zone="" })
  if not def or not def.key then return false end
  if self.saved.dailyCompleted.window ~= TML86.DayWindow() then self.saved.dailyCompleted = { window=TML86.DayWindow(), keys={}, quests={} } end
  local key = tostring(def.key)
  self.saved.dailyCompleted.keys[key] = { name=tostring(questName or def.focus or def.zone or key), timestamp=TML86.Now(), manual=(manual==true), section=def.section, zone=def.zone, focus=def.focus, reward=def.reward }
  self.saved.dailyCompleted.quests[TML86.Key(questName or key)] = key
  if manual then self.saved.dailyManual[key] = true end
  return true
end

function TML86.UnmarkDailyCompleted(self, key)
  self:EnsureDataDefaults(); TML86.EnsureDailyStore(self); key=tostring(key or "")
  if self.saved.dailyCompleted and self.saved.dailyCompleted.keys then self.saved.dailyCompleted.keys[key] = nil end
  if self.saved.dailyManual then self.saved.dailyManual[key] = nil end
end

function TML86.StatusForDef(self, def)
  self:EnsureDataDefaults(); TML86.EnsureDailyStore(self)
  local key = tostring(def and def.key or "")
  local comp = self.saved.dailyCompleted and self.saved.dailyCompleted.keys and self.saved.dailyCompleted.keys[key]
  if comp then return comp.manual and "Manual Complete" or "Completed Today" end
  if self.saved.dailyManual and self.saved.dailyManual[key] then return "Manual Complete" end
  local q = self.saved.dailyScan and self.saved.dailyScan.questByKey and self.saved.dailyScan.questByKey[key]
  if q then return q.status or "Active" end
  return "Not Seen / Unknown"
end

function TML86.IncludeDaily(filter, section, status)
  filter = tostring(filter or "All")
  if filter == "All" then return true end
  if filter == "Zone" then return section == "Zone / DLC / Chapter" or section == "PvP" or section == "Journal Repeatable" end
  if filter == "Skill/Guild" then return section == "Skill-Line / Guild" end
  if filter == "Active/Ready" then return status == "Active" or status == "Ready to Turn In" end
  if filter == "Completed" then return status == "Completed Today" or status == "Manual Complete" end
  if filter == "Unknown" then return status == "Not Seen / Unknown" end
  return true
end

function TML:ScanDailyQuests(noRender)
  self:EnsureDataDefaults(); TML86.EnsureDailyStore(self)
  self.saved.dailyScan = { quests={}, questByKey={}, lastScan=TML86.Now(), journalCount=0, active=0, ready=0, review=0, repeatable=0 }
  local scanned, active, ready, review, repeatable = 0, 0, 0, 0, 0
  if type(GetNumJournalQuests) == "function" then
    local ok, n = pcall(GetNumJournalQuests); n = ok and (tonumber(n) or 0) or 0
    for i=1,n do
      local q = TML86.GetJournalQuest(i)
      if q and q.daily then
        repeatable = repeatable + 1
        local def = TML86.DefFromJournalQuest(self, q)
        if def and def.key then
          local status = q.complete and "Ready to Turn In" or "Active"
          if q.complete then ready = ready + 1 else active = active + 1 end
          local row = { key=def.key, name=q.name, section=def.section, zone=def.zone, focus=def.focus or q.name, reward=def.reward or "Quest reward", status=status, timestamp=TML86.Now(), journalIndex=i, repeatType=q.repeatType }
          self.saved.dailyScan.quests[#self.saved.dailyScan.quests+1] = row
          self.saved.dailyScan.questByKey[def.key] = row
          scanned = scanned + 1
        else
          review = review + 1
        end
      end
    end
  end
  local captured = 0
  for _ in pairs((self.saved.dailyCompleted and self.saved.dailyCompleted.keys) or {}) do captured = captured + 1 end
  self.saved.dailyScan.journalCount = scanned; self.saved.dailyScan.active = active; self.saved.dailyScan.ready = ready; self.saved.dailyScan.review = review; self.saved.dailyScan.repeatable = repeatable
  self.saved.scanStatus.daily = "Scan complete: "..tostring(scanned).." journal repeatable dailies / "..tostring(active).." active / "..tostring(ready).." ready / "..tostring(captured).." completed today captured. Turned-in dailies need completion capture or manual mark."
  if not noRender then self:RenderTool("daily_quests") end
  return scanned
end

function TML:GetDailyRows()
  self:EnsureDataDefaults(); TML86.EnsureDailyStore(self)
  local filter = self.saved.dailyFilter or "All"
  local rows, seen = {}, {}
  for _,def in ipairs(TML86.DailyDefinitions(self)) do
    local status = TML86.StatusForDef(self, def)
    if TML86.IncludeDaily(filter, def.section, status) then
      local r = {def.section, def.zone, def.focus, def.reward, status, "Daily 10:00 UTC"}
      r.__key=def.key; r.__status=status; r.__section=def.section; rows[#rows+1]=r
    end
    seen[def.key] = true
  end
  for key,comp in pairs((self.saved.dailyCompleted and self.saved.dailyCompleted.keys) or {}) do
    if not seen[key] then
      local status = comp.manual and "Manual Complete" or "Completed Today"
      local section = comp.section or "Journal Repeatable"
      if TML86.IncludeDaily(filter, section, status) then
        local r = {section, comp.zone or comp.name or key, comp.focus or comp.name or "Captured daily quest", comp.reward or "Quest reward", status, "Daily 10:00 UTC"}
        r.__key=key; r.__status=status; r.__section=section; rows[#rows+1]=r
      end
      seen[key] = true
    end
  end
  for _,q in ipairs((self.saved.dailyScan and self.saved.dailyScan.quests) or {}) do
    if q.key and not seen[q.key] then
      seen[q.key] = true
      local status = q.status or "Active"
      if TML86.IncludeDaily(filter, q.section, status) then
        local r = {q.section or "Journal Repeatable", q.zone or q.name or q.key, q.focus or q.name or "Active daily", q.reward or "Quest reward", status, "Daily 10:00 UTC"}
        r.__key=q.key; r.__status=status; r.__section=q.section; rows[#rows+1]=r
      end
    end
  end
  table.sort(rows, function(a,b)
    local o={ ["Completed Today"]=1,["Manual Complete"]=2,["Ready to Turn In"]=3,["Active"]=4,["Not Seen / Unknown"]=5 }
    local av,bv=(o[a.__status or ""] or 9),(o[b.__status or ""] or 9)
    if av ~= bv then return av < bv end
    return tostring(a[2] or "") < tostring(b[2] or "")
  end)
  self.lastDailyRows86 = rows
  self.lastDailyRows85 = rows
  return rows
end

function TML:CycleDailyFilter()
  self:EnsureDataDefaults(); local list={"All","Zone","Skill/Guild","Active/Ready","Completed","Unknown"}; local cur=self.saved.dailyFilter or list[1]; local idx=1
  for i,v in ipairs(list) do if v==cur then idx=i end end
  self.saved.dailyFilter=list[(idx % #list)+1]
  self:RenderTool("daily_quests")
end

function TML:V21686_ToggleDailyVisible(index)
  self:EnsureDataDefaults(); local rows=self.lastDailyRows86 or self:GetDailyRows(); local row=rows[tonumber(index) or 1]
  if not row or not row.__key then self.saved.scanStatus.daily="No visible daily in slot #"..tostring(index or 1); self:RenderTool("daily_quests"); return end
  if row.__status == "Completed Today" or row.__status == "Manual Complete" then
    TML86.UnmarkDailyCompleted(self, row.__key)
    self.saved.scanStatus.daily = "Completion removed for "..tostring(row[2] or row.__key)
  else
    TML86.MarkDailyCompleted(self, row[2] or row.__key, true, {key=row.__key,section=row.__section or row[1],zone=row[2],focus=row[3],reward=row[4]})
    self.saved.scanStatus.daily = "Marked complete for today: "..tostring(row[2] or row.__key)
  end
  self:RenderTool("daily_quests")
end

function TML:RenderOldDaily(root,x,y,w,h,accent)
  self:EnsureDataDefaults(); local rows=self:GetDailyRows(); local active,ready,completed,manual,unknown=0,0,0,0,0
  for _,r in ipairs(rows) do
    if r.__status=="Active" then active=active+1 elseif r.__status=="Ready to Turn In" then ready=ready+1 elseif r.__status=="Completed Today" then completed=completed+1 elseif r.__status=="Manual Complete" then manual=manual+1 else unknown=unknown+1 end
  end
  self:DrawLegacyPanel(root,"DailyStats86",x,y,w,176,"DAILY QUEST TRACKER",accent,C.yellow)
  local cards={{"Completed",completed,VGreen},{"Manual",manual,VGreen},{"Ready",ready,C.gold},{"Active",active,C.cyanSoft},{"Unknown",unknown,C.muted},{"Filter",self.saved.dailyFilter or "All",accent}}
  local cardW=math.floor((w-88)/6); for i,c in ipairs(cards) do self:DrawMiniStat(root,"DailyCard86"..i,x+20+(i-1)*(cardW+10),y+58,cardW,74,c[1],tostring(c[2]),c[3],c[3]) end
  self:Label("DailyStatus86",root,tostring(self.saved.scanStatus.daily or "Press Scan. Active/Ready comes from your journal. Completed Today is captured on completion events or manual mark."),x+24,y+140,w-48,24,C.yellowDim,FONTS.panelSmall,TEXT_ALIGN_CENTER)
  self:DrawLegacyTable(root,"DailyRows86",x,y+198,w,h-276,"ZONE DAILIES + SKILL-LINE / GUILD DAILIES",{"Section","Zone/Guild","Daily Focus","Reward","Status","Reset"},self:RowsOrNA(rows,6,"Press Scan Dailies"),accent,{1.05,1.35,1.55,1.35,1.15,.85})
  local by=y+h-66; local bw=math.floor((w-50)/6)
  self:ToolButton(root,"DailyScan86",x,by,bw,48,"Scan",accent,function() TML:ScanDailyQuests() end)
  self:ToolButton(root,"DailyFilter86",x+bw+10,by,bw,48,"Filter: "..(self.saved.dailyFilter or "All"),accent,function() TML:CycleDailyFilter() end)
  self:ToolButton(root,"DailyMark186",x+(bw+10)*2,by,bw,48,"Mark Row 1",accent,function() TML:V21686_ToggleDailyVisible(1) end)
  self:ToolButton(root,"DailyMark286",x+(bw+10)*3,by,bw,48,"Mark Row 2",accent,function() TML:V21686_ToggleDailyVisible(2) end)
  self:ToolButton(root,"DailyUnmark186",x+(bw+10)*4,by,bw,48,"Toggle Row 3",accent,function() TML:V21686_ToggleDailyVisible(3) end)
  self:ToolButton(root,"DailyReset86",x+(bw+10)*5,by,bw,48,"Reset Daily",C.gold,function() TML:ResetPageData("daily_quests") end)
end

function TML86.CaptureCompletedDaily(self, questName, source)
  if not questName or tostring(questName) == "" then return false end
  self:EnsureDataDefaults(); TML86.EnsureDailyStore(self)
  local def = TML86.DefFromJournalQuest(self, {name=questName, text="", zone=""})
  if not def then return false end
  TML86.MarkDailyCompleted(self, questName, false, def)
  self.saved.scanStatus.daily = "Completed today captured ("..tostring(source or "event").."): "..tostring(questName)
  return true
end

TML86.OldInstall = TML.InstallEventPipelines
function TML:InstallEventPipelines()
  if TML86.OldInstall then TML86.OldInstall(self) end
  if EVENT_MANAGER and EVENT_MANAGER.UnregisterForEvent then
    if _G.EVENT_QUEST_COMPLETE then EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestComplete85", EVENT_QUEST_COMPLETE); EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestComplete86", EVENT_QUEST_COMPLETE) end
    if _G.EVENT_QUEST_REMOVED then EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestRemoved86", EVENT_QUEST_REMOVED) end
  end
  if EVENT_MANAGER and _G.EVENT_QUEST_COMPLETE then
    EVENT_MANAGER:RegisterForEvent(self.name.."DailyQuestComplete86", EVENT_QUEST_COMPLETE, function(eventCode, ...)
      local args={...}; local questName=nil
      for _,v in ipairs(args) do if type(v)=="string" and v~="" then questName=v; break end end
      if questName and TML then TML86.CaptureCompletedDaily(TML, questName, "complete") end
    end)
  end
  if EVENT_MANAGER and _G.EVENT_QUEST_REMOVED then
    EVENT_MANAGER:RegisterForEvent(self.name.."DailyQuestRemoved86", EVENT_QUEST_REMOVED, function(eventCode, ...)
      local args={...}; local questName=nil; local completed=false
      for _,v in ipairs(args) do if type(v)=="string" and v~="" and not questName then questName=v elseif type(v)=="boolean" and v==true then completed=true end end
      if completed and questName and TML then TML86.CaptureCompletedDaily(TML, questName, "removed") end
    end)
  end
end

