    {"24H Verified Net",TML86.Gold(verifiedNet),verifiedNet>=0 and VGreen or VRed},{"Snapshot Net",snapshotText,st.actualNet24 and ((st.actualNet24 or 0)>=0 and VGreen or VRed) or C.yellowDim},{"Unmatched 24H",unmatchedText,C.cyanSoft},{"Coverage",coverage,C.cyanSoft}
