  self:DrawLegacyTable(root,"PersonalGoldRows86",x,y+topH+20,w,h-topH-92,"PERSONAL GOLD HISTORY - "..string.upper(filter),{"Date","UserID","Source","Amount","Note"},self:RowsOrNA(rows,5,"Press Refresh Ledger"),accent,{1,1.1,1.8,1,1.3})
  local by=y+h-64; local bw=math.floor((w-12)/2)
  self:ToolButton(root,"PersonalGoldRefresh86",x,by,bw,48,"Refresh Ledger",accent,function() TML:ScanPersonalGoldLedger(); TML:RenderTool("gold_ledger_personal") end)
  self:ToolButton(root,"PersonalGoldFilter86",x+bw+12,by,bw,48,"Filter: "..filter,accent,function() TML:CyclePersonalGoldFilter() end)
