-- =========================================================
-- v2.0.16.87 PHASE 36 TRACKING / ALL-TIME / MODAL LAYOUT FIX
-- Built from v2.0.16.86 rollback line. No menu/scene/input registration changes.
-- =========================================================
TML87 = TML87 or {}
function TML87.Now()
  if type(WNow) == "function" then return WNow() end
  if type(GetTimeStamp) == "function" then local ok,v = pcall(GetTimeStamp); if ok and v then return tonumber(v) or 0 end end
  return math.floor(os.time and os.time() or 0)
end
function TML87.Day() return tonumber(WORKING_SECONDS_DAY) or 86400 end
function TML87.Key(v) return string.lower(tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")) end
function TML87.Lower(v) return string.lower(tostring(v or "")) end
function TML87.Gold(n) if type(WFormatGold)=="function" then return WFormatGold(n) end; return tostring(math.floor(tonumber(n) or 0)).."g" end
function TML87.Num(n) if type(WFormatNumber)=="function" then return WFormatNumber(n) end; return tostring(math.floor(tonumber(n) or 0)) end
function TML87.Rel(ts) if type(WRelTime)=="function" then return WRelTime(ts) end; return tostring(ts or "N/A") end
function TML87.NA() if type(WNA)=="function" then return WNA() end; return "N/A" end
function TML87.Limit(s,n) if type(WLimit)=="function" then return WLimit(s,n) end; s=tostring(s or ""); n=tonumber(n) or 30; if #s>n then return s:sub(1,n-3).."..." end; return s end
function TML87.Cell(text,color) if type(VCell)=="function" then return VCell(text,color) end; return tostring(text or "") end
function TML87.DayWindow() return math.floor((TML87.Now() - (10 * 3600)) / TML87.Day()) end
function TML87.Fee(g) g=tonumber(g) or 0; return math.floor(g*.07 + .5) end
function TML87.Tax(g) g=tonumber(g) or 0; return math.floor(g*.035 + .5) end
function TML87.Net(g) g=tonumber(g) or 0; return math.max(0,g-TML87.Fee(g)) end
function TML87.ValidTime(ts) ts=tonumber(ts) or 0; local now=TML87.Now(); return ts>0 and ts<=now+300 and ts<4102444800 end
function TML87.Is24(ts) return TML87.ValidTime(ts) and (TML87.Now()-(tonumber(ts) or 0)) <= TML87.Day() end

