function TML87.EnsureDailyStore(self)
  self.saved = self.saved or self:Defaults()
  self.saved.scanStatus = self.saved.scanStatus or {}
  self.saved.dailyFilter = self.saved.dailyFilter or "All"
  self.saved.dailyScan = self.saved.dailyScan or { quests={}, questByKey={}, lastScan=0, journalCount=0, active=0, ready=0, review=0, repeatable=0 }
  self.saved.dailyCompleted = self.saved.dailyCompleted or { window=TML87.DayWindow(), keys={}, quests={} }
  if self.saved.dailyCompleted.window ~= TML87.DayWindow() then
    self.saved.dailyCompleted = { window=TML87.DayWindow(), keys={}, quests={} }
    self.saved.scanStatus.daily = "Daily reset detected - completed-today flags cleared. Press Scan Dailies."
  end
  -- Remove legacy manual completion state. Daily Tracker now only shows ESO-proven completion or Unknown.
  self.saved.dailyManual = {}
  for k,v in pairs((self.saved.dailyCompleted and self.saved.dailyCompleted.keys) or {}) do
    if v and v.manual then self.saved.dailyCompleted.keys[k] = nil end
  end
end
function TML87.DailyDefinitions(self) if self and self.V21684_DailyDefinitions then return self:V21684_DailyDefinitions() end; return {} end
function TML87.GetRepeatType(index)
  if type(GetJournalQuestRepeatType)=="function" then local ok,rt=pcall(GetJournalQuestRepeatType,index); if ok then return rt end end
  return nil
end
function TML87.IsDailyRepeatType(rt)
  if rt == nil then return false end
  if _G.QUEST_REPEAT_DAILY ~= nil and rt == _G.QUEST_REPEAT_DAILY then return true end
  if _G.QUEST_REPEAT_REPEATABLE ~= nil and rt == _G.QUEST_REPEAT_REPEATABLE then return true end
  if _G.QUEST_REPEAT_DAILY_REPEATABLE ~= nil and rt == _G.QUEST_REPEAT_DAILY_REPEATABLE then return true end
  if type(rt)=="number" then return rt ~= 0 end
  return tostring(rt) ~= "" and tostring(rt) ~= "0"
end
function TML87.IsJournalQuestDaily(index)
  local rt=TML87.GetRepeatType(index)
  if TML87.IsDailyRepeatType(rt) then return true,rt end
  if type(IsJournalQuestRepeatable)=="function" then local ok,v=pcall(IsJournalQuestRepeatable,index); if ok and v==true then return true,rt end end
  return false,rt
end
function TML87.GetLocation(index)
  local parts={}
  if type(GetJournalQuestLocationInfo)=="function" then local vals={pcall(GetJournalQuestLocationInfo,index)}; if vals[1] then for i=2,#vals do if type(vals[i])=="string" and vals[i]~="" then parts[#parts+1]=vals[i] end end end end
  return table.concat(parts," ")
end
function TML87.GetJournalQuest(index)
  if type(GetJournalQuestInfo)~="function" then return nil end
  local vals={pcall(GetJournalQuestInfo,index)}; if not vals[1] then return nil end
  local name=vals[2]; if not name or name=="" then return nil end
  local textParts={}; local complete=false
  for i=2,#vals do
    if type(vals[i])=="string" and vals[i]~="" then textParts[#textParts+1]=vals[i] end
    if type(vals[i])=="boolean" and vals[i]==true and i>=5 then complete=true end
  end
  if type(IsJournalQuestComplete)=="function" then local ok,v=pcall(IsJournalQuestComplete,index); if ok then complete=(v==true) end end
  local daily,rt=TML87.IsJournalQuestDaily(index)
  return {index=index,name=name,text=table.concat(textParts," "),zone=TML87.GetLocation(index),complete=complete,daily=daily,repeatType=rt}
end
function TML87.DefFromQuest(self,q)
  if not q or not q.name then return nil end
  local hay=TML87.Lower(tostring(q.name or "").." "..tostring(q.text or "").." "..tostring(q.zone or ""))
  for _,def in ipairs(TML87.DailyDefinitions(self)) do for _,pat in ipairs(def.patterns or {}) do if hay:find(TML87.Lower(pat),1,true) then return def end end end
  local z=tostring(q.zone or ""); if z=="" then z="Journal Daily" end
  return {key="journal:"..TML87.Key(q.name),section="Journal Repeatable",zone=z,focus=q.name,reward="Quest reward",patterns={}}
end
function TML87.MarkCompleted(self,questName,def)
  self:EnsureDataDefaults(); TML87.EnsureDailyStore(self)
  def=def or TML87.DefFromQuest(self,{name=questName,text="",zone=""})
  if not def or not def.key then return false end
  self.saved.dailyCompleted.window=TML87.DayWindow(); self.saved.dailyCompleted.keys=self.saved.dailyCompleted.keys or {}; self.saved.dailyCompleted.quests=self.saved.dailyCompleted.quests or {}
  local key=tostring(def.key)
  self.saved.dailyCompleted.keys[key]={name=tostring(questName or def.focus or def.zone or key),timestamp=TML87.Now(),manual=false,section=def.section,zone=def.zone,focus=def.focus,reward=def.reward}
  self.saved.dailyCompleted.quests[TML87.Key(questName or key)] = key
  return true
end
function TML87.StatusForDef(self,def)
  self:EnsureDataDefaults(); TML87.EnsureDailyStore(self)
  local key=tostring(def and def.key or "")
  local comp=self.saved.dailyCompleted and self.saved.dailyCompleted.keys and self.saved.dailyCompleted.keys[key]
  if comp then return "Completed Today" end
  local q=self.saved.dailyScan and self.saved.dailyScan.questByKey and self.saved.dailyScan.questByKey[key]
  if q then return q.status or "Active" end
  return "Not Seen / Unknown"
end
function TML87.IncludeDaily(filter,section,status)
  filter=tostring(filter or "All")
  if filter=="All" then return true end
  if filter=="Zone" then return section=="Zone / DLC / Chapter" or section=="PvP" or section=="Journal Repeatable" end
  if filter=="Skill/Guild" then return section=="Skill-Line / Guild" end
  if filter=="Active/Ready" then return status=="Active" or status=="Ready to Turn In" end
  if filter=="Completed" then return status=="Completed Today" end
  if filter=="Unknown" then return status=="Not Seen / Unknown" end
  return true
end
function TML:ScanDailyQuests(noRender)
  self:EnsureDataDefaults(); TML87.EnsureDailyStore(self)
  self.saved.dailyScan={quests={},questByKey={},lastScan=TML87.Now(),journalCount=0,active=0,ready=0,review=0,repeatable=0}
  local scanned,active,ready,review,repeatable=0,0,0,0,0
  if type(GetNumJournalQuests)=="function" then
    local ok,n=pcall(GetNumJournalQuests); n=ok and (tonumber(n) or 0) or 0
    for i=1,n do
      local q=TML87.GetJournalQuest(i)
      if q and q.daily then
        repeatable=repeatable+1
        local def=TML87.DefFromQuest(self,q)
        if def and def.key then
          local status=q.complete and "Ready to Turn In" or "Active"
          if q.complete then ready=ready+1 else active=active+1 end
          local row={key=def.key,name=q.name,section=def.section,zone=def.zone,focus=def.focus or q.name,reward=def.reward or "Quest reward",status=status,timestamp=TML87.Now(),journalIndex=i,repeatType=q.repeatType}
          self.saved.dailyScan.quests[#self.saved.dailyScan.quests+1]=row; self.saved.dailyScan.questByKey[def.key]=row; scanned=scanned+1
        else review=review+1 end
      end
    end
  end
  local captured=0; for _ in pairs((self.saved.dailyCompleted and self.saved.dailyCompleted.keys) or {}) do captured=captured+1 end
  self.saved.dailyScan.journalCount=scanned; self.saved.dailyScan.active=active; self.saved.dailyScan.ready=ready; self.saved.dailyScan.review=review; self.saved.dailyScan.repeatable=repeatable
  self.saved.scanStatus.daily="Scan complete: "..scanned.." journal repeatable dailies / "..active.." active / "..ready.." ready / "..captured.." completed today captured. Turned-in dailies show only if TML captured ESO completion/removal."
  if not noRender then self:RenderTool("daily_quests") end
  return scanned
end
function TML:GetDailyRows()
  self:EnsureDataDefaults(); TML87.EnsureDailyStore(self)
  local filter=self.saved.dailyFilter or "All"; local rows,seen={},{}
  for _,def in ipairs(TML87.DailyDefinitions(self)) do
    local status=TML87.StatusForDef(self,def)
    if TML87.IncludeDaily(filter,def.section,status) then local r={def.section,def.zone,def.focus,def.reward,status,"Daily 10:00 UTC"}; r.__key=def.key; r.__status=status; r.__section=def.section; rows[#rows+1]=r end
    seen[def.key]=true
  end
  for key,comp in pairs((self.saved.dailyCompleted and self.saved.dailyCompleted.keys) or {}) do
    if not seen[key] then local status="Completed Today"; local section=comp.section or "Journal Repeatable"; if TML87.IncludeDaily(filter,section,status) then local r={section,comp.zone or comp.name or key,comp.focus or comp.name or "Captured daily quest",comp.reward or "Quest reward",status,"Daily 10:00 UTC"}; r.__key=key; r.__status=status; r.__section=section; rows[#rows+1]=r end; seen[key]=true end
  end
  for _,q in ipairs((self.saved.dailyScan and self.saved.dailyScan.quests) or {}) do
    if q.key and not seen[q.key] then seen[q.key]=true; local status=q.status or "Active"; if TML87.IncludeDaily(filter,q.section,status) then local r={q.section or "Journal Repeatable",q.zone or q.name or q.key,q.focus or q.name or "Active daily",q.reward or "Quest reward",status,"Daily 10:00 UTC"}; r.__key=q.key; r.__status=status; r.__section=q.section; rows[#rows+1]=r end end
  end
  table.sort(rows,function(a,b) local o={ ["Completed Today"]=1,["Ready to Turn In"]=2,["Active"]=3,["Not Seen / Unknown"]=4 }; local av,bv=(o[a.__status or ""] or 9),(o[b.__status or ""] or 9); if av~=bv then return av<bv end; return tostring(a[2] or "")<tostring(b[2] or "") end)
  self.lastDailyRows87=rows; self.lastDailyRows86=rows; self.lastDailyRows85=rows; return rows
end
function TML:CycleDailyFilter()
  self:EnsureDataDefaults(); local list={"All","Zone","Skill/Guild","Active/Ready","Completed","Unknown"}; local cur=self.saved.dailyFilter or list[1]; local idx=1
  for i,v in ipairs(list) do if v==cur then idx=i end end
  self.saved.dailyFilter=list[(idx % #list)+1]; self:RenderTool("daily_quests")
end
function TML:V21686_ToggleDailyVisible(index)
  self.saved.scanStatus.daily="Manual daily marking was removed. Daily Tracker now uses ESO journal/completion data only."; self:RenderTool("daily_quests")
end
function TML:V21687_CaptureCompletedDaily(questName,source)
  if not questName or tostring(questName)=="" then return false end
  self:EnsureDataDefaults(); TML87.EnsureDailyStore(self)
  local def=TML87.DefFromQuest(self,{name=questName,text="",zone=""})
  if not def then return false end
  TML87.MarkCompleted(self,questName,def)
  self.saved.scanStatus.daily="Completed today captured ("..tostring(source or "event").."): "..tostring(questName)
  return true
end
function TML:RenderOldDaily(root,x,y,w,h,accent)
  self:EnsureDataDefaults(); local rows=self:GetDailyRows(); local active,ready,completed,unknown=0,0,0,0
  for _,r in ipairs(rows) do if r.__status=="Active" then active=active+1 elseif r.__status=="Ready to Turn In" then ready=ready+1 elseif r.__status=="Completed Today" then completed=completed+1 else unknown=unknown+1 end end
  self:DrawLegacyPanel(root,"DailyStats87",x,y,w,176,"DAILY QUEST TRACKER",accent,C.yellow)
  local cards={{"Completed",completed,VGreen},{"Ready",ready,C.gold},{"Active",active,C.cyanSoft},{"Unknown",unknown,C.muted},{"Filter",self.saved.dailyFilter or "All",accent}}
  local cardW=math.floor((w-80)/5); for i,c in ipairs(cards) do self:DrawMiniStat(root,"DailyCard87"..i,x+20+(i-1)*(cardW+10),y+58,cardW,74,c[1],tostring(c[2]),c[3],c[3]) end
  self:Label("DailyStatus87",root,tostring(self.saved.scanStatus.daily or "Press Scan. Completed Today only appears from ESO completion/removal capture while TML is loaded."),x+24,y+140,w-48,24,C.yellowDim,FONTS.panelSmall,TEXT_ALIGN_CENTER)
  self:DrawLegacyTable(root,"DailyRows87",x,y+198,w,h-276,"ZONE DAILIES + SKILL-LINE / GUILD DAILIES",{"Section","Zone/Guild","Daily Focus","Reward","Status","Reset"},self:RowsOrNA(rows,6,"Press Scan Dailies"),accent,{1.05,1.35,1.55,1.35,1.15,.85})
  local by=y+h-66; local bw=math.floor((w-12)/2)
  self:ToolButton(root,"DailyScan87",x,by,bw,48,"Scan Dailies",accent,function() TML:ScanDailyQuests() end)
  self:ToolButton(root,"DailyFilter87",x+bw+12,by,bw,48,"Filter: "..(self.saved.dailyFilter or "All"),accent,function() TML:CycleDailyFilter() end)
end

-- Install daily event capture without manual completion paths.
TML87.OldInstall = TML.InstallEventPipelines
function TML:InstallEventPipelines()
  if TML87.OldInstall then TML87.OldInstall(self) end
  if EVENT_MANAGER and EVENT_MANAGER.UnregisterForEvent then
    if _G.EVENT_QUEST_COMPLETE then EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestComplete86", EVENT_QUEST_COMPLETE); EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestComplete87", EVENT_QUEST_COMPLETE) end
    if _G.EVENT_QUEST_REMOVED then EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestRemoved86", EVENT_QUEST_REMOVED); EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestRemoved87", EVENT_QUEST_REMOVED) end
  end
  if EVENT_MANAGER and _G.EVENT_QUEST_COMPLETE then
    EVENT_MANAGER:RegisterForEvent(self.name.."DailyQuestComplete87", EVENT_QUEST_COMPLETE, function(eventCode,...)
      local args={...}; local questName=nil
      for _,v in ipairs(args) do if type(v)=="string" and v~="" then questName=v; break end end
      if questName and TML and TML.V21687_CaptureCompletedDaily then TML:V21687_CaptureCompletedDaily(questName,"complete") end
    end)
  end
  if EVENT_MANAGER and _G.EVENT_QUEST_REMOVED then
    EVENT_MANAGER:RegisterForEvent(self.name.."DailyQuestRemoved87", EVENT_QUEST_REMOVED, function(eventCode,...)
      local args={...}; local questName=nil; local completed=false
      for _,v in ipairs(args) do if type(v)=="string" and v~="" and not questName then questName=v elseif type(v)=="boolean" and v==true then completed=true end end
      if completed and questName and TML and TML.V21687_CaptureCompletedDaily then TML:V21687_CaptureCompletedDaily(questName,"removed") end
    end)
  end
end

-- Sales all-time fix: preserve loaded verified sales across scans instead of clearing each guild on every scan.
function TML87.ParseTrader(vals)
  if TML and TML.V21683_ParseTrader then return TML:V21683_ParseTrader(vals) end
  local eventId,timestamp,isRedacted,eventType,seller,buyer,itemLink,quantity,price,tax=vals[1],vals[2],vals[3],vals[4],vals[5],vals[6],vals[7],vals[8],vals[9],vals[10]
  local strings,nums={},{}
  for _,v in ipairs(vals) do if type(v)=="string" then strings[#strings+1]=v elseif type(v)=="number" then nums[#nums+1]=v end end
  for _,s in ipairs(strings) do if (not itemLink or itemLink=="") and s:find("|H",1,true) then itemLink=s end end
  if type(seller)~="string" or seller=="" or seller:find("|H",1,true) then seller=nil end
  for _,s in ipairs(strings) do if s~=itemLink and not seller then seller=s elseif s~=itemLink and s~=seller and not buyer then buyer=s end end
  if not timestamp or not tonumber(timestamp) or tonumber(timestamp)<1000000000 then for _,n in ipairs(nums) do if n>1000000000 and n<4102444800 then timestamp=n; break end end end
  quantity=tonumber(quantity) or 1; price=tonumber(price) or 0
  return eventId,timestamp,isRedacted,eventType,seller,buyer,itemLink,quantity,price,tax
end
function TML87.AddSale(self,gid,row)
  local gross=tonumber(row.price) or 0; local ts=tonumber(row.timestamp) or 0
  if gross<=0 or not TML87.ValidTime(ts) then return false,"review" end
  local qty=tonumber(row.quantity) or 1; if qty<=0 or qty>200000 then qty=1 end
  local fee=TML87.Fee(gross); local net=TML87.Net(gross); local tax=tonumber(row.tax) or TML87.Tax(gross)
  local key=tostring(gid)..":"..tostring(row.eventId or (tostring(row.seller)..":"..tostring(gross)..":"..tostring(ts)..":"..tostring(row.itemLink)..":"..tostring(qty)))
  self.saved.salesEvents[key]={guildId=gid,seller=row.seller or TML87.NA(),buyer=row.buyer,itemLink=row.itemLink,itemName=(type(WGetItemName)=="function" and WGetItemName(row.itemLink) or tostring(row.itemLink or TML87.NA())),quantity=qty,timestamp=ts,eventId=row.eventId,eventType=row.eventType,grossAmount=gross,amount=net,netAmount=net,feeAmount=fee,guildTax=tax,tax=tax,feeAdjusted=true,source="guild trader",lastSeen=TML87.Now()}
  return true
end
function TML:ScanGuildSales(g)
  self:EnsureDataDefaults(); self.saved.salesEvents=self.saved.salesEvents or {}; self.saved.salesCoverage=self.saved.salesCoverage or {guilds={},lastScan=0,review=0}
  if not g or not g.id or g.id==0 then return 0 end
  local cat=self:GetHistoryCategory("trader")
  if type(GetGuildHistoryTraderEventInfo)~="function" or not cat then self.saved.scanStatus.sales="Sales history API unavailable"; return 0 end
  self:RequestHistory(g.id,cat,WORKING_HISTORY_DAYS)
  local newest,oldest=self:GetHistoryIndices(g.id,cat,WORKING_HISTORY_DAYS)
  local stored,skipped,seen=0,0,0
  if oldest>=newest then
    for i=newest,oldest do
      local vals={pcall(GetGuildHistoryTraderEventInfo,g.id,i)}; local ok=table.remove(vals,1)
      if ok then
        local eventId,timestamp,isRedacted,eventType,seller,buyer,itemLink,quantity,price,tax=TML87.ParseTrader(vals)
        if not isRedacted and seller and tonumber(price) and tonumber(price)>0 then
          local added=TML87.AddSale(self,g.id,{eventId=eventId or i,timestamp=timestamp,eventType=eventType,seller=seller,buyer=buyer,itemLink=itemLink,quantity=quantity,price=price,tax=tax})
          if added then stored=stored+1 else skipped=skipped+1 end
          seen=seen+1
        else skipped=skipped+1 end
      else skipped=skipped+1 end
    end
  end
  self:PruneEventTable(self.saved.salesEvents,WORKING_MAX_EVENTS)
  if self.RebuildPriceCacheFromSales then self:RebuildPriceCacheFromSales() end
  self.saved.salesCoverage.guilds[tostring(g.id)]={id=g.id,name=g.name or tostring(g.id),rows=stored,lastScan=TML87.Now(),status=stored>0 and "Merged into All-Time Loaded" or "No new rows - load Guild History"}
  self.saved.salesCoverage.lastScan=TML87.Now()
  self.saved.scanStatus.sales=stored>0 and ("Scan complete: "..stored.." loaded/merged rows / "..skipped.." skipped. All-Time keeps previously loaded rows.") or "No sales rows loaded - load Guild History, then scan again"
  return stored
end
function TML:ScanAllGuildSales(noRender)
  self:EnsureDataDefaults(); local total,guilds=0,0
  self:EachGuild(function(g) guilds=guilds+1; local raw=self:ScanGuildSales(g); total=total+(tonumber(raw) or 0) end)
  self.saved.scanStatus.sales="All guild sales scan: "..tostring(total).." newly loaded/merged rows across "..tostring(guilds).." guilds. All-Time = all retained loaded rows."
  if not noRender then self:RenderTool(self.state.activeTool or "personal_sales") end
  return total
end
function TML:ScanPersonalSales(noRender)
  self:ScanAllGuildSales(true)
  local rows=self:GetSalesRows(0,true); local rows24=self.GetSalesRows24H and self:GetSalesRows24H(0,true) or {}
  self.saved.scanStatus.sales="Personal sales scan: "..tostring(#rows).." all-time loaded @UserID rows / "..tostring(#rows24).." 24H rows."
  if not noRender then self:RenderTool("personal_sales") end
  return #rows
end

-- Personal sales display: clarify All-Time Loaded and do not label 24H data as all-time.
TML87.OldRenderSales = TML.RenderOldSales
function TML:RenderOldSales(root,x,y,w,h,accent,guildMode)
  if guildMode then if TML87.OldRenderSales then return TML87.OldRenderSales(self,root,x,y,w,h,accent,guildMode) end; return end
  local rx,rw=x,w; local filter=self.saved.personalSalesFilter or "All-Time"; local st=self:ComputeSalesStats(0,true)
  self:DrawLegacyPanel(root,"PersonalSalesStats87",rx,y,rw,174,"PERSONAL SALES TRACKER",accent)
  local cards={{"24H Net",TML87.Gold(st.sales24),VGreen},{"All-Time Loaded Net",TML87.Gold(st.totalSales),VYellow},{"All-Time Gross",TML87.Gold(st.gross),C.gold},{"All-Time ESO Fees",TML87.Gold(st.fees),VRed},{"Review",TML87.Num(st.review),st.review>0 and C.red or C.cyanSoft}}
  local cw=math.floor((rw-78)/5); for i,c in ipairs(cards) do self:DrawMiniStat(root,"PersonalSalesCard87"..i,rx+20+(i-1)*(cw+10),y+58,cw,78,c[1],c[2],c[3],c[3]) end
  local status=self.saved.scanStatus.sales or "Press Scan Sales. All-Time Loaded grows as guild history rows are loaded/merged over time."
  self:Label("PersonalSalesStatus87",root,status,rx+24,y+138,rw-48,26,C.cyanSoft,FONTS.panelSmall,TEXT_ALIGN_CENTER)
  local rows,title,headers,widths={},"",{},nil
  if filter=="Guild Breakdown" then
    title="YOUR SALES BY GUILD - ALL-TIME LOADED"; headers={"Guild","24H Net","All-Time Net","Items","Highest","Status"}; widths={1.65,1,1,.65,1,1.25}
    for _,r in ipairs(self:GetPersonalSalesGuildBreakdown()) do rows[#rows+1]={TML87.Limit(r.guild,24),TML87.Cell(TML87.Gold(r.net24),VGreen),TML87.Cell(TML87.Gold(r.net),VYellow),TML87.Num(r.items),TML87.Cell(TML87.Gold(r.highest),VYellow),r.status or "Loaded"} end
  elseif filter=="Best Sellers" then
    title="BEST SELLERS - ALL-TIME LOADED"; headers={"Item","Guild","Qty","Gross","Fees","Net"}; widths={2.1,1.25,.55,1,.85,1}
    for _,e in ipairs(self:GetPersonalBestSellerRows()) do rows[#rows+1]={self:FormatItemCell(e.itemLink,e.itemName,26),self:GetGuildName(e.guild),TML87.Num(e.qty),TML87.Gold(e.gross),TML87.Cell(TML87.Gold(e.fees),VRed),TML87.Cell(TML87.Gold(e.gold),VYellow)} end
  elseif filter=="High Ticket" then
    title="HIGH TICKET PERSONAL SALES - ALL-TIME LOADED"; headers={"Item","Guild","Qty","Gross","Fee","Net","When"}; widths={1.75,1.1,.45,.85,.75,.9,.9}
    local source=self:GetSalesRows(0,true); table.sort(source,function(a,b) return (tonumber(a.netAmount or a.amount) or 0)>(tonumber(b.netAmount or b.amount) or 0) end)
    for _,e in ipairs(source) do rows[#rows+1]={self:FormatItemCell(e.itemLink,e.itemName,22),self:GetGuildName(e.guildId),TML87.Num(e.quantity),TML87.Gold(e.grossAmount),TML87.Cell(TML87.Gold(e.feeAmount),VRed),TML87.Cell(TML87.Gold(e.netAmount or e.amount),VYellow),TML87.Rel(e.timestamp)} end
  elseif filter=="Review" then
    title="REVIEW ROWS - NOT USED IN VERIFIED TOTALS"; headers={"Item","Guild","Seller","Gold","Reason","When"}; widths={1.85,1.1,1,.8,1.2,.8}
    for _,e in ipairs(self:GetSalesReviewRows(true)) do rows[#rows+1]={self:FormatItemCell(e.itemLink,e.itemName,22),self:GetGuildName(e.guildId),TML87.Limit(e.seller,18),TML87.Gold(e.netAmount or e.amount),e.reviewReason or "Review",TML87.Rel(e.timestamp)} end
  else
    local source=(filter=="24H") and self:GetSalesRows24H(0,true) or self:GetSalesRows(0,true)
    title=(filter=="24H") and "24H PERSONAL SALES - VERIFIED TIMESTAMPS ONLY" or "ALL-TIME LOADED PERSONAL SALES - NET AFTER ESO FEES"
    headers={"Item","Guild","Qty","Gross","Fee","Net","When"}; widths={1.75,1.1,.45,.85,.75,.9,.9}
    for _,e in ipairs(source) do rows[#rows+1]={self:FormatItemCell(e.itemLink,e.itemName,22),self:GetGuildName(e.guildId),TML87.Num(e.quantity),TML87.Gold(e.grossAmount),TML87.Cell(TML87.Gold(e.feeAmount),VRed),TML87.Cell(TML87.Gold(e.netAmount or e.amount),VYellow),TML87.Rel(e.timestamp)} end
  end
  self:DrawLegacyTable(root,"PersonalSalesRows87",rx,y+196,rw,h-274,title,headers,self:RowsOrNA(rows,#headers,"Press Scan Sales"),accent,widths)
  local by=y+h-64; local bw=math.floor((rw-24)/3)
  self:ToolButton(root,"PersonalSalesScan87",rx,by,bw,48,"Scan Sales",accent,function() TML:ScanPersonalSales() end)
  self:ToolButton(root,"PersonalSalesAll87",rx+bw+12,by,bw,48,"Scan All",accent,function() TML:ScanAllGuildSales() end)
  self:ToolButton(root,"PersonalSalesFilter87",rx+(bw+12)*2,by,bw,48,"Filter: "..filter,accent,function() TML:CyclePersonalSalesFilter() end)
