-- Personal Gold Ledger: hide Snapshot/Unmatched when coverage is Partial 0h or no real 24H baseline exists.
TML87.OldRenderLedger = TML.RenderOldLedger
function TML:RenderOldLedger(root,x,y,w,h,accent,guildMode)
  if guildMode then if TML87.OldRenderLedger then return TML87.OldRenderLedger(self,root,x,y,w,h,accent,guildMode) end; return end
  local st=self:ComputePersonalGoldStats(); local topH=246
  self:DrawLegacyPanel(root,"PersonalGoldStats87",x,y,w,topH,"PERSONAL GOLD LEDGER",accent)
  local bankText=st.bank==nil and "Bank N/A" or TML87.Gold(st.bank)
  local verifiedNet=tonumber(st.verifiedNet24 or ((st.in24 or 0)-(st.out24 or 0))) or 0
  local coverageRaw=tostring(st.coverage or "Need 24H Baseline")
  local hasSnapshot=(st.actualNet24 ~= nil) and not coverageRaw:find("0h",1,true) and coverageRaw ~= "Need 24H Baseline"
  local snapshotText=hasSnapshot and TML87.Gold(st.actualNet24) or "Need 24H Baseline"
  local unmatchedText=hasSnapshot and TML87.Gold(st.unmatched24 or 0) or "N/A"
  local coverage=hasSnapshot and coverageRaw or "Need 24H Baseline"
  local cards={{"Current Gold",TML87.Gold(st.current),C.gold},{"Bank Gold",bankText,C.gold},{"24H Verified In",TML87.Gold(st.in24),VGreen},{"24H Verified Out",TML87.Gold(st.out24),VRed},{"24H Verified Net",TML87.Gold(verifiedNet),verifiedNet>=0 and VGreen or VRed},{"Snapshot Net",snapshotText,hasSnapshot and ((st.actualNet24 or 0)>=0 and VGreen or VRed) or C.yellowDim},{"Unmatched 24H",unmatchedText,C.cyanSoft},{"Coverage",coverage,C.cyanSoft}}
