TML88 = TML88 or {}
function TML88.Now()
  if type(WNow) == "function" then return WNow() end
  if type(GetTimeStamp) == "function" then local ok,v = pcall(GetTimeStamp); if ok and v then return tonumber(v) or 0 end end
  return math.floor(os.time and os.time() or 0)
end
function TML88.Day() return tonumber(WORKING_SECONDS_DAY) or 86400 end
function TML88.DayWindow() return math.floor((TML88.Now() - (10 * 3600)) / TML88.Day()) end
function TML88.Key(v) return string.lower(tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")) end
function TML88.Lower(v) return string.lower(tostring(v or "")) end
function TML88.Gold(n) if type(WFormatGold)=="function" then return WFormatGold(n) end; return tostring(math.floor(tonumber(n) or 0)).."g" end
function TML88.Num(n) if type(WFormatNumber)=="function" then return WFormatNumber(n) end; return tostring(math.floor(tonumber(n) or 0)) end
function TML88.Rel(ts) if type(WRelTime)=="function" then return WRelTime(ts) end; return tostring(ts or "N/A") end
function TML88.Limit(s,n) if type(WLimit)=="function" then return WLimit(s,n) end; s=tostring(s or ""); n=tonumber(n) or 30; return (#s>n) and (s:sub(1,n-3).."...") or s end
function TML88.NA() if type(WNA)=="function" then return WNA() end; return "N/A" end
function TML88.Cell(text,color) if type(VCell)=="function" then return VCell(text,color) end; return tostring(text or "") end
function TML88.ValidTime(ts) ts=tonumber(ts) or 0; local now=TML88.Now(); return ts>0 and ts<=now+300 and ts<4102444800 end
function TML88.Is24(ts) return TML88.ValidTime(ts) and ((TML88.Now()-(tonumber(ts) or 0)) <= TML88.Day()) end

