function TML88.PageDate(self, toolKey)
  if not toolKey or toolKey == "main" then return tostring(self.lastUpdated or TML88.PAGE_UPDATED.main) end
  local map = self.pageUpdated or TML88.PAGE_UPDATED
  return tostring(map[toolKey] or map[tostring(toolKey or "")] or self.lastUpdated or "")
end

function TML88.IsNonDailyQuestName(name)
  local low = TML88.Lower(name)
  local blocked = {"certification", "certified", "training", "introduction", "tutorial", "prologue", "starter"}
  for _,b in ipairs(blocked) do if low:find(b,1,true) then return true end end
  return false
end

function TML88.IsCraftingWrit(name)
  local low = TML88.Lower(name)
  return low:find("writ",1,true) and (low:find("alchemist",1,true) or low:find("blacksmith",1,true) or low:find("clothier",1,true) or low:find("enchant",1,true) or low:find("jewelry",1,true) or low:find("provisioner",1,true) or low:find("woodworker",1,true))
end

function TML88.DailyDefinitions(self)
  local defs = {}
  if self and self.V21684_DailyDefinitions then for _,d in ipairs(self:V21684_DailyDefinitions()) do defs[#defs+1]=d end end
  local extra = {
    {key="zone:vvardenfell",section="Zone / DLC / Chapter",zone="Vvardenfell",focus="Hall of Justice + Ashlander dailies",reward="Motifs / coffers",patterns={"vvardenfell","vivec city","ald'ruhn","ald ruhn"}},
    {key="zone:murkmire",section="Zone / DLC / Chapter",zone="Murkmire",focus="Delve + world boss + Root-Whisper dailies",reward="Coffers / motifs",patterns={"murkmire","lilmoth","bright-throat"}},
    {key="zone:clockwork",section="Zone / DLC / Chapter",zone="Clockwork City",focus="Clockwork City dailies",reward="Coffers / motifs",patterns={"clockwork","brass fortress","slagtown"}},
    {key="zone:necrom",section="Zone / DLC / Chapter",zone="Telvanni / Apocrypha",focus="Necrom dailies + Bastion Nymic",reward="Motifs / coffers",patterns={"necrom","telvanni peninsula","apocrypha","bastion nymic"}},
    {key="zone:goldroad",section="Zone / DLC / Chapter",zone="West Weald / Gold Road",focus="Skingrad dailies",reward="Coffers / motifs",patterns={"west weald","gold road","skingrad"}},
    {key="skill:crafting_writs",section="Skill-Line / Guild",zone="Crafting Writs",focus="Daily crafting writs",reward="Writ rewards",patterns={"alchemist writ","blacksmith writ","clothier writ","enchanter writ","enchanting writ","jewelry crafting writ","provisioner writ","woodworker writ"}},
  }
  local seen={}
  for _,d in ipairs(defs) do seen[tostring(d.key or "")]=true end
  for _,d in ipairs(extra) do if not seen[tostring(d.key or "")] then defs[#defs+1]=d; seen[tostring(d.key or "")]=true end end
  return defs
end

function TML88.EnsureDailyStore(self)
  self.saved = self.saved or self:Defaults()
  self.saved.scanStatus = self.saved.scanStatus or {}
  self.saved.dailyFilter = self.saved.dailyFilter or "All"
  self.saved.dailyScan = self.saved.dailyScan or { quests={}, questByKey={}, lastScan=0, journalCount=0, active=0, ready=0, review=0, repeatable=0, metaSaved=0, completedMerged=0, excluded=0 }
  self.saved.dailyCompleted = self.saved.dailyCompleted or { window=TML88.DayWindow(), keys={}, quests={}, byName={} }
  if self.saved.dailyCompleted.window ~= TML88.DayWindow() then
    self.saved.dailyCompleted = { window=TML88.DayWindow(), keys={}, quests={}, byName={} }
    self.saved.scanStatus.daily = "Daily reset detected - completed-today cache cleared. Press Scan Dailies."
  end
  self.saved.dailyCompleted.keys = self.saved.dailyCompleted.keys or {}
  self.saved.dailyCompleted.quests = self.saved.dailyCompleted.quests or {}
  self.saved.dailyCompleted.byName = self.saved.dailyCompleted.byName or {}
  self.saved.dailyQuestMeta = self.saved.dailyQuestMeta or {}
  self.saved.dailyManual = {}
  for k,v in pairs(self.saved.dailyCompleted.keys or {}) do if v and v.manual then self.saved.dailyCompleted.keys[k]=nil end end
end

function TML88.GetRepeatType(index)
  if type(GetJournalQuestRepeatType)=="function" then local ok,rt=pcall(GetJournalQuestRepeatType,index); if ok then return rt end end
  return nil
end
function TML88.IsDailyRepeatType(rt)
  if rt == nil then return false end
  if _G.QUEST_REPEAT_DAILY ~= nil and rt == _G.QUEST_REPEAT_DAILY then return true end
  if _G.QUEST_REPEAT_REPEATABLE ~= nil and rt == _G.QUEST_REPEAT_REPEATABLE then return true end
  if _G.QUEST_REPEAT_DAILY_REPEATABLE ~= nil and rt == _G.QUEST_REPEAT_DAILY_REPEATABLE then return true end
  if type(rt)=="number" then return rt ~= 0 end
  return tostring(rt) ~= "" and tostring(rt) ~= "0"
end
function TML88.IsJournalQuestDaily(index)
  local rt=TML88.GetRepeatType(index)
  if TML88.IsDailyRepeatType(rt) then return true,rt end
  if type(IsJournalQuestRepeatable)=="function" then local ok,v=pcall(IsJournalQuestRepeatable,index); if ok and v==true then return true,rt end end
  return false,rt
end
function TML88.GetLocation(index)
  local parts={}
  if type(GetJournalQuestLocationInfo)=="function" then local vals={pcall(GetJournalQuestLocationInfo,index)}; if vals[1] then for i=2,#vals do if type(vals[i])=="string" and vals[i]~="" then parts[#parts+1]=vals[i] end end end end
  return table.concat(parts," ")
end
function TML88.GetJournalQuest(index)
  if type(GetJournalQuestInfo)~="function" then return nil end
  local vals={pcall(GetJournalQuestInfo,index)}; if not vals[1] then return nil end
  local name=vals[2]; if not name or name=="" then return nil end
  local textParts={}; local complete=false
  for i=2,#vals do
    if type(vals[i])=="string" and vals[i]~="" then textParts[#textParts+1]=vals[i] end
    if type(vals[i])=="boolean" and vals[i]==true and i>=5 then complete=true end
  end
  if type(IsJournalQuestComplete)=="function" then local ok,v=pcall(IsJournalQuestComplete,index); if ok then complete=(v==true) end end
  local daily,rt=TML88.IsJournalQuestDaily(index)
  local loc=TML88.GetLocation(index)
  return {index=index,name=tostring(name),text=table.concat(textParts," "),zone=loc,complete=complete,daily=daily,repeatType=rt}
end
function TML88.DefFromQuest(self,q)
  if not q or not q.name then return nil end
  if TML88.IsNonDailyQuestName(q.name) then return nil,"excluded" end
  local hay=TML88.Lower(tostring(q.name or "").." "..tostring(q.text or "").." "..tostring(q.zone or ""))
  if TML88.IsCraftingWrit(q.name) then return {key="craft:"..TML88.Key(q.name),section="Skill-Line / Guild",zone="Crafting Writs",focus=q.name,reward="Writ rewards",patterns={}} end
  for _,def in ipairs(TML88.DailyDefinitions(self)) do for _,pat in ipairs(def.patterns or {}) do if hay:find(TML88.Lower(pat),1,true) then return def end end end
  local z=tostring(q.zone or ""); if z=="" then z="Journal Daily" end
  local section="Journal Repeatable"
  return {key="journal:"..TML88.Key(q.name),section=section,zone=z,focus=q.name,reward="Quest reward",patterns={}}
end
function TML88.MetaFromDef(def, questName)
  if not def or not def.key then return nil end
  return {key=tostring(def.key),name=tostring(questName or def.focus or def.zone or def.key),section=def.section,zone=def.zone,focus=def.focus or questName,reward=def.reward or "Quest reward",timestamp=TML88.Now(),manual=false}
end
function TML88.SaveQuestMeta(self, questName, def)
  if not questName or not def or not def.key then return end
  self.saved.dailyQuestMeta = self.saved.dailyQuestMeta or {}
  local meta=TML88.MetaFromDef(def, questName)
  if meta then self.saved.dailyQuestMeta[TML88.Key(questName)] = meta end
end
function TML88.MarkCompleted(self, questName, def, source)
  self:EnsureDataDefaults(); TML88.EnsureDailyStore(self)
  local nameKey=TML88.Key(questName)
  local meta=(self.saved.dailyQuestMeta or {})[nameKey]
  if meta and meta.key then def={key=meta.key,section=meta.section,zone=meta.zone,focus=meta.focus,reward=meta.reward} end
  def=def or TML88.DefFromQuest(self,{name=questName,text="",zone=""})
  if not def or not def.key then return false end
  if self.saved.dailyCompleted.window ~= TML88.DayWindow() then self.saved.dailyCompleted={window=TML88.DayWindow(),keys={},quests={},byName={}} end
  local key=tostring(def.key); local row=TML88.MetaFromDef(def,questName); if not row then return false end
  row.source=source or "event"
  self.saved.dailyCompleted.keys[key]=row
  self.saved.dailyCompleted.quests[nameKey]=key
  self.saved.dailyCompleted.byName[nameKey]=row
  return true
end
function TML88.StatusForDef(self,def)
  self:EnsureDataDefaults(); TML88.EnsureDailyStore(self)
  local key=tostring(def and def.key or "")
  if self.saved.dailyCompleted and self.saved.dailyCompleted.keys and self.saved.dailyCompleted.keys[key] then return "Completed Today" end
  local q=self.saved.dailyScan and self.saved.dailyScan.questByKey and self.saved.dailyScan.questByKey[key]
  if q then return q.status or "Active" end
  return "Not Seen / Unknown"
end
function TML88.IncludeDaily(filter,section,status)
  filter=tostring(filter or "All")
  if filter=="All" then return true end
  if filter=="Zone" then return section=="Zone / DLC / Chapter" or section=="PvP" or section=="Journal Repeatable" end
  if filter=="Skill/Guild" then return section=="Skill-Line / Guild" end
  if filter=="Active/Ready" then return status=="Active" or status=="Ready to Turn In" end
  if filter=="Completed" then return status=="Completed Today" end
  if filter=="Unknown" then return status=="Not Seen / Unknown" end
  return true
end
function TML:ScanDailyQuests(noRender)
  self:EnsureDataDefaults(); TML88.EnsureDailyStore(self)
  self.saved.dailyScan={quests={},questByKey={},lastScan=TML88.Now(),journalCount=0,active=0,ready=0,review=0,repeatable=0,metaSaved=0,completedMerged=0,excluded=0}
  local scanned,active,ready,review,repeatable,excluded,metaSaved=0,0,0,0,0,0,0
  if type(GetNumJournalQuests)=="function" then
    local ok,n=pcall(GetNumJournalQuests); n=ok and (tonumber(n) or 0) or 0
    for i=1,n do
      local q=TML88.GetJournalQuest(i)
      if q and q.daily then
        repeatable=repeatable+1
        local def,reason=TML88.DefFromQuest(self,q)
        if reason=="excluded" then excluded=excluded+1
        elseif def and def.key then
          TML88.SaveQuestMeta(self,q.name,def); metaSaved=metaSaved+1
          local status=q.complete and "Ready to Turn In" or "Active"
          if q.complete then ready=ready+1 else active=active+1 end
          local row={key=def.key,name=q.name,section=def.section,zone=def.zone,focus=def.focus or q.name,reward=def.reward or "Quest reward",status=status,timestamp=TML88.Now(),journalIndex=i,repeatType=q.repeatType}
          self.saved.dailyScan.quests[#self.saved.dailyScan.quests+1]=row
          self.saved.dailyScan.questByKey[def.key]=row
          scanned=scanned+1
        else review=review+1 end
      end
    end
  end
  local captured=0; for _ in pairs((self.saved.dailyCompleted and self.saved.dailyCompleted.keys) or {}) do captured=captured+1 end
  self.saved.dailyScan.journalCount=scanned; self.saved.dailyScan.active=active; self.saved.dailyScan.ready=ready; self.saved.dailyScan.review=review; self.saved.dailyScan.repeatable=repeatable; self.saved.dailyScan.metaSaved=metaSaved; self.saved.dailyScan.completedMerged=captured; self.saved.dailyScan.excluded=excluded
  self.saved.scanStatus.daily="Scan complete: "..scanned.." journal dailies / "..active.." active / "..ready.." ready / "..captured.." completed retained / "..excluded.." excluded. Rescan keeps completed cache until daily reset."
  if not noRender then self:RenderTool("daily_quests") end
  return scanned
end
function TML:GetDailyRows()
  self:EnsureDataDefaults(); TML88.EnsureDailyStore(self)
  local filter=self.saved.dailyFilter or "All"; local rows,seen={},{}
  for _,def in ipairs(TML88.DailyDefinitions(self)) do
    local status=TML88.StatusForDef(self,def)
    if TML88.IncludeDaily(filter,def.section,status) then local r={def.section,def.zone,def.focus,def.reward,status,"Daily 10:00 UTC"}; r.__key=def.key; r.__status=status; r.__section=def.section; rows[#rows+1]=r end
    seen[def.key]=true
  end
  -- Merge retained completed-today cache after every journal scan; never wipe it during Scan Dailies.
  for key,comp in pairs((self.saved.dailyCompleted and self.saved.dailyCompleted.keys) or {}) do
    if not seen[key] then
      local status="Completed Today"; local section=comp.section or "Journal Repeatable"
      if TML88.IncludeDaily(filter,section,status) then local r={section,comp.zone or comp.name or key,comp.focus or comp.name or "Captured daily quest",comp.reward or "Quest reward",status,"Daily 10:00 UTC"}; r.__key=key; r.__status=status; r.__section=section; rows[#rows+1]=r end
      seen[key]=true
    end
  end
  for _,q in ipairs((self.saved.dailyScan and self.saved.dailyScan.quests) or {}) do
    if q.key and not seen[q.key] then
      seen[q.key]=true; local status=q.status or "Active"
      if TML88.IncludeDaily(filter,q.section,status) then local r={q.section or "Journal Repeatable",q.zone or q.name or q.key,q.focus or q.name or "Active daily",q.reward or "Quest reward",status,"Daily 10:00 UTC"}; r.__key=q.key; r.__status=status; r.__section=q.section; rows[#rows+1]=r end
    end
  end
  table.sort(rows,function(a,b) local o={ ["Completed Today"]=1,["Ready to Turn In"]=2,["Active"]=3,["Not Seen / Unknown"]=4 }; local av,bv=(o[a.__status or ""] or 9),(o[b.__status or ""] or 9); if av~=bv then return av<bv end; return tostring(a[2] or "")<tostring(b[2] or "") end)
  self.lastDailyRows88=rows; self.lastDailyRows87=rows; return rows
end
function TML:CycleDailyFilter()
  self:EnsureDataDefaults(); local list={"All","Zone","Skill/Guild","Active/Ready","Completed","Unknown"}; local cur=self.saved.dailyFilter or list[1]; local idx=1
  for i,v in ipairs(list) do if v==cur then idx=i end end
  self.saved.dailyFilter=list[(idx % #list)+1]; self:RenderTool("daily_quests")
end
function TML:V21688_CaptureCompletedDaily(questName,source)
  if not questName or tostring(questName)=="" then return false end
  if TML88.IsNonDailyQuestName(questName) then return false end
  self:EnsureDataDefaults(); TML88.EnsureDailyStore(self)
