-- Reinstall daily completion events so the new retained cache/classifier is used.
TML88.OldInstall = TML.InstallEventPipelines
function TML:InstallEventPipelines()
  if TML88.OldInstall then TML88.OldInstall(self) end
  if EVENT_MANAGER and EVENT_MANAGER.UnregisterForEvent then
    if _G.EVENT_QUEST_COMPLETE then EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestComplete87", EVENT_QUEST_COMPLETE); EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestComplete88", EVENT_QUEST_COMPLETE) end
    if _G.EVENT_QUEST_REMOVED then EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestRemoved87", EVENT_QUEST_REMOVED); EVENT_MANAGER:UnregisterForEvent(self.name.."DailyQuestRemoved88", EVENT_QUEST_REMOVED) end
  end
  if EVENT_MANAGER and _G.EVENT_QUEST_COMPLETE then
    EVENT_MANAGER:RegisterForEvent(self.name.."DailyQuestComplete88", EVENT_QUEST_COMPLETE, function(eventCode,...)
      local args={...}; local questName=nil
      for _,v in ipairs(args) do if type(v)=="string" and v~="" then questName=v; break end end
      if questName and TML and TML.V21688_CaptureCompletedDaily then TML:V21688_CaptureCompletedDaily(questName,"complete") end
    end)
  end
  if EVENT_MANAGER and _G.EVENT_QUEST_REMOVED then
    EVENT_MANAGER:RegisterForEvent(self.name.."DailyQuestRemoved88", EVENT_QUEST_REMOVED, function(eventCode,...)
      local args={...}; local questName=nil; local completed=false
      for _,v in ipairs(args) do if type(v)=="string" and v~="" and not questName then questName=v elseif type(v)=="boolean" and v==true then completed=true end end
      if completed and questName and TML and TML.V21688_CaptureCompletedDaily then TML:V21688_CaptureCompletedDaily(questName,"removed") end
    end)
  end
end

