-- Personal Gold Ledger: retain rows across scans and show all-time verified totals separately from 24H snapshot math.
TML88.OldScanPersonalGoldLedger = TML.ScanPersonalGoldLedger
function TML:ScanPersonalGoldLedger()
  self:EnsureDataDefaults()
  local existing=self.saved.personalGoldEvents or {}
  if TML88.OldScanPersonalGoldLedger then TML88.OldScanPersonalGoldLedger(self) end
  local merged={}
  for k,v in pairs(existing) do merged[k]=v end
  for k,v in pairs(self.saved.personalGoldEvents or {}) do merged[k]=v end
  self.saved.personalGoldEvents=merged
  local count=0; for _ in pairs(merged) do count=count+1 end
  self.saved.personalGoldTotals=self.saved.personalGoldTotals or {}; self.saved.personalGoldTotals.retained=count
  self.saved.scanStatus.personalGold=(self.saved.scanStatus.personalGold or "Refresh complete").." / Retained all-time rows: "..tostring(count).."."
end
function TML:ComputePersonalGoldStats()
  self:EnsureDataDefaults()
  local st={current=tonumber(self:GetCarriedGoldLive()) or 0,bank=tonumber(self:GetBankGoldLive()),in24=0,out24=0,verifiedNet24=0,net24=0,allIn=0,allOut=0,allNet=0,actualNet24=nil,unmatched24=nil,coverage="Need 24H Baseline",scanned=(self.saved.scanStatus and self.saved.scanStatus.personalGold~=nil)}
  local rows=self:GetPersonalGoldRows("Recent") or {}
  for _,e in ipairs(rows) do
    local amt=tonumber(e.amount) or 0
    if e.direction=="in" then st.allIn=st.allIn+amt; if TML88.Is24(e.timestamp) then st.in24=st.in24+amt end
    elseif e.direction=="out" then st.allOut=st.allOut+amt; if TML88.Is24(e.timestamp) then st.out24=st.out24+amt end end
  end
  st.verifiedNet24=st.in24-st.out24; st.net24=st.verifiedNet24; st.allNet=st.allIn-st.allOut
  local total=st.current+(st.bank or 0); local hist=self.saved.goldSnapshots and self.saved.goldSnapshots.history or {}; local target=TML88.Now()-TML88.Day(); local base=nil; local earliest=nil
  for _,s in ipairs(hist) do if tonumber(s.total) and tonumber(s.timestamp) then if not earliest or (tonumber(s.timestamp) or 0)<(tonumber(earliest.timestamp) or 0) then earliest=s end; if (tonumber(s.timestamp) or 0)<=target and ((not base) or (tonumber(s.timestamp) or 0)>(tonumber(base.timestamp) or 0)) then base=s end end end
  if base then st.actualNet24=total-(tonumber(base.total) or 0); st.coverage="Full 24H" elseif earliest and (TML88.Now()-(tonumber(earliest.timestamp) or 0))>3600 then local hours=math.floor((TML88.Now()-(tonumber(earliest.timestamp) or 0))/3600); if hours>0 then st.actualNet24=total-(tonumber(earliest.total) or 0); st.coverage="Partial "..tostring(hours).."h" end end
  if st.actualNet24 ~= nil then st.unmatched24=st.actualNet24-st.verifiedNet24 end
  return st
end
