-- Built from v2.0.16.88 rollback line. No menu/scene/input registration changes.
TML89 = _G.TML89 or {}
_G.TML89 = TML89
TML89.VERSION = "2.0.16.90"
TML89.ADDON_VERSION = 21690
TML89.UPDATED = "06/22/2026 21:25 UTC"
TML89.DAY = 86400
TML89.PAGE_UPDATED = {main=TML89.UPDATED,personal_sales="06/22/2026",gold_ledger_personal="06/22/2026",net_worth="06/22/2026",fishing="06/22/2026",daily_tracker="06/22/2026"}
function TML89_Now() return (GetTimeStamp and GetTimeStamp()) or os.time() end
function TML89_Lower(s) return string.lower(tostring(s or "")) end
function TML89_UserKey(s) return TML89_Lower((tostring(s or "")):gsub("^%s+",""):gsub("%s+$","")) end
function TML89_SameUser(a,b) return TML89_UserKey(a) ~= "" and TML89_UserKey(a) == TML89_UserKey(b) end
function TML89_Is24(ts) ts=tonumber(ts) or 0; return ts>0 and (TML89_Now()-ts)<=TML89.DAY end
function TML89_Count(t) local n=0; for _ in pairs(t or {}) do n=n+1 end; return n end
function TML89_Gold(v) return WFormatGold and WFormatGold(tonumber(v) or 0) or tostring(tonumber(v) or 0).."g" end
function TML89_Num(v) return WFormatNumber and WFormatNumber(tonumber(v) or 0) or tostring(tonumber(v) or 0) end
function TML89_Limit(s,n) return WLimit and WLimit(s,n) or tostring(s or "") end
function TML89_Cell(t,c) return VCell and VCell(t,c) or tostring(t or "") end
function TML89_Rel(ts) return WRelTime and WRelTime(ts) or tostring(ts or "") end
function TML89_NA() return WNA and WNA() or "N/A" end

function TML:V21689_EnsurePersonalLedgerCore()
  self:EnsureDataDefaults()
  self.saved.retainedSalesEvents = self.saved.retainedSalesEvents or {}
  self.saved.retainedPersonalGoldEvents = self.saved.retainedPersonalGoldEvents or {}
  self.saved.currentScan = self.saved.currentScan or {}
  self.saved.currentScan.sales = self.saved.currentScan.sales or {}
  self.saved.currentScan.personalGold = self.saved.currentScan.personalGold or {}
  self.saved.ledgerMeta = self.saved.ledgerMeta or {}
  self.saved.ledgerMeta.sales = self.saved.ledgerMeta.sales or {currentRows=0,newRows=0,updatedRows=0,retainedRows=0,reviewRows=0}
  self.saved.ledgerMeta.personalGold = self.saved.ledgerMeta.personalGold or {currentRows=0,newRows=0,updatedRows=0,retainedRows=0,reviewRows=0}
  for k,e in pairs(self.saved.salesEvents or {}) do if type(e)=="table" then self.saved.retainedSalesEvents[tostring(k)] = e end end
  for k,e in pairs(self.saved.personalGoldEvents or {}) do if type(e)=="table" then self.saved.retainedPersonalGoldEvents[tostring(k)] = e end end
  self.saved.salesEvents = self.saved.retainedSalesEvents
  self.saved.personalGoldEvents = self.saved.retainedPersonalGoldEvents
end

function TML89_ParseTrader(vals)
  local eventId,timestamp,isRedacted,eventType,seller,buyer,itemLink,quantity,price,tax = vals[1],vals[2],vals[3],vals[4],vals[5],vals[6],vals[7],vals[8],vals[9],vals[10]
  local strings,nums={},{}
  for _,v in ipairs(vals or {}) do if type(v)=="string" then strings[#strings+1]=v elseif type(v)=="number" then nums[#nums+1]=v end end
  if not itemLink or itemLink=="" then for _,s in ipairs(strings) do if tostring(s):find("|H",1,true) then itemLink=s; break end end end
  if not seller or seller=="" then for _,s in ipairs(strings) do if s~=itemLink and (s:sub(1,1)=="@" or not s:find("|H",1,true)) then seller=s; break end end end
  if not buyer or buyer=="" then for _,s in ipairs(strings) do if s~=itemLink and s~=seller and (s:sub(1,1)=="@" or not s:find("|H",1,true)) then buyer=s; break end end end
  if not timestamp or tonumber(timestamp)==0 then for _,n in ipairs(nums) do if n>1000000000 and n<4102444800 then timestamp=n; break end end end
  if not price or tonumber(price)==0 then local maxPrice=0; for _,n in ipairs(nums) do if n>maxPrice and not (tonumber(timestamp) and n==tonumber(timestamp)) then maxPrice=n end end; if maxPrice>0 then price=maxPrice end end
  quantity=tonumber(quantity) or 1; if quantity<=0 or quantity>200000 then quantity=1 end
  return eventId,timestamp,isRedacted,eventType,seller,buyer,itemLink,quantity,price,tax
end
function TML89_Fee(gross) gross=tonumber(gross) or 0; return math.floor(gross*0.07+0.5) end
function TML89_GuildTax(gross) gross=tonumber(gross) or 0; return math.floor(gross*0.035+0.5) end
function TML89_SaleKey(guildId,eventId,seller,gross,timestamp,itemLink,quantity)
  if eventId and tostring(eventId)~="" and tostring(eventId)~="0" then return "sale:"..tostring(guildId)..":event:"..tostring(eventId) end
  return table.concat({"sale",tostring(guildId or 0),TML89_UserKey(seller),tostring(tonumber(gross) or 0),tostring(tonumber(timestamp) or 0),tostring(itemLink or ""),tostring(tonumber(quantity) or 1)},":")
end
function TML89_AddSale(self,guildId,eventId,seller,gross,timestamp,itemLink,quantity,tax,current)
  self:V21689_EnsurePersonalLedgerCore()
  gross=tonumber(gross) or 0; if gross<=0 then return false,false,"bad amount" end
  local ts=tonumber(timestamp) or 0; local review=false; if ts<=0 then ts=TML89_Now(); review=true end
  local qty=tonumber(quantity) or 1; if qty<=0 then qty=1 end
  local fee=TML89_Fee(gross); local net=math.max(0,gross-fee); local guildTax=tonumber(tax) or TML89_GuildTax(gross)
  local key=TML89_SaleKey(guildId,eventId,seller,gross,ts,itemLink,qty); local existed=self.saved.retainedSalesEvents[key] ~= nil
  self.saved.retainedSalesEvents[key]={key=key,guildId=guildId,seller=seller or TML89_NA(),amount=net,netAmount=net,grossAmount=gross,feeAmount=fee,guildTax=guildTax,tax=guildTax,feeAdjusted=true,timestamp=ts,itemLink=itemLink,itemName=(WGetItemName and WGetItemName(itemLink)) or tostring(itemLink or "Sale"),quantity=qty,review=review}
  if current then self.saved.currentScan.sales[key]=true end
  self.saved.salesEvents=self.saved.retainedSalesEvents
  return not existed,existed,nil
end

function TML:ScanGuildSales(g,noRender,noReset)
  self:V21689_EnsurePersonalLedgerCore(); if not g or not g.id or g.id==0 then return 0 end; if not noReset then self.saved.currentScan.sales={} end
  local cat=self:GetHistoryCategory("trader"); if type(GetGuildHistoryTraderEventInfo)~="function" or not cat then self.saved.scanStatus.sales="Sales history API unavailable"; return 0 end
  local newest,oldest=self:GetHistoryIndices(g.id,cat,WORKING_HISTORY_DAYS); local scanned,accepted,newRows,updatedRows,review=0,0,0,0,0
  if oldest>=newest then
    for i=newest,oldest do
      local vals={pcall(GetGuildHistoryTraderEventInfo,g.id,i)}; local ok=table.remove(vals,1)
      if ok then
        local eventId,timestamp,isRedacted,eventType,seller,buyer,itemLink,quantity,price,tax=TML89_ParseTrader(vals)
        if not isRedacted and seller and tonumber(price) and tonumber(price)>0 then scanned=scanned+1; local added,existed=TML89_AddSale(self,g.id,eventId or i,seller,price,timestamp,itemLink,quantity,tax,true); if added or existed then accepted=accepted+1 end; if added then newRows=newRows+1 elseif existed then updatedRows=updatedRows+1 end else review=review+1 end
      else review=review+1 end
    end
  end
  if self.RequestHistory then self:RequestHistory(g.id,cat,WORKING_HISTORY_DAYS) end; if self.RebuildPriceCacheFromSales then self:RebuildPriceCacheFromSales() end
  self.saved.ledgerMeta.sales={currentRows=accepted,newRows=newRows,updatedRows=updatedRows,retainedRows=TML89_Count(self.saved.retainedSalesEvents),reviewRows=review,lastGuild=tostring(g.name or g.id),lastScan=TML89_Now()}
  self.saved.scanStatus.sales="Current scan for "..tostring(g.name or "guild")..": "..tostring(accepted).." rows seen / "..tostring(newRows).." new / "..tostring(TML89_Count(self.saved.retainedSalesEvents)).." all-time loaded retained."
  if not noRender then self:RenderTool(self.state.activeTool or "guild_sales") end
  return accepted
end
function TML:ScanSelectedGuildSales(noRender) local n=self:ScanGuildSales(self:GetGuild(),true,false); if not noRender then self:RenderTool(self.state.activeTool or "guild_sales") end; return n end
function TML:ScanAllGuildSales(noRender)
  self:V21689_EnsurePersonalLedgerCore(); self.saved.currentScan.sales={}; local total,nguild,newRows,review=0,0,0,0
  self:EachGuild(function(g) nguild=nguild+1; local before=TML89_Count(self.saved.retainedSalesEvents); local raw=self:ScanGuildSales(g,true,true); local n=tonumber(raw) or 0; total=total+n; local after=TML89_Count(self.saved.retainedSalesEvents); if after>before then newRows=newRows+(after-before) end; local m=self.saved.ledgerMeta and self.saved.ledgerMeta.sales or {}; review=review+(tonumber(m.reviewRows) or 0) end)
  local personalAll=self:GetSalesRows(0,true); local personal24=self:GetSalesRows24H(0,true)
  self.saved.ledgerMeta.sales={currentRows=total,newRows=newRows,updatedRows=math.max(0,total-newRows),retainedRows=TML89_Count(self.saved.retainedSalesEvents),reviewRows=review,guilds=nguild,personalAllRows=#personalAll,personal24Rows=#personal24,lastScan=TML89_Now()}
  self.saved.scanStatus.sales="Current scan: "..tostring(total).." guild sale rows across "..tostring(nguild).." guilds / "..tostring(newRows).." new. Your @UserID: "..tostring(#personalAll).." all-time loaded / "..tostring(#personal24).." 24H."
  if not noRender then self:RenderTool(self.state.activeTool or "personal_sales") end; return total
end
function TML:ScanPersonalSales(noRender)
  local current=self:ScanAllGuildSales(true); local rows=self:GetSalesRows(0,true); local rows24=self:GetSalesRows24H(0,true); local m=self.saved.ledgerMeta.sales or {}
  self.saved.scanStatus.sales="Personal scan: current scan saw "..tostring(current).." guild sale rows. Your @UserID retained: "..tostring(#rows).." all-time loaded / "..tostring(#rows24).." 24H / "..tostring(tonumber(m.newRows) or 0).." new rows."
  if not noRender then self:RenderTool("personal_sales") end; return #rows
end
function TML:GetSalesRows(guildId,onlyMe)
  self:V21689_EnsurePersonalLedgerCore(); local rows={}; local my=TML89_UserKey(self:GetUserDisplayName())
  for _,e in pairs(self.saved.retainedSalesEvents or self.saved.salesEvents or {}) do if type(e)=="table" then if V21669_NormalizeSaleRow then V21669_NormalizeSaleRow(e) end; local okGuild=(not guildId or guildId==0 or e.guildId==guildId); local okUser=(not onlyMe) or (TML89_UserKey(e.seller)==my); if okGuild and okUser then rows[#rows+1]=e end end end
  table.sort(rows,function(a,b) return (tonumber(a.timestamp) or 0)>(tonumber(b.timestamp) or 0) end); return rows
end
function TML:GetSalesRows24H(guildId,onlyMe) local out={}; for _,e in ipairs(self:GetSalesRows(guildId,onlyMe)) do if TML89_Is24(e.timestamp) then out[#out+1]=e end end; return out end
function TML:ComputeSalesStats(guildId,onlyMe)
  local rows=self:GetSalesRows(guildId,onlyMe); local st={sales24=0,salesToday=0,totalSales=0,allTimeSales=0,items=0,tax=0,fees=0,gross=0,net=0,topEarner=TML89_NA(),topAmount=0,deltaPct=nil,rowCount=#rows,review=0,currentRows=(self.saved and self.saved.ledgerMeta and self.saved.ledgerMeta.sales and self.saved.ledgerMeta.sales.currentRows) or 0}; local sellers={}
  for _,e in ipairs(rows) do local net=tonumber(e.netAmount or e.amount) or 0; local gross=tonumber(e.grossAmount) or net; local guildTax=tonumber(e.guildTax or e.tax) or TML89_GuildTax(gross); local fee=tonumber(e.feeAmount) or TML89_Fee(gross); if TML89_Is24(e.timestamp) then st.sales24=st.sales24+net; st.salesToday=st.salesToday+net end; st.totalSales=st.totalSales+net; st.allTimeSales=st.allTimeSales+net; st.gross=st.gross+gross; st.fees=st.fees+fee; st.tax=st.tax+guildTax; st.net=st.net+net; st.items=st.items+(tonumber(e.quantity) or 1); if e.review then st.review=st.review+1 end; local u=e.seller or TML89_NA(); sellers[u]=(sellers[u] or 0)+net end
  for u,v in pairs(sellers) do if v>st.topAmount then st.topAmount=v; st.topEarner=u end end; if st.totalSales>0 then st.deltaPct=(st.sales24/st.totalSales)*100 end; return st
end
function TML:GetPersonalSalesGuildBreakdown()
  local by={}; for _,e in ipairs(self:GetSalesRows(0,true)) do local g=self:GetGuildName(e.guildId); local r=by[g] or {guild=g,net=0,net24=0,items=0,highest=0,status="Loaded"}; local net=tonumber(e.netAmount or e.amount) or 0; r.net=r.net+net; r.items=r.items+(tonumber(e.quantity) or 1); if net>r.highest then r.highest=net end; if TML89_Is24(e.timestamp) then r.net24=r.net24+net end; by[g]=r end
  local rows={}; for _,r in pairs(by) do rows[#rows+1]=r end; table.sort(rows,function(a,b) return (a.net or 0)>(b.net or 0) end); return rows
end
function TML:GetPersonalTopSellerRows()
  local by={}; for _,e in ipairs(self:GetSalesRows(0,true)) do local k=tostring(e.itemLink or e.itemName or "Unknown"); local r=by[k] or {itemLink=e.itemLink,itemName=e.itemName,guild=e.guildId,qty=0,gold=0,avg=0,count=0}; local q=tonumber(e.quantity) or 1; local net=tonumber(e.netAmount or e.amount) or 0; r.qty=r.qty+q; r.gold=r.gold+net; r.count=r.count+1; r.avg=math.floor(r.gold/math.max(1,r.qty)); by[k]=r end
  local rows={}; for _,r in pairs(by) do rows[#rows+1]=r end; table.sort(rows,function(a,b) return (a.gold or 0)>(b.gold or 0) end); return rows
end

function TML89_PersonalGoldKey(prefix,guildId,timestamp,amount,direction,extra) return table.concat({"pg",tostring(prefix or "event"),tostring(guildId or 0),tostring(tonumber(timestamp) or 0),tostring(tonumber(amount) or 0),tostring(direction or "in"),tostring(extra or "")},":") end
function TML89_AddPersonalGold(self,key,row,current)
  self:V21689_EnsurePersonalLedgerCore(); if not row or (tonumber(row.amount) or 0)<=0 then return false,false end
  local existed=self.saved.retainedPersonalGoldEvents[key] ~= nil; row.key=key; row.timestamp=tonumber(row.timestamp) or TML89_Now(); row.user=row.user or self:GetUserDisplayName(); row.direction=row.direction or "in"; row.source=row.source or "Personal Gold"; row.note=row.note or row.source
  self.saved.retainedPersonalGoldEvents[key]=row; if current then self.saved.currentScan.personalGold[key]=true end; self.saved.personalGoldEvents=self.saved.retainedPersonalGoldEvents; return not existed,existed
end
function TML:ScanPersonalGoldLedger()
  self:V21689_EnsurePersonalLedgerCore(); self.saved.currentScan.personalGold={}; self.saved.goldSnapshots=self.saved.goldSnapshots or {}; self.saved.goldSnapshots.history=self.saved.goldSnapshots.history or {}
  local carried=tonumber(self:GetCarriedGoldLive()) or 0; local bank=tonumber(self:GetBankGoldLive()) or nil; local total=carried+(bank or 0); local now=TML89_Now(); table.insert(self.saved.goldSnapshots.history,{carriedGold=carried,bankedGold=bank,total=total,timestamp=now}); while #self.saved.goldSnapshots.history>72 do table.remove(self.saved.goldSnapshots.history,1) end; self.saved.goldSnapshots.personalLast={carriedGold=carried,bankedGold=bank,total=total,timestamp=now}
  local rawSales=self:ScanAllGuildSales(true); local currentSales=tonumber(rawSales) or 0; local guildGoldSeen=0; self:EachGuild(function(g) if self.ScanGuildGold then local rawGold=self:ScanGuildGold(g); guildGoldSeen=guildGoldSeen+(tonumber(rawGold) or 0) end end)
  local my=self:GetUserDisplayName(); local added,updated,review=0,0,0
  for sk,s in pairs(self.saved.retainedSalesEvents or {}) do if type(s)=="table" and TML89_SameUser(s.seller,my) then local amt=tonumber(s.netAmount or s.amount) or 0; local key=TML89_PersonalGoldKey("sale",s.guildId,s.timestamp,amt,"in",sk); local cur=(self.saved.currentScan.sales or {})[sk] == true; local isNew,isOld=TML89_AddPersonalGold(self,key,{timestamp=s.timestamp,user=my,source="Guild Trader Sale",amount=amt,direction="in",note=self:GetGuildName(s.guildId),guildId=s.guildId,sourceKey=sk},cur); if isNew then added=added+1 elseif isOld and cur then updated=updated+1 end end end
  for _,e in pairs(self.saved.guildGoldEvents or {}) do if type(e)=="table" and TML89_SameUser(e.user,my) then local b=tostring(e.bucket or ""); local amt=tonumber(e.amount) or 0; local dir=nil; local source=nil; local note=b; if e.action=="deposit" and (b=="Donation" or b=="Ticket" or b=="Giveaway Ticket" or b=="Reset") then dir="out"; source="Guild Bank Deposit" elseif e.action=="withdraw" and (b=="Withdrawal" or b=="Other / Review" or b=="Withdraw") then dir="in"; source="Guild Bank Withdrawal" else review=review+1 end; if dir and amt>0 then local key=TML89_PersonalGoldKey("guildgold",e.guildId,e.timestamp,amt,dir,tostring(b)..":"..tostring(e.user)); local isNew,isOld=TML89_AddPersonalGold(self,key,{timestamp=e.timestamp,user=my,source=source,amount=amt,direction=dir,note=note,guildId=e.guildId},true); if isNew then added=added+1 elseif isOld then updated=updated+1 end end end end
  local retained=TML89_Count(self.saved.retainedPersonalGoldEvents); local current=TML89_Count(self.saved.currentScan.personalGold); self.saved.ledgerMeta.personalGold={currentRows=current,newRows=added,updatedRows=updated,retainedRows=retained,reviewRows=review,lastScan=now,salesRows=currentSales,guildGoldRows=guildGoldSeen}; self.saved.scanStatus.personalGold="Current scan: "..tostring(current).." personal gold rows seen / "..tostring(added).." new / "..tostring(retained).." all-time loaded retained / "..tostring(review).." review."; if self.MarkScanned then self:MarkScanned(current>0 and "Scanned" or "No New Rows", current>0) end
end
function TML:GetPersonalGoldRows(filter)
  self:V21689_EnsurePersonalLedgerCore(); local rows={}; filter=filter or self.saved.personalGoldFilter or "Recent"
  for _,e in pairs(self.saved.retainedPersonalGoldEvents or self.saved.personalGoldEvents or {}) do if type(e)=="table" then if filter=="Gold In" then if e.direction=="in" then rows[#rows+1]=e end elseif filter=="Gold Out" then if e.direction=="out" then rows[#rows+1]=e end else rows[#rows+1]=e end end end
  if filter=="Gold In" or filter=="Gold Out" then table.sort(rows,function(a,b) return (tonumber(a.amount) or 0)>(tonumber(b.amount) or 0) end) else table.sort(rows,function(a,b) return (tonumber(a.timestamp) or 0)>(tonumber(b.timestamp) or 0) end) end; return rows
end
function TML:ComputePersonalGoldStats()
  self:V21689_EnsurePersonalLedgerCore(); local st={current=tonumber(self:GetCarriedGoldLive()) or 0,bank=tonumber(self:GetBankGoldLive()),in24=0,out24=0,verifiedNet24=0,net24=0,allIn=0,allOut=0,allNet=0,actualNet24=nil,unmatched24=nil,coverage="Need 24H Baseline",scanned=(self.saved.scanStatus and self.saved.scanStatus.personalGold~=nil)}
  for _,e in ipairs(self:GetPersonalGoldRows("Recent") or {}) do local amt=tonumber(e.amount) or 0; if e.direction=="in" then st.allIn=st.allIn+amt; if TML89_Is24(e.timestamp) then st.in24=st.in24+amt end elseif e.direction=="out" then st.allOut=st.allOut+amt; if TML89_Is24(e.timestamp) then st.out24=st.out24+amt end end end
  st.verifiedNet24=st.in24-st.out24; st.net24=st.verifiedNet24; st.allNet=st.allIn-st.allOut; local total=st.current+(st.bank or 0); local hist=self.saved.goldSnapshots and self.saved.goldSnapshots.history or {}; local target=TML89_Now()-TML89.DAY; local base=nil; local earliest=nil
  for _,s in ipairs(hist) do if tonumber(s.total) and tonumber(s.timestamp) then if not earliest or (tonumber(s.timestamp) or 0)<(tonumber(earliest.timestamp) or 0) then earliest=s end; if (tonumber(s.timestamp) or 0)<=target and ((not base) or (tonumber(s.timestamp) or 0)>(tonumber(base.timestamp) or 0)) then base=s end end end
  if base then st.actualNet24=total-(tonumber(base.total) or 0); st.coverage="Full 24H" elseif earliest then local hours=math.floor((TML89_Now()-(tonumber(earliest.timestamp) or 0))/3600); if hours and hours>0 then st.actualNet24=total-(tonumber(earliest.total) or 0); st.coverage="Partial "..tostring(hours).."h" end end; if st.actualNet24 ~= nil then st.unmatched24=st.actualNet24-st.verifiedNet24 end; return st
end

TML89.OldRenderPersonalLedger = TML.RenderOldLedger
function TML:RenderOldLedger(root,x,y,w,h,accent,guildMode)
  if guildMode then if TML89.OldRenderPersonalLedger then return TML89.OldRenderPersonalLedger(self,root,x,y,w,h,accent,guildMode) end; return end
  local st=self:ComputePersonalGoldStats(); local topH=338; self:DrawLegacyPanel(root,"PersonalGoldStats89",x,y,w,topH,"PERSONAL GOLD LEDGER",accent); local bankText=st.bank==nil and "Bank N/A" or TML89_Gold(st.bank); local hasSnapshot=(st.actualNet24 ~= nil) and tostring(st.coverage or ""):find("0h",1,true)==nil; local snapshotText=hasSnapshot and TML89_Gold(st.actualNet24) or "Need 24H Baseline"; local unmatchedText=hasSnapshot and TML89_Gold(st.unmatched24 or 0) or "N/A"; local coverage=hasSnapshot and tostring(st.coverage or "Partial") or "Need 24H Baseline"; local meta=self.saved.ledgerMeta and self.saved.ledgerMeta.personalGold or {}
  local cards={{"Current Gold",TML89_Gold(st.current),C.gold},{"Bank Gold",bankText,C.gold},{"24H In",TML89_Gold(st.in24),VGreen},{"24H Out",TML89_Gold(st.out24),VRed},{"24H Net",TML89_Gold(st.verifiedNet24),st.verifiedNet24>=0 and VGreen or VRed},{"All-Time In",TML89_Gold(st.allIn),VGreen},{"All-Time Out",TML89_Gold(st.allOut),VRed},{"All-Time Net",TML89_Gold(st.allNet),st.allNet>=0 and VGreen or VRed},{"Current Scan",TML89_Num(meta.currentRows or 0),C.cyanSoft},{"All-Time Rows",TML89_Num(meta.retainedRows or TML89_Count(self.saved.retainedPersonalGoldEvents)),C.cyanSoft},{"Snapshot Net",snapshotText,hasSnapshot and ((st.actualNet24 or 0)>=0 and VGreen or VRed) or C.yellowDim},{"Unmatched 24H",unmatchedText,C.cyanSoft}}
  local cardW=math.floor((w-104)/4); for i,c in ipairs(cards) do local col=(i-1)%4; local row=math.floor((i-1)/4); self:DrawMiniStat(root,"PersonalGoldCard89"..i,x+24+col*(cardW+14),y+58+row*78,cardW,68,c[1],c[2],c[3],c[3]) end; self:Label("PersonalGoldNote89",root,"24H = last 24h only. All-Time = every retained loaded personal gold row. Current Scan never replaces All-Time. Coverage: "..coverage,x+26,y+topH-36,w-52,30,C.yellowDim,FONTS.panelSmall,TEXT_ALIGN_CENTER)
  local filter=self.saved.personalGoldFilter or "Recent"; local rows={}; for _,e in ipairs(self:GetPersonalGoldRows(filter)) do rows[#rows+1]={TML89_Rel(e.timestamp),TML89_Limit(e.user,18),e.source or TML89_NA(),e.direction=="in" and TML89_Cell("+"..TML89_Gold(e.amount),VGreen) or TML89_Cell("-"..TML89_Gold(e.amount),VRed),e.note or TML89_NA()} end
  self:DrawLegacyTable(root,"PersonalGoldRows89",x,y+topH+20,w,h-topH-96,"PERSONAL GOLD HISTORY - "..string.upper(filter),{"Date","UserID","Source","Amount","Note"},self:RowsOrNA(rows,5,"Press Refresh Ledger"),accent,{1,1.1,1.8,1,1.3}); local by=y+h-64; local bw=math.floor((w-12)/2); self:ToolButton(root,"PersonalGoldRefresh89",x,by,bw,48,"Refresh Ledger",accent,function() TML:ScanPersonalGoldLedger(); TML:RenderTool("gold_ledger_personal") end); self:ToolButton(root,"PersonalGoldFilter89",x+bw+12,by,bw,48,"Filter: "..filter,accent,function() TML:CyclePersonalGoldFilter() end)
end

TML89.OldRenderSales = TML.RenderOldSales
function TML:RenderOldSales(root,x,y,w,h,accent,guildMode)
  if guildMode then if TML89.OldRenderSales then return TML89.OldRenderSales(self,root,x,y,w,h,accent,guildMode) end; return end
  self:V21689_EnsurePersonalLedgerCore(); local filter=self.saved.personalSalesFilter or "All-Time"; local st=self:ComputeSalesStats(0,true); local meta=self.saved.ledgerMeta and self.saved.ledgerMeta.sales or {}; self:DrawLegacyPanel(root,"PersonalSalesStats89",x,y,w,192,"PERSONAL SALES TRACKER",accent)
  local cards={{"24H Net",TML89_Gold(st.sales24),VGreen},{"All-Time Loaded",TML89_Gold(st.totalSales),VYellow},{"All-Time Gross",TML89_Gold(st.gross),C.gold},{"ESO Fees",TML89_Gold(st.fees),VRed},{"Current Scan",TML89_Num(meta.currentRows or 0),C.cyanSoft},{"Your Rows",TML89_Num(st.rowCount or 0),C.cyanSoft}}; local cw=math.floor((w-88)/6); for i,c in ipairs(cards) do self:DrawMiniStat(root,"PersonalSalesCard89"..i,x+20+(i-1)*(cw+10),y+58,cw,78,c[1],c[2],c[3],c[3]) end; self:Label("PersonalSalesStatus89",root,tostring(self.saved.scanStatus.sales or "Press Scan Sales. Current Scan and All-Time Loaded are separated."),x+24,y+148,w-48,26,C.cyanSoft,FONTS.panelSmall,TEXT_ALIGN_CENTER)
  local source,title,headers,widths={},"",{},nil
  if filter=="Guild Breakdown" then for _,r in ipairs(self:GetPersonalSalesGuildBreakdown()) do source[#source+1]={TML89_Limit(r.guild,24),TML89_Cell(TML89_Gold(r.net24),VGreen),TML89_Cell(TML89_Gold(r.net),VYellow),TML89_Num(r.items),TML89_Cell(TML89_Gold(r.highest),VYellow),r.status or "Loaded"} end; title="PERSONAL SALES BY GUILD"; headers={"Guild","24H Net","All-Time Net","Items","Highest","Status"}; widths={1.7,1,1,0.6,1,1}
  elseif filter=="Top Sellers" or filter=="Best Sellers" then for _,e in ipairs(self:GetPersonalTopSellerRows()) do source[#source+1]={self:FormatItemCell(e.itemLink,e.itemName,24),self:GetGuildName(e.guild),TML89_Num(e.qty),TML89_Cell(TML89_Gold(e.gold),VYellow),TML89_Cell(TML89_Gold(e.avg),VYellow)} end; title="TOP SELLERS - PERSONAL ALL-TIME LOADED"; headers={"Item","Guild","Qty","Total","Avg"}; widths={2,1.3,.55,1,1}
  else local rows=(filter=="24H") and self:GetSalesRows24H(0,true) or self:GetSalesRows(0,true); for _,e in ipairs(rows) do source[#source+1]={self:FormatItemCell(e.itemLink,e.itemName,24),self:GetGuildName(e.guildId),TML89_Num(e.quantity),TML89_Cell(TML89_Gold(e.grossAmount or e.amount),C.gold),TML89_Cell(TML89_Gold(e.feeAmount or 0),VRed),TML89_Cell(TML89_Gold(e.netAmount or e.amount),VYellow),TML89_Rel(e.timestamp)} end; title=(filter=="24H") and "24H PERSONAL SALES - LAST 24 HOURS" or "ALL-TIME LOADED PERSONAL SALES - RETAINED @USERID ROWS"; headers={"Item","Guild","Qty","Gross","Fee","Net","When"}; widths={2,1.15,.45,.8,.75,.85,.8} end
  self:DrawLegacyTable(root,"PersonalSalesRows89",x,y+214,w,h-292,title,headers,self:RowsOrNA(source,#headers,"Press Scan Sales"),accent,widths); local by=y+h-64; local bw=math.floor((w-36)/4); self:ToolButton(root,"PersonalSalesScan89",x,by,bw,48,"Scan Sales",accent,function() TML:ScanPersonalSales() end); self:ToolButton(root,"PersonalSalesAll89",x+bw+12,by,bw,48,"Scan All",accent,function() TML:ScanAllGuildSales() end); self:ToolButton(root,"PersonalSalesFilter89",x+(bw+12)*2,by,bw,48,"Filter: "..filter,accent,function() TML:CyclePersonalSalesFilter() end)
end
function TML:CyclePersonalSalesFilter() local o={"All-Time","24H","Guild Breakdown","Top Sellers"}; local cur=self.saved.personalSalesFilter or "All-Time"; local idx=1; for i,v in ipairs(o) do if v==cur then idx=i end end; self.saved.personalSalesFilter=o[(idx%#o)+1]; self:RenderTool("personal_sales") end

TML89.OldScanNetWorth = TML.ScanNetWorth
function TML:ScanNetWorth() self:EnsureDataDefaults(); self.saved.networth=nil; if TML89.OldScanNetWorth then TML89.OldScanNetWorth(self) end; self.saved.networth=self.saved.networth or {}; self.saved.networth.currentSnapshot=true; self.saved.networth.snapshotScanId=tostring(TML89_Now()); self.saved.scanStatus.networth=(self.saved.scanStatus.networth or "Scan complete").." / Current snapshot replaced; no old item rows retained." end
TML89.OldResetFishingSession = TML.ResetFishingSession
function TML:ResetFishingSession() self:EnsureDataDefaults(); self.saved.fishingSession={state="not_started",baseline={},rows={},startedAt=0,resumedAt=0,stoppedAt=0,activeSeconds=0,lastUpdate=0,baitUsed=0}; self.saved.scanStatus.fishing="Successful Reset - fishing session rows and baseline cleared."; self:RenderTool("fishing") end

TML89.OldEnsure = TML.EnsureDataDefaults
function TML:EnsureDataDefaults() if TML89.OldEnsure then TML89.OldEnsure(self) end; self.saved=self.saved or self:Defaults(); self.saved.scanStatus=self.saved.scanStatus or {}; self.saved.ledgerMeta=self.saved.ledgerMeta or {}; self.saved.currentScan=self.saved.currentScan or {}; self.saved.retainedSalesEvents=self.saved.retainedSalesEvents or {}; self.saved.retainedPersonalGoldEvents=self.saved.retainedPersonalGoldEvents or {}; self.pageUpdated=self.pageUpdated or {}; for k,v in pairs(TML89.PAGE_UPDATED) do self.pageUpdated[k]=v end end
TML89.OldInitialize = TML.Initialize
function TML:Initialize(addonName) if TML89.OldInitialize then TML89.OldInitialize(self,addonName) end; self.version=TML89.VERSION; self.addOnVersion=TML89.ADDON_VERSION; self.lastUpdated=TML89.UPDATED; self.icon="TamrielMasterLedger/textures/tamrielmasterledger_icon.dds"; self.displayTitle="|c00D9FFTamriel Master Ledger|r"; self:EnsureDataDefaults(); if d then d("Tamriel Master Ledger v"..self.version.." personal ledger crash guard fix loaded.") end end

-- v2.0.16.91 PHASE 40 PERSONAL SALES COVERAGE / SCAN HEALTH FIX
-- Built from v2.0.16.90 rollback line. No menu/scene/input registration changes.
TML40 = _G.TML40 or {}
_G.TML40 = TML40
TML40.VERSION = "2.0.16.91"
TML40.ADDON_VERSION = 21691
TML40.UPDATED = "06/22/2026 22:05 UTC"
TML40.PAGE_UPDATED = { main=TML40.UPDATED, personal_sales="06/22/2026", gold_ledger_personal="06/22/2026", daily_tracker="06/22/2026" }

function TML40_Now() return (GetTimeStamp and GetTimeStamp()) or os.time() end
function TML40_CleanUser(s)
  s = tostring(s or "")
  s = s:gsub("|c%x%x%x%x%x%x",""):gsub("|r","")
  s = s:gsub("^%s+",""):gsub("%s+$","")
  s = s:gsub("^@","")
  return string.lower(s)
end
function TML40_UserText(s)
  s = tostring(s or "")
  s = s:gsub("|c%x%x%x%x%x%x",""):gsub("|r","")
  s = s:gsub("^%s+",""):gsub("%s+$","")
  return s
end
-- Re-harden the shared user key used by the retained sales ledger so @xPricee and xPricee match.
function TML89_UserKey(s) return TML40_CleanUser(s) end
function TML40_SameUser(a,b) return TML40_CleanUser(a) ~= "" and TML40_CleanUser(a) == TML40_CleanUser(b) end
function TML40_Is24(ts) ts=tonumber(ts) or 0; return ts>0 and (TML40_Now()-ts)<=86400 end
function TML40_Count(t) local n=0; for _ in pairs(t or {}) do n=n+1 end; return n end
function TML40_Gold(v) return WFormatGold and WFormatGold(tonumber(v) or 0) or tostring(tonumber(v) or 0).."g" end
function TML40_Num(v) return WFormatNumber and WFormatNumber(tonumber(v) or 0) or tostring(tonumber(v) or 0) end
function TML40_Cell(t,c) return VCell and VCell(t,c) or tostring(t or "") end
function TML40_Limit(s,n) return WLimit and WLimit(s,n) or tostring(s or "") end
function TML40_Rel(ts) return WRelTime and WRelTime(ts) or tostring(ts or "") end
function TML40_NA() return WNA and WNA() or "N/A" end

function TML40_SaleKey(guildId,eventId,seller,gross,timestamp,itemLink,quantity)
  if eventId and tostring(eventId) ~= "" and tostring(eventId) ~= "0" then return "sale:"..tostring(guildId or 0)..":event:"..tostring(eventId) end
  return table.concat({"sale",tostring(guildId or 0),TML40_CleanUser(seller),tostring(tonumber(gross) or 0),tostring(tonumber(timestamp) or 0),tostring(itemLink or ""),tostring(tonumber(quantity) or 1)},":")
end

-- Replacement retained sale writer: stores normalized seller fields and current-scan flags.
function TML89_AddSale(self,guildId,eventId,seller,gross,timestamp,itemLink,quantity,tax,current)
  self:V21689_EnsurePersonalLedgerCore()
  gross=tonumber(gross) or 0; if gross<=0 then return false,false,"bad amount" end
  local ts=tonumber(timestamp) or 0; local review=false; if ts<=0 then ts=TML40_Now(); review=true end
  local qty=tonumber(quantity) or 1; if qty<=0 then qty=1 end
  local fee=TML89_Fee and TML89_Fee(gross) or math.floor(gross*0.07+0.5)
  local net=math.max(0,gross-fee)
  local guildTax=tonumber(tax) or (TML89_GuildTax and TML89_GuildTax(gross)) or math.floor(gross*0.035+0.5)
  local sellerRaw=TML40_UserText(seller)
  local sellerKey=TML40_CleanUser(sellerRaw)
  local key=TML40_SaleKey(guildId,eventId,sellerRaw,gross,ts,itemLink,qty)
  local existed=self.saved.retainedSalesEvents[key] ~= nil
  self.saved.retainedSalesEvents[key]={key=key,guildId=guildId,seller=sellerRaw ~= "" and sellerRaw or TML40_NA(),sellerRaw=sellerRaw,sellerKey=sellerKey,amount=net,netAmount=net,grossAmount=gross,feeAmount=fee,guildTax=guildTax,tax=guildTax,feeAdjusted=true,timestamp=ts,itemLink=itemLink,itemName=(WGetItemName and WGetItemName(itemLink)) or tostring(itemLink or "Sale"),quantity=qty,review=review}
  if current then self.saved.currentScan.sales[key]=true end
  self.saved.salesEvents=self.saved.retainedSalesEvents
  return not existed,existed,nil
end

function TML:V21691_SalesCoverage()
  self:V21689_EnsurePersonalLedgerCore()
  local my=TML40_CleanUser(self:GetUserDisplayName())
  local c={guildsTotal=0,guildsWithRows=0,guildRowsThisScan=0,personalRowsThisScan=0,personalAllRows=0,personal24Rows=0,retainedRows=TML40_Count(self.saved.retainedSalesEvents),reviewRows=0,sellerMissing=0,sellerNonMatch=0,oldest=nil,newest=nil,coverage="No Sales Loaded"}
  if self.EachGuild then self:EachGuild(function(_) c.guildsTotal=c.guildsTotal+1 end) end
  local guildSeen={}
  for k,e in pairs(self.saved.retainedSalesEvents or {}) do
    if type(e)=="table" then
      local g=e.guildId or e.guild or 0; if g and g~=0 then guildSeen[tostring(g)]=true end
      if e.review then c.reviewRows=c.reviewRows+1 end
      local sellerKey=TML40_CleanUser(e.sellerKey or e.seller or e.sellerRaw)
      if sellerKey=="" or sellerKey==TML40_CleanUser(TML40_NA()) then c.sellerMissing=c.sellerMissing+1
      elseif sellerKey~=my then c.sellerNonMatch=c.sellerNonMatch+1 end
      if (self.saved.currentScan and self.saved.currentScan.sales and self.saved.currentScan.sales[k]) then
        c.guildRowsThisScan=c.guildRowsThisScan+1
        if sellerKey==my then c.personalRowsThisScan=c.personalRowsThisScan+1 end
      end
      if sellerKey==my then
        c.personalAllRows=c.personalAllRows+1
        if TML40_Is24(e.timestamp) then c.personal24Rows=c.personal24Rows+1 end
        local ts=tonumber(e.timestamp) or 0
        if ts>0 and (not c.oldest or ts<c.oldest) then c.oldest=ts end
        if ts>0 and (not c.newest or ts>c.newest) then c.newest=ts end
      end
    end
  end
  for _ in pairs(guildSeen) do c.guildsWithRows=c.guildsWithRows+1 end
  local meta=self.saved.ledgerMeta and self.saved.ledgerMeta.sales or {}
  c.newRows=tonumber(meta.newRows) or 0
  c.updatedRows=tonumber(meta.updatedRows) or 0
  if c.personalAllRows>0 then
    if c.guildsTotal>0 and c.guildsWithRows<c.guildsTotal then c.coverage="Partial - Load Guild History" else c.coverage="Loaded" end
  elseif c.retainedRows>0 then
    c.coverage="No @UserID Rows Found"
  else
    c.coverage="Press Scan All"
  end
  return c
end

-- Rebuild guild sales scan to track per-guild coverage and never make current scan look like all-time.
function TML:ScanGuildSales(g,noRender,noReset)
  self:V21689_EnsurePersonalLedgerCore(); if not g or not g.id or g.id==0 then return 0 end; if not noReset then self.saved.currentScan.sales={} end
  self.saved.currentScan.salesGuilds=self.saved.currentScan.salesGuilds or {}
  local cat=self:GetHistoryCategory("trader"); if type(GetGuildHistoryTraderEventInfo)~="function" or not cat then self.saved.scanStatus.sales="Sales history API unavailable"; return 0 end
  local newest,oldest=self:GetHistoryIndices(g.id,cat,WORKING_HISTORY_DAYS); local scanned,accepted,newRows,updatedRows,review,missingSeller=0,0,0,0,0,0
  if oldest and newest and oldest>=newest then
    for i=newest,oldest do
      local vals={pcall(GetGuildHistoryTraderEventInfo,g.id,i)}; local ok=table.remove(vals,1)
      if ok then
        local eventId,timestamp,isRedacted,eventType,seller,buyer,itemLink,quantity,price,tax=TML89_ParseTrader(vals)
        if not isRedacted and tonumber(price) and tonumber(price)>0 then
          scanned=scanned+1
          if not seller or TML40_UserText(seller)=="" then missingSeller=missingSeller+1; review=review+1 end
          local added,existed=TML89_AddSale(self,g.id,eventId or i,seller,price,timestamp,itemLink,quantity,tax,true)
          if added or existed then accepted=accepted+1 end
          if added then newRows=newRows+1 elseif existed then updatedRows=updatedRows+1 end
        else
          review=review+1
        end
      else
        review=review+1
      end
    end
  end
  self.saved.currentScan.salesGuilds[tostring(g.id)]={name=tostring(g.name or g.id),scanned=scanned,accepted=accepted,newRows=newRows,updatedRows=updatedRows,reviewRows=review,missingSeller=missingSeller}
  if self.RequestHistory then self:RequestHistory(g.id,cat,WORKING_HISTORY_DAYS) end; if self.RebuildPriceCacheFromSales then self:RebuildPriceCacheFromSales() end
  self.saved.ledgerMeta.sales={currentRows=accepted,newRows=newRows,updatedRows=updatedRows,retainedRows=TML40_Count(self.saved.retainedSalesEvents),reviewRows=review,missingSeller=missingSeller,lastGuild=tostring(g.name or g.id),lastScan=TML40_Now()}
  self.saved.scanStatus.sales="Current guild scan for "..tostring(g.name or "guild")..": "..tostring(accepted).." rows seen / "..tostring(newRows).." new / "..tostring(TML40_Count(self.saved.retainedSalesEvents)).." all-time loaded retained."
  if not noRender then self:RenderTool(self.state.activeTool or "guild_sales") end
  return accepted
end

function TML:ScanAllGuildSales(noRender)
  self:V21689_EnsurePersonalLedgerCore(); self.saved.currentScan.sales={}; self.saved.currentScan.salesGuilds={}
  local total,nguild,newRows,updatedRows,review,missingSeller=0,0,0,0,0,0
  self:EachGuild(function(g)
    nguild=nguild+1
    local before=TML40_Count(self.saved.retainedSalesEvents)
    local raw=self:ScanGuildSales(g,true,true); local n=tonumber(raw) or 0; total=total+n
    local after=TML40_Count(self.saved.retainedSalesEvents); if after>before then newRows=newRows+(after-before) end
    local gm=(self.saved.currentScan.salesGuilds or {})[tostring(g.id)] or {}; review=review+(tonumber(gm.reviewRows) or 0); missingSeller=missingSeller+(tonumber(gm.missingSeller) or 0); updatedRows=updatedRows+(tonumber(gm.updatedRows) or 0)
  end)
  local cov=self:V21691_SalesCoverage()
  self.saved.ledgerMeta.sales={currentRows=total,newRows=newRows,updatedRows=updatedRows,retainedRows=TML40_Count(self.saved.retainedSalesEvents),reviewRows=review,missingSeller=missingSeller,guilds=nguild,guildsWithRows=cov.guildsWithRows,personalCurrentRows=cov.personalRowsThisScan,personalAllRows=cov.personalAllRows,personal24Rows=cov.personal24Rows,oldest=cov.oldest,newest=cov.newest,lastScan=TML40_Now(),coverage=cov.coverage}
  self.saved.scanStatus.sales="Coverage: "..tostring(cov.coverage)..". Guilds scanned "..tostring(nguild).." / with history "..tostring(cov.guildsWithRows)..". Current scan: "..tostring(total).." guild rows / "..tostring(cov.personalRowsThisScan).." yours. Your all-time loaded: "..tostring(cov.personalAllRows).." rows / "..tostring(cov.personal24Rows).." 24H."
  if not noRender then self:RenderTool(self.state.activeTool or "personal_sales") end; return total
end

function TML:ScanPersonalSales(noRender)
  local total=self:ScanAllGuildSales(true)
  local cov=self:V21691_SalesCoverage()
  self.saved.scanStatus.sales="Coverage: "..tostring(cov.coverage)..". Current scan saw "..tostring(total).." guild sale rows and "..tostring(cov.personalRowsThisScan).." @UserID rows. All-Time Loaded keeps "..tostring(cov.personalAllRows).." @UserID rows / "..tostring(cov.personal24Rows).." 24H."
  if not noRender then self:RenderTool("personal_sales") end; return cov.personalAllRows or 0
end

function TML:GetSalesRows(guildId,onlyMe)
  self:V21689_EnsurePersonalLedgerCore(); local rows={}; local my=TML40_CleanUser(self:GetUserDisplayName())
  for _,e in pairs(self.saved.retainedSalesEvents or self.saved.salesEvents or {}) do
    if type(e)=="table" then
      if V21669_NormalizeSaleRow then V21669_NormalizeSaleRow(e) end
      local okGuild=(not guildId or guildId==0 or e.guildId==guildId)
      local sellerKey=TML40_CleanUser(e.sellerKey or e.seller or e.sellerRaw)
      local okUser=(not onlyMe) or (sellerKey==my)
      if okGuild and okUser then rows[#rows+1]=e end
    end
  end
  table.sort(rows,function(a,b) return (tonumber(a.timestamp) or 0)>(tonumber(b.timestamp) or 0) end); return rows
end
function TML:GetSalesRows24H(guildId,onlyMe) local out={}; for _,e in ipairs(self:GetSalesRows(guildId,onlyMe)) do if TML40_Is24(e.timestamp) then out[#out+1]=e end end; return out end

TML40.OldRenderSales = TML.RenderOldSales
function TML:RenderOldSales(root,x,y,w,h,accent,guildMode)
  if guildMode then if TML40.OldRenderSales then return TML40.OldRenderSales(self,root,x,y,w,h,accent,guildMode) end; return end
  self:V21689_EnsurePersonalLedgerCore()
  local filter=self.saved.personalSalesFilter or "All-Time"; local st=self:ComputeSalesStats(0,true); local cov=self:V21691_SalesCoverage(); local meta=self.saved.ledgerMeta and self.saved.ledgerMeta.sales or {}
  local topH=276
  self:DrawLegacyPanel(root,"PersonalSalesStats91",x,y,w,topH,"PERSONAL SALES TRACKER",accent)
  local oldest=cov.oldest and TML40_Rel(cov.oldest) or "N/A"; local newest=cov.newest and TML40_Rel(cov.newest) or "N/A"
  local cards={{"24H Net",TML40_Gold(st.sales24),VGreen},{"All-Time Net",TML40_Gold(st.totalSales),VYellow},{"All-Time Gross",TML40_Gold(st.gross),C.gold},{"ESO Fees",TML40_Gold(st.fees),VRed},{"Your Rows",TML40_Num(cov.personalAllRows),C.cyanSoft},{"24H Rows",TML40_Num(cov.personal24Rows),VGreen},{"This Scan Yours",TML40_Num(cov.personalRowsThisScan),C.cyanSoft},{"Coverage",tostring(cov.coverage),C.yellowDim}}
  local cw=math.floor((w-104)/4)
  for i,c in ipairs(cards) do local col=(i-1)%4; local row=math.floor((i-1)/4); self:DrawMiniStat(root,"PersonalSalesCard91"..i,x+20+col*(cw+14),y+58+row*78,cw,68,c[1],c[2],c[3],c[3]) end
  self:Label("PersonalSalesCoverage91a",root,"Guilds scanned: "..tostring(meta.guilds or 0).." / with trader rows: "..tostring(cov.guildsWithRows)..". Current scan: "..tostring(cov.guildRowsThisScan).." guild rows, "..tostring(cov.personalRowsThisScan).." yours, "..tostring(meta.newRows or 0).." new retained.",x+24,y+214,w-48,24,C.cyanSoft,FONTS.panelSmall,TEXT_ALIGN_CENTER)
  self:Label("PersonalSalesCoverage91b",root,"Oldest loaded personal sale: "..oldest.."  |  Newest: "..newest.."  |  Review: "..tostring(cov.reviewRows).."  |  Seller missing: "..tostring(cov.sellerMissing).."  |  Seller non-match: "..tostring(cov.sellerNonMatch),x+24,y+238,w-48,24,C.yellowDim,FONTS.panelSmall,TEXT_ALIGN_CENTER)
  local source,title,headers,widths={},"",{},nil
  if filter=="Guild Breakdown" then for _,r in ipairs(self:GetPersonalSalesGuildBreakdown()) do source[#source+1]={TML40_Limit(r.guild,24),TML40_Cell(TML40_Gold(r.net24),VGreen),TML40_Cell(TML40_Gold(r.net),VYellow),TML40_Num(r.items),TML40_Cell(TML40_Gold(r.highest),VYellow),r.status or "Loaded"} end; title="PERSONAL SALES BY GUILD - ALL-TIME LOADED"; headers={"Guild","24H Net","All-Time Net","Items","Highest","Status"}; widths={1.7,1,1,.6,1,1}
  elseif filter=="Top Sellers" or filter=="Best Sellers" then for _,e in ipairs(self:GetPersonalTopSellerRows()) do source[#source+1]={self:FormatItemCell(e.itemLink,e.itemName,24),self:GetGuildName(e.guild),TML40_Num(e.qty),TML40_Cell(TML40_Gold(e.gold),VYellow),TML40_Cell(TML40_Gold(e.avg),VYellow)} end; title="TOP SELLERS - PERSONAL ALL-TIME LOADED"; headers={"Item","Guild","Qty","Total","Avg"}; widths={2,1.3,.55,1,1}
  else local rows=(filter=="24H") and self:GetSalesRows24H(0,true) or self:GetSalesRows(0,true); for _,e in ipairs(rows) do source[#source+1]={self:FormatItemCell(e.itemLink,e.itemName,24),self:GetGuildName(e.guildId),TML40_Num(e.quantity),TML40_Cell(TML40_Gold(e.grossAmount or e.amount),C.gold),TML40_Cell(TML40_Gold(e.feeAmount or 0),VRed),TML40_Cell(TML40_Gold(e.netAmount or e.amount),VYellow),TML40_Rel(e.timestamp)} end; title=(filter=="24H") and "24H PERSONAL SALES - LAST 24 HOURS" or "ALL-TIME LOADED PERSONAL SALES - RETAINED @USERID ROWS"; headers={"Item","Guild","Qty","Gross","Fee","Net","When"}; widths={2,1.15,.45,.8,.75,.85,.8} end
  self:DrawLegacyTable(root,"PersonalSalesRows91",x,y+topH+20,w,h-topH-98,title,headers,self:RowsOrNA(source,#headers,"Press Scan Sales"),accent,widths)
  local by=y+h-64; local bw=math.floor((w-36)/4)
