-- =========================================================
-- v2.0.16.92 PERSONAL SALES/GOLD SCANNER REBUILD + RAFFLE TICKET COST
-- Phase 41
-- - Safer trader sale parsing with raw diagnostics.
-- - Personal Sales: current scan vs retained all-time @UserID rows.
-- - Personal Gold Ledger: uses retained verified personal sale rows and retained guild gold rows.
-- - Guild Raffle: manual ticket cost per guild/mode while keeping reset/ticket suffix rule.
-- - No menu/scene/input registration changes.
-- =========================================================
TML.version = "2.0.16.92"
TML.addOnVersion = 21692
TML.lastUpdated = "06/22/2026 22:45 UTC"

_G.TML41 = _G.TML41 or {}
TML41 = _G.TML41
TML41.VERSION = "2.0.16.92"
TML41.ADDON_VERSION = 21692
TML41.UPDATED = "06/22/2026 22:45 UTC"
TML41.PAGE_UPDATED = {
  main = TML41.UPDATED,
  personal_sales = "06/22/2026",
  gold_ledger_personal = "06/22/2026",
  guild_raffle = "06/22/2026",
}

function TML41_Now() return (GetTimeStamp and GetTimeStamp()) or os.time() end
function TML41_Gold(v) return WFormatGold and WFormatGold(tonumber(v) or 0) or tostring(tonumber(v) or 0).."g" end
function TML41_Num(v) return WFormatNumber and WFormatNumber(tonumber(v) or 0) or tostring(tonumber(v) or 0) end
function TML41_Cell(t,c) return VCell and VCell(t,c) or tostring(t or "") end
function TML41_Limit(s,n) return WLimit and WLimit(s,n) or tostring(s or "") end
function TML41_Rel(ts) return WRelTime and WRelTime(ts) or tostring(ts or "") end
function TML41_NA() return WNA and WNA() or "N/A" end
function TML41_Count(t) local n=0; for _ in pairs(t or {}) do n=n+1 end; return n end
function TML41_CleanUser(s)
  s=tostring(s or "")
  s=s:gsub("|c%x%x%x%x%x%x",""):gsub("|r","")
  s=s:gsub("^%s+",""):gsub("%s+$","")
  s=s:gsub("^@","")
  return string.lower(s)
end
function TML41_UserText(s)
  s=tostring(s or "")
  s=s:gsub("|c%x%x%x%x%x%x",""):gsub("|r","")
  s=s:gsub("^%s+",""):gsub("%s+$","")
  return s
end
function TML41_IsItemLink(s) return type(s)=="string" and s:find("|H",1,true) ~= nil end
function TML41_IsUserString(s)
  if type(s) ~= "string" then return false end
  if TML41_IsItemLink(s) then return false end
  local t=TML41_UserText(s)
  return t ~= "" and t:sub(1,1) == "@"
end
function TML41_Is24(ts) ts=tonumber(ts) or 0; return ts>0 and (TML41_Now()-ts)<=86400 end
function TML41_Fee(gross) gross=tonumber(gross) or 0; return math.floor(gross*0.07+0.5) end
function TML41_GuildTax(gross) gross=tonumber(gross) or 0; return math.floor(gross*0.035+0.5) end
function TML41_SameUser(a,b) local aa=TML41_CleanUser(a); local bb=TML41_CleanUser(b); return aa ~= "" and aa == bb end

function TML:V21692_EnsureCore()
  if self.V21689_EnsurePersonalLedgerCore then self:V21689_EnsurePersonalLedgerCore() else self:EnsureDataDefaults() end
  self.saved.retainedSalesEvents = self.saved.retainedSalesEvents or {}
  self.saved.retainedPersonalGoldEvents = self.saved.retainedPersonalGoldEvents or {}
  self.saved.currentScan = self.saved.currentScan or {}
  self.saved.currentScan.sales = self.saved.currentScan.sales or {}
  self.saved.currentScan.salesGuilds = self.saved.currentScan.salesGuilds or {}
  self.saved.currentScan.personalGold = self.saved.currentScan.personalGold or {}
  self.saved.ledgerMeta = self.saved.ledgerMeta or {}
  self.saved.ledgerMeta.sales = self.saved.ledgerMeta.sales or {}
  self.saved.ledgerMeta.personalGold = self.saved.ledgerMeta.personalGold or {}
  self.saved.raffleTicketCost = self.saved.raffleTicketCost or {}
  self.saved.salesEvents = self.saved.retainedSalesEvents
  self.saved.personalGoldEvents = self.saved.retainedPersonalGoldEvents
end

-- Stronger trader-history parser. Keeps the known ESO positional layout first, then falls back to type/shape detection.
function TML:V21692_ParseTrader(vals,index)
  vals = vals or {}
  local eventId = vals[1]
  local timestamp = vals[2]
  local isRedacted = vals[3] == true
  local eventType = vals[4]
  local seller = vals[5]
  local buyer = vals[6]
  local itemLink = vals[7]
  local quantity = vals[8]
  local price = vals[9]
  local tax = vals[10]

  local strings, users, itemStrings, nums = {}, {}, {}, {}
  for i,v in ipairs(vals) do
    if type(v) == "string" then
      strings[#strings+1] = {i=i,v=v}
      if TML41_IsItemLink(v) then itemStrings[#itemStrings+1] = {i=i,v=v}
      elseif TML41_IsUserString(v) then users[#users+1] = {i=i,v=v} end
    elseif type(v) == "number" then
      nums[#nums+1] = {i=i,v=v}
    elseif type(v) == "boolean" and v == true then
      isRedacted = true
    end
  end

  if not TML41_IsItemLink(itemLink) and itemStrings[1] then itemLink = itemStrings[1].v end
  if not TML41_IsUserString(seller) then seller = nil end
  if not TML41_IsUserString(buyer) then buyer = nil end
  if not seller and users[1] then seller = users[1].v end
  if not buyer and users[2] then buyer = users[2].v end

  -- Timestamp: use positional value first, then any sane Unix timestamp.
  if not tonumber(timestamp) or tonumber(timestamp) <= 0 then
    timestamp = nil
    for _,n in ipairs(nums) do if n.v > 1000000000 and n.v < 4102444800 then timestamp = n.v; break end end
  end

  -- Quantity: ESO trader event usually puts quantity at position 8.
  quantity = tonumber(quantity) or 1
  if quantity <= 0 or quantity > 200000 then quantity = 1 end

  -- Price: trust position 9 when sane. Fallback ignores eventId/timestamp/eventType/quantity/tax slots where possible.
  price = tonumber(price) or 0
  if price <= 0 then
    local best = 0
    for _,n in ipairs(nums) do
      local idx, val = n.i, tonumber(n.v) or 0
      if idx ~= 1 and idx ~= 2 and idx ~= 3 and idx ~= 4 and idx ~= 8 and idx ~= 10 and val > best and val < 1000000000 then best = val end
    end
    if best <= 0 then
      for _,n in ipairs(nums) do local val=tonumber(n.v) or 0; if val > best and val < 1000000000 then best = val end end
    end
    price = best
  end
  tax = tonumber(tax) or 0
  if tax < 0 or (price and price > 0 and tax > price) then tax = 0 end

  if not eventId or tostring(eventId)=="" then eventId = index end
  return {
    eventId=eventId,
    timestamp=tonumber(timestamp) or 0,
    isRedacted=isRedacted,
    eventType=eventType,
    seller=TML41_UserText(seller),
    sellerKey=TML41_CleanUser(seller),
    buyer=TML41_UserText(buyer),
    buyerKey=TML41_CleanUser(buyer),
    itemLink=itemLink,
    quantity=quantity,
    price=tonumber(price) or 0,
    tax=tax,
    raw=vals,
  }
end

function TML41_SaleKey(guildId,eventId,sellerKey,gross,timestamp,itemLink,quantity,index)
  if eventId and tostring(eventId) ~= "" and tostring(eventId) ~= "0" then return "sale:"..tostring(guildId or 0)..":event:"..tostring(eventId) end
  return table.concat({"sale",tostring(guildId or 0),tostring(index or 0),tostring(sellerKey or ""),tostring(tonumber(gross) or 0),tostring(tonumber(timestamp) or 0),tostring(itemLink or ""),tostring(tonumber(quantity) or 1)},":")
end

function TML:V21692_AddSale(guildId,parsed,current,index)
  self:V21692_EnsureCore()
  parsed = parsed or {}
  local gross = tonumber(parsed.price) or 0
  if gross <= 0 then return false,false,"bad amount" end
  local ts = tonumber(parsed.timestamp) or 0
  local review = false
  if ts <= 0 then ts = TML41_Now(); review = true end
  local sellerKey = TML41_CleanUser(parsed.sellerKey or parsed.seller)
  if sellerKey == "" then review = true end
  local qty = tonumber(parsed.quantity) or 1; if qty <= 0 then qty = 1 end
  local fee = TML41_Fee(gross)
  local net = math.max(0,gross-fee)
  local tax = tonumber(parsed.tax) or TML41_GuildTax(gross)
  local key = TML41_SaleKey(guildId,parsed.eventId,sellerKey,gross,ts,parsed.itemLink,qty,index)
  local existed = self.saved.retainedSalesEvents[key] ~= nil
  self.saved.retainedSalesEvents[key] = {
    key=key,guildId=guildId,eventId=parsed.eventId,seller=parsed.seller ~= "" and parsed.seller or TML41_NA(),sellerRaw=parsed.seller or "",sellerKey=sellerKey,
    buyer=parsed.buyer or "",buyerKey=parsed.buyerKey or "",amount=net,netAmount=net,grossAmount=gross,feeAmount=fee,guildTax=tax,tax=tax,feeAdjusted=true,
    timestamp=ts,itemLink=parsed.itemLink,itemName=(WGetItemName and WGetItemName(parsed.itemLink)) or tostring(parsed.itemLink or "Sale"),quantity=qty,review=review,
    rawSeller=parsed.seller or "",rawBuyer=parsed.buyer or "",
  }
  if current then self.saved.currentScan.sales[key] = true end
  self.saved.salesEvents = self.saved.retainedSalesEvents
  return not existed,existed,nil
end

-- Override sales scan: one canonical Phase 41 path for personal/guild sales source rows.
function TML:ScanGuildSales(g,noRender,noReset)
  self:V21692_EnsureCore()
  if not g or not g.id or g.id == 0 then return 0 end
  if not noReset then self.saved.currentScan.sales = {}; self.saved.currentScan.salesGuilds = {} end
  self.saved.currentScan.salesGuilds = self.saved.currentScan.salesGuilds or {}
  local cat = self:GetHistoryCategory("trader")
  if type(GetGuildHistoryTraderEventInfo) ~= "function" or not cat then self.saved.scanStatus.sales = "Sales history API unavailable"; return 0 end
  local newest,oldest = self:GetHistoryIndices(g.id,cat,WORKING_HISTORY_DAYS)
  local scanned,accepted,newRows,updatedRows,review,missingSeller,personalRows = 0,0,0,0,0,0,0
  local my = TML41_CleanUser(self:GetUserDisplayName())
  if oldest and newest and oldest >= newest then
    for i=newest,oldest do
      local vals = {pcall(GetGuildHistoryTraderEventInfo,g.id,i)}
      local ok = table.remove(vals,1)
      if ok then
        local p = self:V21692_ParseTrader(vals,i)
        if not p.isRedacted and p.price and p.price > 0 then
          scanned = scanned + 1
          if not p.sellerKey or p.sellerKey == "" then missingSeller = missingSeller + 1; review = review + 1 end
          if p.sellerKey == my then personalRows = personalRows + 1 end
          local added,existed = self:V21692_AddSale(g.id,p,true,i)
          if added or existed then accepted = accepted + 1 end
          if added then newRows = newRows + 1 elseif existed then updatedRows = updatedRows + 1 end
        else
          review = review + 1
        end
      else
        review = review + 1
      end
    end
  end
  self.saved.currentScan.salesGuilds[tostring(g.id)] = {name=tostring(g.name or g.id),scanned=scanned,accepted=accepted,newRows=newRows,updatedRows=updatedRows,reviewRows=review,missingSeller=missingSeller,personalRows=personalRows}
  if self.RequestHistory then self:RequestHistory(g.id,cat,WORKING_HISTORY_DAYS) end
  if self.RebuildPriceCacheFromSales then self:RebuildPriceCacheFromSales() end
  self.saved.ledgerMeta.sales = {currentRows=accepted,newRows=newRows,updatedRows=updatedRows,retainedRows=TML41_Count(self.saved.retainedSalesEvents),reviewRows=review,missingSeller=missingSeller,personalCurrentRows=personalRows,lastGuild=tostring(g.name or g.id),lastScan=TML41_Now()}
  self.saved.scanStatus.sales = "Current guild scan for "..tostring(g.name or "guild")..": "..tostring(accepted).." sale rows / "..tostring(personalRows).." yours / "..tostring(newRows).." new retained."
  if not noRender then self:RenderTool(self.state.activeTool or "guild_sales") end
  return accepted
end

function TML:ScanSelectedGuildSales(noRender)
  local n = self:ScanGuildSales(self:GetGuild(),true,false)
  if not noRender then self:RenderTool(self.state.activeTool or "guild_sales") end
  return n
end

function TML:V21692_SalesCoverage()
  self:V21692_EnsureCore()
  local my = TML41_CleanUser(self:GetUserDisplayName())
  local c = {guildsTotal=0,guildsWithRows=0,guildRowsThisScan=0,personalRowsThisScan=0,personalAllRows=0,personal24Rows=0,retainedRows=TML41_Count(self.saved.retainedSalesEvents),reviewRows=0,sellerMissing=0,sellerNonMatch=0,oldest=nil,newest=nil,coverage="Press Scan All"}
  if self.EachGuild then self:EachGuild(function(_) c.guildsTotal = c.guildsTotal + 1 end) end
  local guildSeen = {}
  for key,e in pairs(self.saved.retainedSalesEvents or {}) do
    if type(e) == "table" then
      local gid=e.guildId or 0; if gid and gid ~= 0 then guildSeen[tostring(gid)] = true end
      if e.review then c.reviewRows = c.reviewRows + 1 end
      local sk = TML41_CleanUser(e.sellerKey or e.seller or e.sellerRaw)
      if sk == "" or sk == TML41_CleanUser(TML41_NA()) then c.sellerMissing = c.sellerMissing + 1 elseif sk ~= my then c.sellerNonMatch = c.sellerNonMatch + 1 end
      if self.saved.currentScan and self.saved.currentScan.sales and self.saved.currentScan.sales[key] then
        c.guildRowsThisScan = c.guildRowsThisScan + 1
        if sk == my then c.personalRowsThisScan = c.personalRowsThisScan + 1 end
      end
      if sk == my then
        c.personalAllRows = c.personalAllRows + 1
        if TML41_Is24(e.timestamp) then c.personal24Rows = c.personal24Rows + 1 end
        local ts=tonumber(e.timestamp) or 0
        if ts > 0 and (not c.oldest or ts < c.oldest) then c.oldest = ts end
        if ts > 0 and (not c.newest or ts > c.newest) then c.newest = ts end
      end
    end
  end
  for _ in pairs(guildSeen) do c.guildsWithRows = c.guildsWithRows + 1 end
  local meta = self.saved.ledgerMeta and self.saved.ledgerMeta.sales or {}
  c.newRows = tonumber(meta.newRows) or 0
  c.updatedRows = tonumber(meta.updatedRows) or 0
  if c.personalAllRows > 0 then c.coverage = (c.guildsTotal > 0 and c.guildsWithRows < c.guildsTotal) and "Partial - Load Guild History" or "Loaded"
  elseif c.retainedRows > 0 then c.coverage = "No @UserID Seller Rows"
  else c.coverage = "Press Scan All" end
  return c
end

function TML:ScanAllGuildSales(noRender)
  self:V21692_EnsureCore()
  self.saved.currentScan.sales = {}
  self.saved.currentScan.salesGuilds = {}
  local total,nguild,newRows,updatedRows,review,missingSeller,personal = 0,0,0,0,0,0,0
  self:EachGuild(function(g)
    nguild = nguild + 1
    local before = TML41_Count(self.saved.retainedSalesEvents)
    local n = tonumber(self:ScanGuildSales(g,true,true)) or 0
    total = total + n
    local after = TML41_Count(self.saved.retainedSalesEvents)
    if after > before then newRows = newRows + (after-before) end
    local gm = (self.saved.currentScan.salesGuilds or {})[tostring(g.id)] or {}
    updatedRows = updatedRows + (tonumber(gm.updatedRows) or 0)
    review = review + (tonumber(gm.reviewRows) or 0)
    missingSeller = missingSeller + (tonumber(gm.missingSeller) or 0)
    personal = personal + (tonumber(gm.personalRows) or 0)
  end)
  local cov = self:V21692_SalesCoverage()
  self.saved.ledgerMeta.sales = {currentRows=total,newRows=newRows,updatedRows=updatedRows,retainedRows=TML41_Count(self.saved.retainedSalesEvents),reviewRows=review,missingSeller=missingSeller,guilds=nguild,guildsWithRows=cov.guildsWithRows,personalCurrentRows=cov.personalRowsThisScan,personalAllRows=cov.personalAllRows,personal24Rows=cov.personal24Rows,oldest=cov.oldest,newest=cov.newest,lastScan=TML41_Now(),coverage=cov.coverage}
  self.saved.scanStatus.sales = "Coverage: "..tostring(cov.coverage)..". Current scan: "..tostring(total).." guild sale rows / "..tostring(cov.personalRowsThisScan).." yours. All-Time Loaded: "..tostring(cov.personalAllRows).." @UserID rows / "..tostring(cov.personal24Rows).." 24H."
  if not noRender then self:RenderTool(self.state.activeTool or "personal_sales") end
  return total
end
function TML:ScanPersonalSales(noRender)
  local total = self:ScanAllGuildSales(true)
  local cov = self:V21692_SalesCoverage()
  self.saved.scanStatus.sales = "Current scan saw "..tostring(total).." guild sale rows and "..tostring(cov.personalRowsThisScan).." @UserID seller rows. All-Time Loaded keeps "..tostring(cov.personalAllRows).." @UserID rows."
  if not noRender then self:RenderTool("personal_sales") end
  return cov.personalAllRows or 0
end

function TML:GetSalesRows(guildId,onlyMe)
  self:V21692_EnsureCore()
  local rows = {}
  local my = TML41_CleanUser(self:GetUserDisplayName())
  for _,e in pairs(self.saved.retainedSalesEvents or self.saved.salesEvents or {}) do
    if type(e) == "table" then
      local okGuild = (not guildId or guildId == 0 or e.guildId == guildId)
      local sellerKey = TML41_CleanUser(e.sellerKey or e.seller or e.sellerRaw)
      if okGuild and ((not onlyMe) or sellerKey == my) then rows[#rows+1] = e end
    end
  end
  table.sort(rows,function(a,b) return (tonumber(a.timestamp) or 0) > (tonumber(b.timestamp) or 0) end)
  return rows
end
function TML:GetSalesRows24H(guildId,onlyMe)
  local out={}
  for _,e in ipairs(self:GetSalesRows(guildId,onlyMe)) do if TML41_Is24(e.timestamp) then out[#out+1]=e end end
  return out
end
function TML:ComputeSalesStats(guildId,onlyMe)
  local rows = self:GetSalesRows(guildId,onlyMe)
  local st={sales24=0,salesToday=0,totalSales=0,allTimeSales=0,items=0,tax=0,fees=0,gross=0,net=0,topEarner=TML41_NA(),topAmount=0,deltaPct=nil,rowCount=#rows,review=0,currentRows=(self.saved and self.saved.ledgerMeta and self.saved.ledgerMeta.sales and self.saved.ledgerMeta.sales.currentRows) or 0}
  local sellers={}
  for _,e in ipairs(rows) do
    local net=tonumber(e.netAmount or e.amount) or 0; local gross=tonumber(e.grossAmount) or net; local fee=tonumber(e.feeAmount) or TML41_Fee(gross); local guildTax=tonumber(e.guildTax or e.tax) or TML41_GuildTax(gross)
    if TML41_Is24(e.timestamp) then st.sales24=st.sales24+net; st.salesToday=st.salesToday+net end
    st.totalSales=st.totalSales+net; st.allTimeSales=st.allTimeSales+net; st.gross=st.gross+gross; st.fees=st.fees+fee; st.tax=st.tax+guildTax; st.net=st.net+net; st.items=st.items+(tonumber(e.quantity) or 1)
    if e.review then st.review=st.review+1 end
    local u=e.seller or TML41_NA(); sellers[u]=(sellers[u] or 0)+net
  end
  for u,v in pairs(sellers) do if v > st.topAmount then st.topAmount=v; st.topEarner=u end end
  if st.totalSales > 0 then st.deltaPct = (st.sales24/st.totalSales)*100 end
  return st
end

function TML:ScanPersonalGoldLedger()
  self:V21692_EnsureCore()
  self.saved.currentScan.personalGold = {}
  self.saved.goldSnapshots = self.saved.goldSnapshots or {}; self.saved.goldSnapshots.history = self.saved.goldSnapshots.history or {}
  local carried=tonumber(self:GetCarriedGoldLive()) or 0; local bank=tonumber(self:GetBankGoldLive()); local total=carried+(bank or 0); local now=TML41_Now()
  table.insert(self.saved.goldSnapshots.history,{carriedGold=carried,bankedGold=bank,total=total,timestamp=now})
  while #self.saved.goldSnapshots.history > 72 do table.remove(self.saved.goldSnapshots.history,1) end
  self.saved.goldSnapshots.personalLast = {carriedGold=carried,bankedGold=bank,total=total,timestamp=now}

  local saleScanRows = tonumber(self:ScanAllGuildSales(true)) or 0
  local guildGoldSeen = 0
  self:EachGuild(function(g) if self.ScanGuildGold then local rg=self:ScanGuildGold(g); guildGoldSeen = guildGoldSeen + (tonumber(rg) or 0) end end)

  local my = self:GetUserDisplayName(); local added,updated,review = 0,0,0
  for sk,s in pairs(self.saved.retainedSalesEvents or {}) do
    if type(s)=="table" and TML41_SameUser(s.sellerKey or s.seller,my) then
      local amt=tonumber(s.netAmount or s.amount) or 0
      if amt > 0 then
        local key=TML89_PersonalGoldKey and TML89_PersonalGoldKey("sale",s.guildId,s.timestamp,amt,"in",sk) or ("pg:sale:"..tostring(sk))
        local cur=(self.saved.currentScan.sales or {})[sk] == true
        local isNew,isOld=TML89_AddPersonalGold(self,key,{timestamp=s.timestamp,user=my,source="Guild Trader Sale",amount=amt,direction="in",note=self:GetGuildName(s.guildId),guildId=s.guildId,sourceKey=sk},cur)
        if isNew then added=added+1 elseif isOld and cur then updated=updated+1 end
      end
    end
  end
  for _,e in pairs(self.saved.guildGoldEvents or {}) do
    if type(e)=="table" and TML41_SameUser(e.user,my) then
      local b=tostring(e.bucket or ""); local amt=tonumber(e.amount) or 0; local action=tostring(e.action or "")
      local dir,source,note=nil,nil,b
      if action=="deposit" and (b=="Donation" or b=="Ticket" or b=="Giveaway Ticket" or b=="Reset") then dir="out"; source="Guild Bank Deposit"
      elseif action=="withdraw" and (b=="Withdrawal" or b=="Other / Review" or b=="Withdraw") then dir="in"; source="Guild Bank Withdrawal"
      else review=review+1 end
      if dir and amt>0 then
        local key=TML89_PersonalGoldKey and TML89_PersonalGoldKey("guildgold",e.guildId,e.timestamp,amt,dir,tostring(b)..":"..tostring(e.user)) or ("pg:guild:"..tostring(e.guildId)..":"..tostring(e.timestamp)..":"..tostring(amt)..":"..dir)
        local isNew,isOld=TML89_AddPersonalGold(self,key,{timestamp=e.timestamp,user=my,source=source,amount=amt,direction=dir,note=note,guildId=e.guildId},true)
        if isNew then added=added+1 elseif isOld then updated=updated+1 end
      end
    end
  end
  local retained=TML41_Count(self.saved.retainedPersonalGoldEvents); local current=TML41_Count(self.saved.currentScan.personalGold)
  self.saved.ledgerMeta.personalGold={currentRows=current,newRows=added,updatedRows=updated,retainedRows=retained,reviewRows=review,lastScan=now,salesRows=saleScanRows,guildGoldRows=guildGoldSeen}
  self.saved.scanStatus.personalGold="Current scan: "..tostring(current).." personal gold rows seen / "..tostring(added).." new / "..tostring(retained).." all-time loaded retained / "..tostring(review).." review."
  if self.MarkScanned then self:MarkScanned(current>0 and "Scanned" or "No New Rows", current>0) end
end

function TML:ComputePersonalGoldStats()
  self:V21692_EnsureCore()
  local st={current=tonumber(self:GetCarriedGoldLive()) or 0,bank=tonumber(self:GetBankGoldLive()),in24=0,out24=0,verifiedNet24=0,net24=0,allIn=0,allOut=0,allNet=0,actualNet24=nil,unmatched24=nil,coverage="Need 24H Baseline",scanned=(self.saved.scanStatus and self.saved.scanStatus.personalGold~=nil)}
  for _,e in ipairs(self:GetPersonalGoldRows("Recent") or {}) do
    local amt=tonumber(e.amount) or 0
    if e.direction=="in" then st.allIn=st.allIn+amt; if TML41_Is24(e.timestamp) then st.in24=st.in24+amt end
    elseif e.direction=="out" then st.allOut=st.allOut+amt; if TML41_Is24(e.timestamp) then st.out24=st.out24+amt end end
  end
  st.verifiedNet24=st.in24-st.out24; st.net24=st.verifiedNet24; st.allNet=st.allIn-st.allOut
  local total=st.current+(st.bank or 0); local hist=self.saved.goldSnapshots and self.saved.goldSnapshots.history or {}; local target=TML41_Now()-86400; local base=nil; local earliest=nil
  for _,s in ipairs(hist) do
    if tonumber(s.total) and tonumber(s.timestamp) then
      if not earliest or (tonumber(s.timestamp) or 0)<(tonumber(earliest.timestamp) or 0) then earliest=s end
      if (tonumber(s.timestamp) or 0)<=target and ((not base) or (tonumber(s.timestamp) or 0)>(tonumber(base.timestamp) or 0)) then base=s end
    end
  end
  if base then st.actualNet24=total-(tonumber(base.total) or 0); st.coverage="Full 24H"
  elseif earliest then local hours=math.floor((TML41_Now()-(tonumber(earliest.timestamp) or 0))/3600); if hours and hours>0 then st.actualNet24=total-(tonumber(earliest.total) or 0); st.coverage="Partial "..tostring(hours).."h" end end
  if st.actualNet24 ~= nil then st.unmatched24=st.actualNet24-st.verifiedNet24 end
  return st
end

-- Raffle ticket cost helpers.
function TML:V21692_RaffleKey(guildId,mode) return tostring(guildId or 0)..":"..tostring(mode or "gold") end
function TML:GetRaffleTicketCost(guildId,mode)
  self:V21692_EnsureCore()
  mode = mode or (self.GetRaffleMode and self:GetRaffleMode(guildId)) or "gold"
  local key = self:V21692_RaffleKey(guildId,mode)
  local r = self.GetRaffle and self:GetRaffle(guildId,mode) or nil
  local cost = (r and tonumber(r.ticketCost)) or tonumber(self.saved.raffleTicketCost[key]) or 1000
  cost = math.max(1, math.floor(cost))
  if r then r.ticketCost = cost end
  self.saved.raffleTicketCost[key] = cost
  return cost
end
function TML:SaveRaffleTicketCost(amount)
  local g=self:GetGuild(); if not g or not g.id then return end
  local mode=(self.GetRaffleMode and self:GetRaffleMode(g.id)) or "gold"
  local cost=math.max(1,math.floor(tonumber(amount) or 1000))
  local r=self:GetRaffle(g.id,mode); r.ticketCost=cost
  self.saved.raffleTicketCost[self:V21692_RaffleKey(g.id,mode)] = cost
  self.saved.scanStatus.raffle = "Ticket cost saved: "..TML41_Gold(cost).." = 1 ticket."
  if self.MarkScanned then self:MarkScanned("Saved",true) end
  self:RenderTool("guild_raffle")
end
function TML:RaffleTicketsFromGold(amount,guildId,mode)
  local cost=self:GetRaffleTicketCost(guildId or (self:GetGuild() and self:GetGuild().id),mode)
  amount=tonumber(amount) or 0
  return math.max(0, math.floor(amount / math.max(1,cost)))
end

-- Override scan entries to use manual ticket cost for ticket count while keeping suffix/rule detection.
function TML:ScanRaffleEntries(noRender)
  self:V21692_EnsureCore()
  local g=self:GetGuild(); if not g or not g.id or g.id==0 then self:Notify("Select a guild before scanning raffle entries."); return end
  if self.ScanGuildGold then self:ScanGuildGold(g) end
  local mode=(self.GetRaffleMode and self:GetRaffleMode(g.id)) or "gold"
  local r=self:GetRaffle(g.id,mode); r.entries={}; r.winners={}; r.lastScan=TML41_Now(); local reset=self:FindRaffleResetTime(g.id,mode); r.started=reset
  local cost=self:GetRaffleTicketCost(g.id,mode); local deposits,tickets,skipped=0,0,0
  for _,e in ipairs(self:GetRaffleSourceEvents(g.id) or {}) do
    local ts=tonumber(e.timestamp) or 0; local amount=tonumber(e.amount) or 0
    local valid=false
    if self.IsRaffleTicketAmountForMode then valid=self:IsRaffleTicketAmountForMode(mode,amount) else valid=V21668_EventIsTicket and V21668_EventIsTicket(e) end
    local isReset = self.IsRaffleResetAmount and self:IsRaffleResetAmount(g.id,mode,amount)
    if ts >= reset and valid and not isReset then
      local t=self:RaffleTicketsFromGold(amount,g.id,mode)
      if t > 0 then
        local user=tostring(e.user or TML41_NA()); local key=(V21673_UserKey and V21673_UserKey(user)) or TML41_CleanUser(user)
        local existing=r.entries[key] or {name=user,tickets=0,gold=0,last=0,entryType=""}
        existing.tickets=(tonumber(existing.tickets) or 0)+t; existing.gold=(tonumber(existing.gold) or 0)+amount
        existing.entryType=mode=="giveaway" and ((V21673_EndsWith and V21673_EndsWith(amount,2)) and "002" or "003") or "001"
        if ts>(tonumber(existing.last) or 0) then existing.last=ts end
        r.entries[key]=existing; deposits=deposits+1; tickets=tickets+t
      else skipped=skipped+1 end
    elseif valid and ts < reset then skipped=skipped+1 end
  end
  self.saved.scanStatus.raffle = deposits>0 and ("Scanned "..deposits.." valid deposits / "..tickets.." tickets at "..TML41_Gold(cost).." per ticket") or ("No valid entries after reset. Ticket cost: "..TML41_Gold(cost))
  if self.MarkScanned then self:MarkScanned(deposits>0 and "Scanned" or "No Data", deposits>0) end
  if not noRender then self:RenderTool("guild_raffle") end
end

