function TML_21693_Patch()

-- =========================================================
-- v2.0.16.93 PHASE 42 - SALES PARSER + GUILD/PERSONAL LEDGER SOURCE FIX
-- Built from v2.0.16.92 rollback line. Does not touch menu/scene/input registration.
-- Fixes shared sales source parsing so Personal Sales, Guild Sales, and Personal Gold Ledger
-- all read the same verified retained sales ledger.
-- =========================================================
local TML42 = {}
TML42.VERSION = "2.0.16.93"
TML42.ADDON_VERSION = 21693
TML42.UPDATED = "06/22/2026 23:20 UTC"
TML42.PAGE_UPDATED = {
  main = TML42.UPDATED,
  personal_sales = "06/22/2026",
  guild_sales = "06/22/2026",
  gold_ledger_personal = "06/22/2026",
}

local function TML42_Now() return (GetTimeStamp and GetTimeStamp()) or os.time() end
local function TML42_Gold(v) return WFormatGold and WFormatGold(tonumber(v) or 0) or tostring(tonumber(v) or 0).."g" end
local function TML42_Num(v) return WFormatNumber and WFormatNumber(tonumber(v) or 0) or tostring(tonumber(v) or 0) end
local function TML42_Cell(t,c) return VCell and VCell(t,c) or tostring(t or "") end
local function TML42_Limit(s,n) return WLimit and WLimit(s,n) or tostring(s or "") end
local function TML42_Rel(ts) return WRelTime and WRelTime(ts) or tostring(ts or "") end
local function TML42_NA() return WNA and WNA() or "N/A" end
local function TML42_Count(t) local n=0; for _ in pairs(t or {}) do n=n+1 end; return n end
local function TML42_Is24(ts) ts=tonumber(ts) or 0; return ts>0 and (TML42_Now()-ts)<=86400 end
local function TML42_Fee(gross) gross=tonumber(gross) or 0; return math.floor(gross*0.07+0.5) end
local function TML42_GuildTax(gross) gross=tonumber(gross) or 0; return math.floor(gross*0.035+0.5) end
local function TML42_Trim(s) return (tostring(s or ""):gsub("|c%x%x%x%x%x%x",""):gsub("|r",""):gsub("^%s+",""):gsub("%s+$","")) end
local function TML42_IsItemLink(s) return type(s)=="string" and s:find("|H",1,true) ~= nil end
local function TML42_ExtractUser(s)
  s = TML42_Trim(s)
  if s == "" or TML42_IsItemLink(s) then return "" end
  local at = s:match("(@[%w%._%-]+)") or s:match("(@[^%s|]+)")
  if at and at ~= "" then return at end
  return s
end
local function TML42_CleanUser(s)
  local u = TML42_ExtractUser(s)
  u = u:gsub("^@",""):gsub("^%s+",""):gsub("%s+$","")
  return string.lower(u)
end
local function TML42_UserDisplay(s)
  local u = TML42_ExtractUser(s)
  if u == "" then return "" end
  if u:sub(1,1) ~= "@" and not u:find("%s") then u = "@"..u end
  return u
end
local function TML42_IsUserString(s) return TML42_CleanUser(s) ~= "" and not TML42_IsItemLink(s) end
local function TML42_SameUser(a,b) local aa=TML42_CleanUser(a); local bb=TML42_CleanUser(b); return aa ~= "" and aa == bb end
local function TML42_SafeNum(v) local n=tonumber(v); if n then return n end return nil end
local function TML42_IsUnix(v) v=tonumber(v) or 0; return v > 1000000000 and v < 4102444800 end

function TML:V21693_EnsureCore()
  if self.V21692_EnsureCore then self:V21692_EnsureCore() else self:EnsureDataDefaults() end
  self.saved = self.saved or self:Defaults()
  self.saved.retainedSalesEvents = self.saved.retainedSalesEvents or {}
  self.saved.retainedPersonalGoldEvents = self.saved.retainedPersonalGoldEvents or {}
  self.saved.currentScan = self.saved.currentScan or {}
  self.saved.currentScan.sales = self.saved.currentScan.sales or {}
  self.saved.currentScan.salesGuilds = self.saved.currentScan.salesGuilds or {}
  self.saved.currentScan.personalGold = self.saved.currentScan.personalGold or {}
  self.saved.ledgerMeta = self.saved.ledgerMeta or {}
  self.saved.ledgerMeta.sales = self.saved.ledgerMeta.sales or {}
  self.saved.ledgerMeta.personalGold = self.saved.ledgerMeta.personalGold or {}
  for k,e in pairs(self.saved.salesEvents or {}) do if type(e)=="table" then self.saved.retainedSalesEvents[tostring(k)] = e end end
  for k,e in pairs(self.saved.personalGoldEvents or {}) do if type(e)=="table" then self.saved.retainedPersonalGoldEvents[tostring(k)] = e end end
  self.saved.salesEvents = self.saved.retainedSalesEvents
  self.saved.personalGoldEvents = self.saved.retainedPersonalGoldEvents
end

function TML:V21693_FallbackHistoryMeta(guildId,category,index)
  local out = {eventId=nil,timestamp=nil,isRedacted=nil,eventType=nil}
  if type(GetGuildHistoryEventInfo) == "function" then
    local vals = {pcall(GetGuildHistoryEventInfo,guildId,category,index)}
    local ok = table.remove(vals,1)
    if ok then
      for _,v in ipairs(vals) do
        if type(v)=="number" then
          if TML42_IsUnix(v) and not out.timestamp then out.timestamp = v
          elseif not out.eventId and v and v > 0 and v < 1000000000 then out.eventId = v end
        elseif type(v)=="boolean" and out.isRedacted == nil then
          out.isRedacted = v
        end
      end
    end
  end
  return out
end

function TML:V21693_ParseTrader(vals,index,guildId,category)
  vals = vals or {}
  local strings, users, nums = {}, {}, {}
  local itemIdx, itemLink = nil, nil
  for i,v in ipairs(vals) do
    if type(v)=="string" then
      strings[#strings+1] = {i=i,v=v}
      if TML42_IsItemLink(v) and not itemLink then itemIdx=i; itemLink=v
      elseif TML42_IsUserString(v) then users[#users+1] = {i=i,v=v,key=TML42_CleanUser(v)} end
    elseif type(v)=="number" then
      nums[#nums+1] = {i=i,v=v}
    end
  end

  local looksOld = (#vals >= 10 and (TML42_IsItemLink(vals[7]) or TML42_IsUserString(vals[5]) or TML42_IsUnix(vals[2])))
  local meta = self:V21693_FallbackHistoryMeta(guildId,category,index)
  local eventId = looksOld and vals[1] or meta.eventId
  local timestamp = looksOld and vals[2] or meta.timestamp
  local isRedacted = looksOld and (vals[3] == true) or (meta.isRedacted == true)
  local eventType = looksOld and vals[4] or vals[1]
  local seller = looksOld and vals[5] or nil
  local buyer = looksOld and vals[6] or nil
  local quantity = looksOld and vals[8] or nil
  local price = looksOld and vals[9] or nil
  local tax = looksOld and vals[10] or nil

  if itemIdx and not looksOld then
    seller = vals[itemIdx-3] or seller
    buyer = vals[itemIdx-2] or buyer
    quantity = vals[itemIdx-1] or quantity
    price = vals[itemIdx+1] or price
    tax = vals[itemIdx+2] or tax
  end
  if not itemLink and TML42_IsItemLink(vals[7]) then itemLink = vals[7]; itemIdx = 7 end
  if not itemLink then for _,s in ipairs(strings) do if TML42_IsItemLink(s.v) then itemLink=s.v; itemIdx=s.i; break end end end

  if not TML42_IsUserString(seller) then seller = nil end
  if not TML42_IsUserString(buyer) then buyer = nil end
  if not seller and users[1] then seller = users[1].v end
  if not buyer and users[2] then buyer = users[2].v end

  if not TML42_IsUnix(timestamp) then
    timestamp = nil
    for _,n in ipairs(nums) do if TML42_IsUnix(n.v) then timestamp=n.v; break end end
  end

  quantity = tonumber(quantity) or 1
  if quantity <= 0 or quantity > 200000 then quantity = 1 end

  price = tonumber(price) or 0
  if price <= 0 and itemIdx and tonumber(vals[itemIdx+1]) and tonumber(vals[itemIdx+1]) > 0 then price = tonumber(vals[itemIdx+1]) or 0 end
  if price <= 0 and tonumber(vals[9]) and tonumber(vals[9]) > 0 then price = tonumber(vals[9]) or 0 end
  if price <= 0 then
    local best = 0
    for _,n in ipairs(nums) do
      local idx, val = n.i, tonumber(n.v) or 0
      local isQty = (itemIdx and idx == itemIdx-1) or idx == 8
      local isTax = (itemIdx and idx == itemIdx+2) or idx == 10
      if val > best and val > 0 and val < 1000000000 and not TML42_IsUnix(val) and not isQty and not isTax then best = val end
    end
    price = best
  end
  tax = tonumber(tax) or 0
  if tax <= 0 and itemIdx and tonumber(vals[itemIdx+2]) and tonumber(vals[itemIdx+2]) >= 0 then tax = tonumber(vals[itemIdx+2]) or 0 end
  if tax < 0 or (price and price > 0 and tax > price) then tax = 0 end

  local sellerDisplay = TML42_UserDisplay(seller)
  local buyerDisplay = TML42_UserDisplay(buyer)
  local sellerKey = TML42_CleanUser(sellerDisplay ~= "" and sellerDisplay or seller)
  local buyerKey = TML42_CleanUser(buyerDisplay ~= "" and buyerDisplay or buyer)
  local review = false
  if sellerKey == "" or price <= 0 or not itemLink or itemLink == "" or not timestamp or tonumber(timestamp) == nil or tonumber(timestamp) <= 0 then review = true end
  return {
    eventId = eventId,
    timestamp = tonumber(timestamp) or 0,
    isRedacted = isRedacted,
    eventType = eventType,
    seller = sellerDisplay,
    sellerRaw = TML42_Trim(seller),
    sellerKey = sellerKey,
    buyer = buyerDisplay,
    buyerRaw = TML42_Trim(buyer),
    buyerKey = buyerKey,
    itemLink = itemLink,
    quantity = quantity,
    price = tonumber(price) or 0,
    tax = tax,
    review = review,
    rawCount = #vals,
  }
end

local function TML42_SaleKey(guildId,eventId,sellerKey,gross,timestamp,itemLink,quantity,index)
  if eventId and tostring(eventId) ~= "" and tostring(eventId) ~= "0" then return "sale:"..tostring(guildId or 0)..":event:"..tostring(eventId) end
  return table.concat({"sale",tostring(guildId or 0),tostring(index or 0),tostring(sellerKey or ""),tostring(tonumber(gross) or 0),tostring(tonumber(timestamp) or 0),tostring(itemLink or ""),tostring(tonumber(quantity) or 1)},":")
end

function TML:V21693_AddSale(guildId,parsed,current,index)
  self:V21693_EnsureCore()
  parsed = parsed or {}
  local gross = tonumber(parsed.price) or 0
  if gross <= 0 then return false,false,"bad amount" end
  local qty = tonumber(parsed.quantity) or 1; if qty <= 0 then qty = 1 end
  local ts = tonumber(parsed.timestamp) or 0
  local review = parsed.review == true
  local fee = TML42_Fee(gross)
  local net = math.max(0,gross-fee)
  local guildTax = tonumber(parsed.tax) or TML42_GuildTax(gross)
  local sellerKey = TML42_CleanUser(parsed.sellerKey or parsed.seller or parsed.sellerRaw)
  local sellerDisplay = parsed.seller and parsed.seller ~= "" and parsed.seller or (sellerKey ~= "" and ("@"..sellerKey) or TML42_NA())
  local key = TML42_SaleKey(guildId,parsed.eventId,sellerKey,gross,ts,parsed.itemLink,qty,index)
  local existed = self.saved.retainedSalesEvents[key] ~= nil
  self.saved.retainedSalesEvents[key] = {
    key=key,guildId=guildId,eventId=parsed.eventId,
    seller=sellerDisplay,sellerRaw=parsed.sellerRaw or sellerDisplay,sellerKey=sellerKey,
    buyer=parsed.buyer or "",buyerRaw=parsed.buyerRaw or parsed.buyer or "",buyerKey=TML42_CleanUser(parsed.buyerKey or parsed.buyer),
    amount=net,netAmount=net,grossAmount=gross,feeAmount=fee,guildTax=guildTax,tax=guildTax,feeAdjusted=true,
    timestamp=ts,itemLink=parsed.itemLink,itemName=(WGetItemName and WGetItemName(parsed.itemLink)) or tostring(parsed.itemLink or "Sale"),quantity=qty,
    review=review,parser="v21693",rawCount=parsed.rawCount,
  }
  if current then self.saved.currentScan.sales[key] = true end
  self.saved.salesEvents = self.saved.retainedSalesEvents
  return not existed,existed,nil
end

function TML:ScanGuildSales(g,noRender,noReset)
  self:V21693_EnsureCore()
  if not g or not g.id or g.id == 0 then return 0 end
  if not noReset then self.saved.currentScan.sales = {}; self.saved.currentScan.salesGuilds = {} end
  self.saved.currentScan.salesGuilds = self.saved.currentScan.salesGuilds or {}
  local cat = self:GetHistoryCategory("trader")
  if type(GetGuildHistoryTraderEventInfo) ~= "function" or not cat then self.saved.scanStatus.sales = "Sales history API unavailable"; return 0 end
  if self.RequestHistory then self:RequestHistory(g.id,cat,WORKING_HISTORY_DAYS) end
  local newest,oldest = self:GetHistoryIndices(g.id,cat,WORKING_HISTORY_DAYS)
  local scanned,accepted,newRows,updatedRows,review,missingSeller,personalRows,sellerParsed = 0,0,0,0,0,0,0,0
  local my = TML42_CleanUser(self:GetUserDisplayName())
  if oldest and newest and oldest >= newest then
    for i=newest,oldest do
      local vals = {pcall(GetGuildHistoryTraderEventInfo,g.id,i)}
      local ok = table.remove(vals,1)
      if ok then
        local p = self:V21693_ParseTrader(vals,i,g.id,cat)
        if not p.isRedacted and p.price and p.price > 0 then
          scanned = scanned + 1
          if p.sellerKey and p.sellerKey ~= "" then sellerParsed = sellerParsed + 1 else missingSeller = missingSeller + 1; review = review + 1 end
          if p.review then review = review + 1 end
          if p.sellerKey == my then personalRows = personalRows + 1 end
          local added,existed = self:V21693_AddSale(g.id,p,true,i)
          if added or existed then accepted = accepted + 1 end
          if added then newRows = newRows + 1 elseif existed then updatedRows = updatedRows + 1 end
        else
          review = review + 1
        end
      else
        review = review + 1
      end
    end
  end
  self.saved.currentScan.salesGuilds[tostring(g.id)] = {name=tostring(g.name or g.id),scanned=scanned,accepted=accepted,newRows=newRows,updatedRows=updatedRows,reviewRows=review,missingSeller=missingSeller,sellerParsed=sellerParsed,personalRows=personalRows,historyReady=accepted>0 or scanned>0}
  if self.RebuildPriceCacheFromSales then self:RebuildPriceCacheFromSales() end
  self.saved.ledgerMeta.sales = {currentRows=accepted,newRows=newRows,updatedRows=updatedRows,retainedRows=TML42_Count(self.saved.retainedSalesEvents),reviewRows=review,missingSeller=missingSeller,sellerParsed=sellerParsed,personalCurrentRows=personalRows,lastGuild=tostring(g.name or g.id),lastScan=TML42_Now()}
  if accepted > 0 then self.saved.scanStatus.sales = "Current guild scan for "..tostring(g.name or "guild")..": "..tostring(accepted).." sale rows / "..tostring(sellerParsed).." sellers parsed / "..tostring(personalRows).." yours."
  else self.saved.scanStatus.sales = "No trader sale rows read for "..tostring(g.name or "guild")..". History requested - open/load Guild History, then scan again." end
  if not noRender then self:RenderTool(self.state.activeTool or "guild_sales") end
  return accepted
end

function TML:ScanSelectedGuildSales(noRender)
  local n = self:ScanGuildSales(self:GetGuild(),true,false)
  if not noRender then self:RenderTool(self.state.activeTool or "guild_sales") end
  return n
end

function TML:V21693_SalesCoverage(guildId)
  self:V21693_EnsureCore()
  local my = TML42_CleanUser(self:GetUserDisplayName())
  local c = {guildsTotal=0,guildsWithRows=0,guildRowsThisScan=0,personalRowsThisScan=0,personalAllRows=0,personal24Rows=0,retainedRows=TML42_Count(self.saved.retainedSalesEvents),reviewRows=0,sellerMissing=0,sellerNonMatch=0,sellerParsed=0,oldest=nil,newest=nil,coverage="Press Scan All",guildRows=0,guild24Rows=0,guildSellerRows=0}
  if self.EachGuild then self:EachGuild(function(_) c.guildsTotal = c.guildsTotal + 1 end) end
  local guildSeen = {}
  for key,e in pairs(self.saved.retainedSalesEvents or {}) do
    if type(e)=="table" then
      local gid = tonumber(e.guildId) or 0
      if gid ~= 0 then guildSeen[tostring(gid)] = true end
      local okGuild = (not guildId or guildId == 0 or gid == guildId)
      local sk = TML42_CleanUser(e.sellerKey or e.seller or e.sellerRaw)
      if okGuild then
        c.guildRows = c.guildRows + 1
        if TML42_Is24(e.timestamp) then c.guild24Rows = c.guild24Rows + 1 end
        if sk ~= "" then c.guildSellerRows = c.guildSellerRows + 1 end
      end
      if e.review then c.reviewRows = c.reviewRows + 1 end
      if sk == "" or sk == TML42_CleanUser(TML42_NA()) then c.sellerMissing = c.sellerMissing + 1 elseif sk ~= my then c.sellerNonMatch = c.sellerNonMatch + 1 end
      if sk ~= "" then c.sellerParsed = c.sellerParsed + 1 end
      if self.saved.currentScan and self.saved.currentScan.sales and self.saved.currentScan.sales[key] then
        if okGuild then c.guildRowsThisScan = c.guildRowsThisScan + 1 end
        if sk == my then c.personalRowsThisScan = c.personalRowsThisScan + 1 end
      end
      if sk == my then
        c.personalAllRows = c.personalAllRows + 1
        if TML42_Is24(e.timestamp) then c.personal24Rows = c.personal24Rows + 1 end
        local ts=tonumber(e.timestamp) or 0
        if ts > 0 and (not c.oldest or ts < c.oldest) then c.oldest = ts end
        if ts > 0 and (not c.newest or ts > c.newest) then c.newest = ts end
      end
    end
  end
  for _ in pairs(guildSeen) do c.guildsWithRows = c.guildsWithRows + 1 end
  local meta = self.saved.ledgerMeta and self.saved.ledgerMeta.sales or {}
  c.newRows = tonumber(meta.newRows) or 0
  c.updatedRows = tonumber(meta.updatedRows) or 0
  if c.personalAllRows > 0 then c.coverage = (c.guildsTotal > 0 and c.guildsWithRows < c.guildsTotal) and "Partial - Load Guild History" or "Loaded"
  elseif c.retainedRows > 0 then c.coverage = "No @UserID Seller Rows"
  else c.coverage = "Press Scan All" end
  return c
end

function TML:ScanAllGuildSales(noRender)
  self:V21693_EnsureCore()
  self.saved.currentScan.sales = {}
  self.saved.currentScan.salesGuilds = {}
  local total,nguild,newRows,updatedRows,review,missingSeller,sellerParsed,personal = 0,0,0,0,0,0,0,0
  self:EachGuild(function(g)
    nguild = nguild + 1
    local before = TML42_Count(self.saved.retainedSalesEvents)
    local n = tonumber(self:ScanGuildSales(g,true,true)) or 0
    total = total + n
    local after = TML42_Count(self.saved.retainedSalesEvents)
    if after > before then newRows = newRows + (after-before) end
    local gm = (self.saved.currentScan.salesGuilds or {})[tostring(g.id)] or {}
    updatedRows = updatedRows + (tonumber(gm.updatedRows) or 0)
    review = review + (tonumber(gm.reviewRows) or 0)
    missingSeller = missingSeller + (tonumber(gm.missingSeller) or 0)
    sellerParsed = sellerParsed + (tonumber(gm.sellerParsed) or 0)
    personal = personal + (tonumber(gm.personalRows) or 0)
  end)
  local cov = self:V21693_SalesCoverage()
  self.saved.ledgerMeta.sales = {currentRows=total,newRows=newRows,updatedRows=updatedRows,retainedRows=TML42_Count(self.saved.retainedSalesEvents),reviewRows=review,missingSeller=missingSeller,sellerParsed=sellerParsed,guilds=nguild,guildsWithRows=cov.guildsWithRows,personalCurrentRows=cov.personalRowsThisScan,personalAllRows=cov.personalAllRows,personal24Rows=cov.personal24Rows,oldest=cov.oldest,newest=cov.newest,lastScan=TML42_Now(),coverage=cov.coverage}
  self.saved.scanStatus.sales = "Coverage: "..tostring(cov.coverage)..". Current scan: "..tostring(total).." guild sale rows / "..tostring(sellerParsed).." sellers parsed / "..tostring(cov.personalRowsThisScan).." yours. All-Time Loaded: "..tostring(cov.personalAllRows).." @UserID rows."
  if total == 0 then self.saved.scanStatus.sales = "No sale rows read. History requested for "..tostring(nguild).." guilds - open/load Guild History, then scan again." end
  if not noRender then self:RenderTool(self.state.activeTool or "personal_sales") end
  return total
end
function TML:ScanPersonalSales(noRender)
  local total = self:ScanAllGuildSales(true)
  local cov = self:V21693_SalesCoverage()
  self.saved.scanStatus.sales = "Current scan saw "..tostring(total).." guild sale rows and "..tostring(cov.personalRowsThisScan).." @UserID seller rows. All-Time Loaded keeps "..tostring(cov.personalAllRows).." @UserID rows."
  if not noRender then self:RenderTool("personal_sales") end
  return cov.personalAllRows or 0
end

function TML:GetSalesRows(guildId,onlyMe)
  self:V21693_EnsureCore()
  local rows = {}
  local my = TML42_CleanUser(self:GetUserDisplayName())
  for _,e in pairs(self.saved.retainedSalesEvents or self.saved.salesEvents or {}) do
    if type(e)=="table" then
      local okGuild = (not guildId or guildId == 0 or tonumber(e.guildId) == tonumber(guildId))
      local sellerKey = TML42_CleanUser(e.sellerKey or e.seller or e.sellerRaw)
      if okGuild and ((not onlyMe) or sellerKey == my) then rows[#rows+1] = e end
    end
  end
  table.sort(rows,function(a,b) return (tonumber(a.timestamp) or 0) > (tonumber(b.timestamp) or 0) end)
  return rows
end
function TML:GetSalesRows24H(guildId,onlyMe)
  local out = {}
  for _,e in ipairs(self:GetSalesRows(guildId,onlyMe)) do if TML42_Is24(e.timestamp) then out[#out+1] = e end end
  return out
end
function TML:ComputeSalesStats(guildId,onlyMe)
  local rows = self:GetSalesRows(guildId,onlyMe)
  local st={sales24=0,salesToday=0,totalSales=0,allTimeSales=0,items=0,tax=0,fees=0,gross=0,net=0,topEarner=TML42_NA(),topAmount=0,deltaPct=nil,rowCount=#rows,review=0,currentRows=(self.saved and self.saved.ledgerMeta and self.saved.ledgerMeta.sales and self.saved.ledgerMeta.sales.currentRows) or 0}
  local sellers = {}
  for _,e in ipairs(rows) do
    local net=tonumber(e.netAmount or e.amount) or 0; local gross=tonumber(e.grossAmount) or net; local fee=tonumber(e.feeAmount) or TML42_Fee(gross); local guildTax=tonumber(e.guildTax or e.tax) or TML42_GuildTax(gross)
    if TML42_Is24(e.timestamp) then st.sales24=st.sales24+net; st.salesToday=st.salesToday+net end
    st.totalSales=st.totalSales+net; st.allTimeSales=st.allTimeSales+net; st.gross=st.gross+gross; st.fees=st.fees+fee; st.tax=st.tax+guildTax; st.net=st.net+net; st.items=st.items+(tonumber(e.quantity) or 1)
    if e.review then st.review=st.review+1 end
    local u=e.seller or TML42_NA(); sellers[u]=(sellers[u] or 0)+net
  end
  for u,v in pairs(sellers) do if v > st.topAmount then st.topAmount=v; st.topEarner=u end end
  if st.totalSales > 0 then st.deltaPct = (st.sales24/st.totalSales)*100 end
  return st
end

function TML:ScanPersonalGoldLedger()
  self:V21693_EnsureCore()
  self.saved.currentScan.personalGold = {}
  self.saved.goldSnapshots = self.saved.goldSnapshots or {}; self.saved.goldSnapshots.history = self.saved.goldSnapshots.history or {}
  local carried=tonumber(self:GetCarriedGoldLive()) or 0; local bank=tonumber(self:GetBankGoldLive()); local total=carried+(bank or 0); local now=TML42_Now()
  table.insert(self.saved.goldSnapshots.history,{carriedGold=carried,bankedGold=bank,total=total,timestamp=now})
  while #self.saved.goldSnapshots.history > 72 do table.remove(self.saved.goldSnapshots.history,1) end
  self.saved.goldSnapshots.personalLast = {carriedGold=carried,bankedGold=bank,total=total,timestamp=now}
  local saleScanRows = tonumber(self:ScanAllGuildSales(true)) or 0
  local guildGoldSeen = 0
  self:EachGuild(function(g) if self.ScanGuildGold then local rg=self:ScanGuildGold(g); guildGoldSeen = guildGoldSeen + (tonumber(rg) or 0) end end)
  local my=self:GetUserDisplayName(); local myKey=TML42_CleanUser(my); local added,updated,review=0,0,0
  for sk,s in pairs(self.saved.retainedSalesEvents or {}) do
    if type(s)=="table" and TML42_CleanUser(s.sellerKey or s.seller or s.sellerRaw) == myKey then
      local amt=tonumber(s.netAmount or s.amount) or 0
      if amt > 0 then
        local key=(TML89_PersonalGoldKey and TML89_PersonalGoldKey("sale",s.guildId,s.timestamp,amt,"in",sk)) or ("pg:sale:"..tostring(sk))
        local cur=(self.saved.currentScan.sales or {})[sk] == true
        local isNew,isOld=TML89_AddPersonalGold(self,key,{timestamp=s.timestamp,user=my,source="Guild Trader Sale",amount=amt,direction="in",note=self:GetGuildName(s.guildId),guildId=s.guildId,sourceKey=sk},cur)
        if isNew then added=added+1 elseif isOld and cur then updated=updated+1 end
      end
    end
  end
  for _,e in pairs(self.saved.guildGoldEvents or {}) do
    if type(e)=="table" and TML42_SameUser(e.user,my) then
      local b=tostring(e.bucket or ""); local amt=tonumber(e.amount) or 0; local action=tostring(e.action or "")
      local dir,source,note=nil,nil,b
      if action=="deposit" and (b=="Donation" or b=="Ticket" or b=="Giveaway Ticket" or b=="Reset") then dir="out"; source="Guild Bank Deposit"
      elseif action=="withdraw" and (b=="Withdrawal" or b=="Other / Review" or b=="Withdraw") then dir="in"; source="Guild Bank Withdrawal"
      else review=review+1 end
      if dir and amt>0 then
        local key=(TML89_PersonalGoldKey and TML89_PersonalGoldKey("guildgold",e.guildId,e.timestamp,amt,dir,tostring(b)..":"..tostring(e.user))) or ("pg:guild:"..tostring(e.guildId)..":"..tostring(e.timestamp)..":"..tostring(amt)..":"..dir)
        local isNew,isOld=TML89_AddPersonalGold(self,key,{timestamp=e.timestamp,user=my,source=source,amount=amt,direction=dir,note=note,guildId=e.guildId},true)
        if isNew then added=added+1 elseif isOld then updated=updated+1 end
      end
    end
  end
  local retained=TML42_Count(self.saved.retainedPersonalGoldEvents); local current=TML42_Count(self.saved.currentScan.personalGold)
  self.saved.ledgerMeta.personalGold={currentRows=current,newRows=added,updatedRows=updated,retainedRows=retained,reviewRows=review,lastScan=now,salesRows=saleScanRows,guildGoldRows=guildGoldSeen}
  self.saved.scanStatus.personalGold="Current scan: "..tostring(current).." personal gold rows seen / "..tostring(added).." new / "..tostring(retained).." all-time loaded retained. Sales rows read: "..tostring(saleScanRows).."."
  if self.MarkScanned then self:MarkScanned(current>0 and "Scanned" or "No New Rows", current>0) end
end

function TML:ComputePersonalGoldStats()
  self:V21693_EnsureCore()
  local st={current=tonumber(self:GetCarriedGoldLive()) or 0,bank=tonumber(self:GetBankGoldLive()),in24=0,out24=0,verifiedNet24=0,net24=0,allIn=0,allOut=0,allNet=0,actualNet24=nil,unmatched24=nil,coverage="Need 24H Baseline",scanned=(self.saved.scanStatus and self.saved.scanStatus.personalGold~=nil)}
  for _,e in ipairs(self:GetPersonalGoldRows("Recent") or {}) do
    local amt=tonumber(e.amount) or 0
    if e.direction=="in" then st.allIn=st.allIn+amt; if TML42_Is24(e.timestamp) then st.in24=st.in24+amt end
    elseif e.direction=="out" then st.allOut=st.allOut+amt; if TML42_Is24(e.timestamp) then st.out24=st.out24+amt end end
  end
  st.verifiedNet24=st.in24-st.out24; st.net24=st.verifiedNet24; st.allNet=st.allIn-st.allOut
  local total=st.current+(st.bank or 0); local hist=self.saved.goldSnapshots and self.saved.goldSnapshots.history or {}; local target=TML42_Now()-86400; local base=nil; local earliest=nil
  for _,s in ipairs(hist) do
    if tonumber(s.total) and tonumber(s.timestamp) then
      if not earliest or (tonumber(s.timestamp) or 0)<(tonumber(earliest.timestamp) or 0) then earliest=s end
      if (tonumber(s.timestamp) or 0)<=target and ((not base) or (tonumber(s.timestamp) or 0)>(tonumber(base.timestamp) or 0)) then base=s end
    end
  end
  if base then st.actualNet24=total-(tonumber(base.total) or 0); st.coverage="Full 24H"
  elseif earliest then local hours=math.floor((TML42_Now()-(tonumber(earliest.timestamp) or 0))/3600); if hours and hours>0 then st.actualNet24=total-(tonumber(earliest.total) or 0); st.coverage="Partial "..tostring(hours).."h" end end
  if st.actualNet24 ~= nil then st.unmatched24=st.actualNet24-st.verifiedNet24 end
  return st
end

function TML:V21693_CycleGuildSalesFilter()
  local list={"All-Time","24H","High Ticket","Review"}
  local cur=self.saved.salesFilter or list[1]; local idx=1
  for i,v in ipairs(list) do if v==cur then idx=i end end
  self.saved.salesFilter=list[(idx%#list)+1]
  self:RenderTool("guild_sales")
end

local TML42_OldRenderSales = TML.RenderOldSales
function TML:RenderOldSales(root,x,y,w,h,accent,guildMode)
  self:V21693_EnsureCore()
  if guildMode then
    local selectorW=300; self:DrawGuildSelectorLive(root,x,y,selectorW,h,accent)
    local rx=x+selectorW+24; local rw=w-selectorW-24; local g=self:GetGuild(); local gid=g and g.id or 0
    local st=self:ComputeSalesStats(gid,false); local cov=self:V21693_SalesCoverage(gid); local topH=254
    self:DrawLegacyPanel(root,"GuildSalesStats93",rx,y,rw,topH,"GUILD SALES TRACKER",accent)
    local cards={{"24H Net",TML42_Gold(st.sales24),VGreen},{"All-Time Net",TML42_Gold(st.totalSales),VYellow},{"All-Time Gross",TML42_Gold(st.gross),C.gold},{"Guild Tax",TML42_Gold(st.tax),VGreen},{"Rows",TML42_Num(cov.guildRows),C.cyanSoft},{"Seller Rows",TML42_Num(cov.guildSellerRows),C.cyanSoft},{"This Scan",TML42_Num(cov.guildRowsThisScan),C.cyanSoft},{"Review",TML42_Num(cov.reviewRows),cov.reviewRows>0 and VRed or C.cyanSoft}}
    local cw=math.floor((rw-104)/4); for i,c in ipairs(cards) do local col=(i-1)%4; local row=math.floor((i-1)/4); self:DrawMiniStat(root,"GuildSalesCard93"..i,rx+20+col*(cw+14),y+58+row*72,cw,62,c[1],c[2],c[3],c[3]) end
    local status=self.saved.scanStatus.sales or "Press Scan Guild. If rows are missing, open/load Guild History first."
    self:Label("GuildSalesStatus93",root,status,rx+24,y+204,rw-48,24,C.cyanSoft,FONTS.panelSmall,TEXT_ALIGN_CENTER)
    self:Label("GuildSalesCoverage93",root,"Guild rows retained: "..tostring(cov.guildRows).." | 24H rows: "..tostring(cov.guild24Rows).." | missing seller: "..tostring(cov.sellerMissing).." | seller parsed: "..tostring(cov.sellerParsed),rx+24,y+226,rw-48,22,C.yellowDim,FONTS.panelSmall,TEXT_ALIGN_CENTER)
    local filter=self.saved.salesFilter or "All-Time"; local rows={}; local source=self:GetSalesRows(gid,false)
    if filter=="24H" then source=self:GetSalesRows24H(gid,false)
    elseif filter=="High Ticket" then table.sort(source,function(a,b) return (tonumber(a.netAmount or a.amount) or 0)>(tonumber(b.netAmount or b.amount) or 0) end)
    elseif filter=="Review" then local rr={}; for _,e in ipairs(source) do if e.review or TML42_CleanUser(e.sellerKey or e.seller or e.sellerRaw)=="" then rr[#rr+1]=e end end; source=rr end
    for _,e in ipairs(source) do rows[#rows+1]={TML42_Limit(e.seller or "Unknown Seller",20),self:FormatItemCell(e.itemLink,e.itemName,24),TML42_Num(e.quantity),TML42_Cell(TML42_Gold(e.grossAmount or e.amount),C.gold),TML42_Cell(TML42_Gold(e.feeAmount or 0),VRed),TML42_Cell(TML42_Gold(e.netAmount or e.amount),VYellow),TML42_Rel(e.timestamp)} end
    local title = (filter=="24H") and "24H GUILD SALES - LAST 24 HOURS" or ((filter=="Review") and "GUILD SALES REVIEW ROWS" or "ALL-TIME LOADED GUILD SALES - SELLER ROWS")
    self:DrawLegacyTable(root,"GuildSalesRows93",rx,y+topH+18,rw,h-topH-96,title,{"Seller","Item","Qty","Gross","Fee","Net","When"},self:RowsOrNA(rows,7,"Press Scan Guild"),accent,{1.1,2,.45,.8,.7,.8,.75})
    local by=y+h-64; local bw=math.floor((rw-36)/4)
    self:ToolButton(root,"GuildSalesScan93",rx,by,bw,48,"Scan Guild",accent,function() TML:ScanSelectedGuildSales() end)
    self:ToolButton(root,"GuildSalesAll93",rx+bw+12,by,bw,48,"Scan All",accent,function() TML:ScanAllGuildSales() end)
