TML_21693_Patch(); TML_21693_Patch=nil -- v2.0.16.93 shared sales parser + ledger source fix

--[[
Tamriel Master Ledger v2.0.16.94 - Phase 43
Chunked Scan Scheduler / Freeze Fix
- Heavy scans are now queued in small chunks so ESO can render between chunks.
- Net Worth no longer triggers guild sales/history scans.
- Page scans show progress and reject double-scan spam while running.
- Personal Gold Ledger runs sales + guild gold + personal merge in staged chunks.
- Guild Sales, Personal Sales, Guild Gold, Guild Bank and Bookkeeper use chunked scan paths.
- No menu/scene/input registration changes.
]]
function TML_21694_Patch()
  if not TML or TML.__v21694Applied then return end
  TML.__v21694Applied = true

  local P43 = {}
  P43.VERSION = "2.0.16.94"
  P43.ADDON_VERSION = 21694
  P43.UPDATED = "06/22/2026 21:45 UTC"
  P43.ROWS_PER_TICK = 85
  P43.BAG_PER_TICK = 90
  P43.DELAY_MS = 10

  local function Now94() return (GetTimeStamp and GetTimeStamp()) or os.time() end
  local function Count94(t) local n=0; if type(t)=="table" then for _ in pairs(t) do n=n+1 end end; return n end
  local function CleanUser94(v)
    v = tostring(v or "")
    v = v:gsub("|c%x%x%x%x%x%x",""):gsub("|r","")
    v = v:gsub("^%s+",""):gsub("%s+$","")
    v = v:gsub("^@","")
    return string.lower(v)
  end
  local function SameUser94(a,b) return CleanUser94(a) ~= "" and CleanUser94(a) == CleanUser94(b) end
  local function Gold94(v) return (WFormatGold and WFormatGold(v or 0)) or (tostring(tonumber(v) or 0).."g") end
  local function Num94(v) return (WFormatNumber and WFormatNumber(v or 0)) or tostring(tonumber(v) or 0) end
  local function Rel94(ts) return (WRelTime and WRelTime(ts)) or tostring(ts or "") end

  local function Later94(fn, delay)
    if type(zo_callLater) == "function" then zo_callLater(fn, delay or P43.DELAY_MS) else fn() end
  end

  function TML:V21694_SetStatus(key, msg, scannedText, scanned)
    self.saved = self.saved or (self.Defaults and self:Defaults()) or {}
    self.saved.scanStatus = self.saved.scanStatus or {}
    self.saved.scanStatus[key or "scan"] = tostring(msg or "Scanning...")
    if self.MarkScanned then pcall(function() self:MarkScanned(scannedText or "Scanning", scanned == true) end) end
  end

  function TML:V21694_RenderActive()
    if self.RenderTool and self.state and self.state.activeTool then pcall(function() self:RenderTool(self.state.activeTool) end) end
  end

  function TML:V21694_StartTask(task)
    self:EnsureDataDefaults()
    if self.__v21694ScanRunning then
      local name = (self.__v21694Task and self.__v21694Task.name) or "another scan"
      self:V21694_SetStatus(task.statusKey or "scan", "Scan already running: "..tostring(name)..". Wait for it to finish.", "Scanning", true)
      self:V21694_RenderActive()
      return 0
    end
    self.__v21694ScanRunning = true
    self.__v21694Task = task
    task.startedAt = Now94()
    self:V21694_SetStatus(task.statusKey or "scan", tostring(task.name or "Scan").." started...", "Scanning", true)
    self:V21694_RenderActive()

    local function tick()
      if not self.__v21694ScanRunning or self.__v21694Task ~= task then return end
      local done = false
      local ok,err = pcall(function() done = task.step(task) == true end)
      if not ok then
        self:V21694_SetStatus(task.statusKey or "scan", "Scan error: "..tostring(err), "Error", false)
        done = true
      end
      if done then
        local ok2,err2 = pcall(function() if task.finish then task.finish(task) end end)
        if not ok2 then self:V21694_SetStatus(task.statusKey or "scan", "Scan finalize error: "..tostring(err2), "Error", false) end
        self.__v21694ScanRunning = false
        self.__v21694Task = nil
        self:V21694_RenderActive()
      else
        Later94(tick, P43.DELAY_MS)
      end
    end
    Later94(tick, P43.DELAY_MS)
    return 0
  end

  function TML:V21694_GetGuildList(selectedOnly)
    local guilds = {}
    if selectedOnly then
      local g = self.GetGuild and self:GetGuild() or nil
      if g and g.id and g.id ~= 0 then guilds[#guilds+1] = g end
    elseif self.EachGuild then
      self:EachGuild(function(g) if g and g.id and g.id ~= 0 then guilds[#guilds+1] = g end end)
    end
    return guilds
  end

  function TML:V21694_MakeSalesChunker(guilds, resetCurrent)
    self:V21693_EnsureCore()
    if resetCurrent then
      self.saved.currentScan.sales = {}
      self.saved.currentScan.salesGuilds = {}
    end
    local ch = {guilds=guilds or {}, gi=1, idx=nil, newest=nil, oldest=nil, cat=nil, g=nil, total=0, newRows=0, updatedRows=0, review=0, missingSeller=0, sellerParsed=0, personal=0, guildCount=0}
    function ch:prepareGuild(tml)
      self.g = self.guilds[self.gi]
      self.idx = nil; self.newest = nil; self.oldest = nil
      if not self.g then return false end
      self.guildCount = self.guildCount + 1
      self.cat = tml:GetHistoryCategory("trader")
      if not self.cat or type(GetGuildHistoryTraderEventInfo) ~= "function" then
        tml:V21694_SetStatus("sales", "Sales history API unavailable.", "No API", false)
        self.gi = self.gi + 1
        return true
      end
      if tml.RequestHistory then pcall(function() tml:RequestHistory(self.g.id,self.cat,WORKING_HISTORY_DAYS) end) end
      local ok,n,o = pcall(tml.GetHistoryIndices, tml, self.g.id, self.cat, WORKING_HISTORY_DAYS)
      if ok then self.newest = tonumber(n); self.oldest = tonumber(o) end
      if not self.newest or not self.oldest or self.oldest < self.newest then
        tml.saved.currentScan.salesGuilds[tostring(self.g.id)] = {name=tostring(self.g.name or self.g.id),scanned=0,accepted=0,newRows=0,updatedRows=0,reviewRows=0,missingSeller=0,sellerParsed=0,personalRows=0,pending=true}
        self.gi = self.gi + 1
        return true
      end
      self.idx = self.newest
      self.gstat = {name=tostring(self.g.name or self.g.id),scanned=0,accepted=0,newRows=0,updatedRows=0,reviewRows=0,missingSeller=0,sellerParsed=0,personalRows=0}
      return true
    end
    function ch:finishGuild(tml)
      if self.g and self.gstat then tml.saved.currentScan.salesGuilds[tostring(self.g.id)] = self.gstat end
      self.gi = self.gi + 1; self.g = nil; self.gstat = nil; self.idx = nil
    end
    function ch:step(tml, maxRows)
      maxRows = maxRows or P43.ROWS_PER_TICK
      local processed = 0
      local my = CleanUser94(tml.GetUserDisplayName and tml:GetUserDisplayName() or "")
      while processed < maxRows do
        if self.gi > #self.guilds then return true end
        if not self.g then self:prepareGuild(tml) end
        if self.g and self.idx then
          while self.idx <= self.oldest and processed < maxRows do
            local vals = {pcall(GetGuildHistoryTraderEventInfo,self.g.id,self.idx)}
            local ok = table.remove(vals,1)
            if ok then
              local p
              if tml.V21693_ParseTrader then p = tml:V21693_ParseTrader(vals,self.idx,self.g.id,self.cat)
              elseif tml.V21692_ParseTrader then p = tml:V21692_ParseTrader(vals,self.idx)
              else p = nil end
              if p and not p.isRedacted and tonumber(p.price) and tonumber(p.price) > 0 then
                self.gstat.scanned = self.gstat.scanned + 1; self.total = self.total + 1
                if p.sellerKey and tostring(p.sellerKey) ~= "" then self.gstat.sellerParsed = self.gstat.sellerParsed + 1; self.sellerParsed = self.sellerParsed + 1 else self.gstat.missingSeller = self.gstat.missingSeller + 1; self.missingSeller = self.missingSeller + 1; self.review = self.review + 1 end
                if CleanUser94(p.sellerKey or p.seller) == my then self.gstat.personalRows = self.gstat.personalRows + 1; self.personal = self.personal + 1 end
                local added,existed = false,false
                if tml.V21693_AddSale then added,existed = tml:V21693_AddSale(self.g.id,p,true,self.idx)
                elseif tml.V21692_AddSale then added,existed = tml:V21692_AddSale(self.g.id,p,true,self.idx) end
                if added or existed then self.gstat.accepted = self.gstat.accepted + 1 end
                if added then self.gstat.newRows = self.gstat.newRows + 1; self.newRows = self.newRows + 1 elseif existed then self.gstat.updatedRows = self.gstat.updatedRows + 1; self.updatedRows = self.updatedRows + 1 end
              else
                self.gstat.reviewRows = self.gstat.reviewRows + 1; self.review = self.review + 1
              end
            else
              self.gstat.reviewRows = self.gstat.reviewRows + 1; self.review = self.review + 1
            end
            self.idx = self.idx + 1; processed = processed + 1
          end
          tml:V21694_SetStatus("sales", "Scanning sales: "..tostring(self.g.name or "Guild").." row "..tostring(math.min(self.idx or 0,self.oldest or 0)).." / "..tostring(self.oldest or 0)..". Current rows: "..tostring(self.total).." / yours: "..tostring(self.personal)..".", "Scanning", true)
          if self.idx and self.oldest and self.idx > self.oldest then self:finishGuild(tml) end
          return false
        end
      end
      return false
    end
    function ch:finish(tml)
      local cov = tml.V21693_SalesCoverage and tml:V21693_SalesCoverage() or {}
      tml.saved.ledgerMeta.sales = {currentRows=self.total,newRows=self.newRows,updatedRows=self.updatedRows,retainedRows=Count94(tml.saved.retainedSalesEvents),reviewRows=self.review,missingSeller=self.missingSeller,sellerParsed=self.sellerParsed,guilds=self.guildCount,guildsWithRows=cov.guildsWithRows or 0,personalCurrentRows=cov.personalRowsThisScan or self.personal,personalAllRows=cov.personalAllRows or 0,personal24Rows=cov.personal24Rows or 0,oldest=cov.oldest,newest=cov.newest,lastScan=Now94(),coverage=cov.coverage or "Loaded"}
      tml.saved.scanStatus.sales = "Scan complete without freezing: "..tostring(self.total).." guild sale rows / "..tostring(cov.personalAllRows or 0).." all-time @UserID rows / "..tostring(cov.personal24Rows or 0).." 24H."
      if tml.MarkScanned then tml:MarkScanned("Scanned", self.total > 0) end
    end
    return ch
  end

  function TML:V21694_StartSalesScan(guilds, toolKey, statusKey)
    local chunker = self:V21694_MakeSalesChunker(guilds, true)
    return self:V21694_StartTask({name="Sales Scan",statusKey=statusKey or "sales",tool=toolKey or (self.state and self.state.activeTool) or "personal_sales",step=function(task) return chunker:step(self,P43.ROWS_PER_TICK) end,finish=function(task) chunker:finish(self) end})
  end

  function TML:ScanAllGuildSales(noRender)
    return self:V21694_StartSalesScan(self:V21694_GetGuildList(false), self.state and self.state.activeTool or "personal_sales", "sales")
  end
  function TML:ScanGuildSales(g,noRender,noReset)
    local list = {}; if g and g.id and g.id ~= 0 then list[1] = g end
    return self:V21694_StartSalesScan(list, self.state and self.state.activeTool or "guild_sales", "sales")
  end
  function TML:ScanSelectedGuildSales(noRender)
    return self:ScanGuildSales(self:GetGuild(), noRender, false)
  end
  function TML:ScanPersonalSales(noRender)
    return self:ScanAllGuildSales(noRender)
  end

  function TML:V21694_MakeGuildGoldChunker(guilds, clearGuildRows)
    local ch = {guilds=guilds or {}, gi=1, g=nil, idx=nil, newest=nil, oldest=nil, cat=nil, scanned=0,accepted=0,review=0}
    function ch:prepareGuild(tml)
      self.g = self.guilds[self.gi]
      self.idx=nil; self.newest=nil; self.oldest=nil
      if not self.g then return false end
      self.cat = tml:GetHistoryCategory("bankedCurrency")
      if not self.cat or type(GetGuildHistoryBankedCurrencyEventInfo) ~= "function" then self.gi=self.gi+1; self.g=nil; return true end
      if clearGuildRows then for key,e in pairs(tml.saved.guildGoldEvents or {}) do if e and e.guildId==self.g.id then tml.saved.guildGoldEvents[key]=nil end end end
      if tml.RequestHistory then pcall(function() tml:RequestHistory(self.g.id,self.cat,WORKING_HISTORY_DAYS) end) end
      local ok,n,o = pcall(tml.GetHistoryIndices,tml,self.g.id,self.cat,WORKING_HISTORY_DAYS)
      if ok then self.newest=tonumber(n); self.oldest=tonumber(o) end
      if not self.newest or not self.oldest or self.oldest < self.newest then self.gi=self.gi+1; self.g=nil; return true end
      self.idx=self.newest
      return true
    end
    function ch:step(tml,maxRows)
      maxRows=maxRows or P43.ROWS_PER_TICK
      local processed=0
      while processed < maxRows do
        if self.gi > #self.guilds then return true end
        if not self.g then self:prepareGuild(tml) end
        if self.g and self.idx then
          while self.idx <= self.oldest and processed < maxRows do
            local ok,eventId,timestamp,isRedacted,eventType,displayName,currencyType,amount,kioskName = pcall(GetGuildHistoryBankedCurrencyEventInfo,self.g.id,self.idx)
            local isMoney = (currencyType == nil or _G.CURT_MONEY == nil or currencyType == _G.CURT_MONEY)
            if ok and not isRedacted and displayName and amount and isMoney then
              tml:AddGuildGoldEvent(self.g.id,eventId or self.idx,displayName,tonumber(amount),timestamp,nil,nil,tostring(kioskName or ""),eventType)
              self.scanned = self.scanned + 1; self.accepted = self.accepted + 1
            else self.review = self.review + 1 end
            self.idx = self.idx + 1; processed = processed + 1
          end
          tml:V21694_SetStatus("gold", "Scanning guild gold: "..tostring(self.g.name or "Guild").." row "..tostring(math.min(self.idx or 0,self.oldest or 0)).." / "..tostring(self.oldest or 0)..". Rows: "..tostring(self.scanned)..".", "Scanning", true)
          if self.idx > self.oldest then self.gi=self.gi+1; self.g=nil; self.idx=nil end
          return false
        end
      end
      return false
    end
    function ch:finish(tml)
      if tml.RebuildDonationEvents then pcall(function() tml:RebuildDonationEvents() end) end
      tml.saved.scanStatus.gold = "Scan complete without freezing: "..tostring(self.scanned).." guild gold rows / "..tostring(self.review).." review."
      if tml.MarkScanned then tml:MarkScanned(self.scanned>0 and "Scanned" or "No Data", self.scanned>0) end
    end
    return ch
  end

  function TML:ScanSelectedGuildGold()
    local guilds = self:V21694_GetGuildList(true)
    local chunker = self:V21694_MakeGuildGoldChunker(guilds,true)
    return self:V21694_StartTask({name="Guild Gold Scan",statusKey="gold",tool=self.state and self.state.activeTool or "guild_gold_ledger",step=function(task) return chunker:step(self,P43.ROWS_PER_TICK) end,finish=function(task) chunker:finish(self) end})
  end
  function TML:ScanGuildGold(g)
    local guilds = {}; if g and g.id and g.id ~= 0 then guilds[1]=g end
    local chunker = self:V21694_MakeGuildGoldChunker(guilds,true)
    return self:V21694_StartTask({name="Guild Gold Scan",statusKey="gold",tool=self.state and self.state.activeTool or "guild_gold_ledger",step=function(task) return chunker:step(self,P43.ROWS_PER_TICK) end,finish=function(task) chunker:finish(self) end})
  end

  function TML:V21694_StartPersonalGoldScan()
    self:V21693_EnsureCore()
    self.saved.currentScan.personalGold = {}
    self.saved.goldSnapshots = self.saved.goldSnapshots or {}; self.saved.goldSnapshots.history = self.saved.goldSnapshots.history or {}
    local carried=tonumber(self:GetCarriedGoldLive()) or 0; local bank=tonumber(self:GetBankGoldLive()); local total=carried+(bank or 0); local now=Now94()
    table.insert(self.saved.goldSnapshots.history,{carriedGold=carried,bankedGold=bank,total=total,timestamp=now})
    while #self.saved.goldSnapshots.history > 72 do table.remove(self.saved.goldSnapshots.history,1) end
    self.saved.goldSnapshots.personalLast = {carriedGold=carried,bankedGold=bank,total=total,timestamp=now}
    local guilds = self:V21694_GetGuildList(false)
    local salesChunker = self:V21694_MakeSalesChunker(guilds,true)
    local goldChunker = self:V21694_MakeGuildGoldChunker(guilds,true)
    local phase = "sales"
    local saleList, goldList, saleIdx, goldIdx = nil,nil,1,1
    local added,updated,review = 0,0,0
    local function prepareLists(tml)
      saleList = {}; for sk,s in pairs(tml.saved.retainedSalesEvents or {}) do saleList[#saleList+1] = {key=sk,row=s} end
      goldList = {}; for _,e in pairs(tml.saved.guildGoldEvents or {}) do goldList[#goldList+1] = e end
      saleIdx = 1; goldIdx = 1
    end
    local task = {name="Personal Gold Ledger Refresh",statusKey="personalGold",tool="gold_ledger_personal"}
    function task:step()
      if phase == "sales" then
        local done = salesChunker:step(TML,P43.ROWS_PER_TICK)
        TML:V21694_SetStatus("personalGold", "Refreshing ledger: scanning sales in chunks...", "Scanning", true)
        if done then phase = "gold" end
        return false
      elseif phase == "gold" then
        local done = goldChunker:step(TML,P43.ROWS_PER_TICK)
        TML:V21694_SetStatus("personalGold", "Refreshing ledger: scanning guild gold in chunks...", "Scanning", true)
        if done then goldChunker:finish(TML); prepareLists(TML); phase = "mergeSales" end
        return false
      elseif phase == "mergeSales" then
        local my=TML:GetUserDisplayName(); local myKey=CleanUser94(my); local processed=0
        while saleIdx <= #saleList and processed < P43.ROWS_PER_TICK do
          local sk=saleList[saleIdx].key; local s=saleList[saleIdx].row
          if type(s)=="table" and CleanUser94(s.sellerKey or s.seller or s.sellerRaw) == myKey then
            local amt=tonumber(s.netAmount or s.amount) or 0
            if amt>0 then
              local key=(TML89_PersonalGoldKey and TML89_PersonalGoldKey("sale",s.guildId,s.timestamp,amt,"in",sk)) or ("pg:sale:"..tostring(sk))
              local cur=(TML.saved.currentScan.sales or {})[sk] == true
              local isNew,isOld=TML89_AddPersonalGold(TML,key,{timestamp=s.timestamp,user=my,source="Guild Trader Sale",amount=amt,direction="in",note=TML:GetGuildName(s.guildId),guildId=s.guildId,sourceKey=sk},cur)
              if isNew then added=added+1 elseif isOld and cur then updated=updated+1 end
            end
          end
          saleIdx=saleIdx+1; processed=processed+1
        end
        TML:V21694_SetStatus("personalGold", "Refreshing ledger: merging personal sale income "..tostring(math.min(saleIdx,#saleList)).." / "..tostring(#saleList).."...", "Scanning", true)
        if saleIdx > #saleList then phase = "mergeGold" end
        return false
      elseif phase == "mergeGold" then
        local my=TML:GetUserDisplayName(); local processed=0
        while goldIdx <= #goldList and processed < P43.ROWS_PER_TICK do
          local e=goldList[goldIdx]
          if type(e)=="table" and SameUser94(e.user,my) then
            local b=tostring(e.bucket or ""); local amt=tonumber(e.amount) or 0; local action=tostring(e.action or "")
            local dir,source,note=nil,nil,b
            if action=="deposit" and (b=="Donation" or b=="Ticket" or b=="Giveaway Ticket" or b=="Reset") then dir="out"; source="Guild Bank Deposit"
            elseif action=="withdraw" and (b=="Withdrawal" or b=="Other / Review" or b=="Withdraw") then dir="in"; source="Guild Bank Withdrawal"
            else review=review+1 end
            if dir and amt>0 then
              local key=(TML89_PersonalGoldKey and TML89_PersonalGoldKey("guildgold",e.guildId,e.timestamp,amt,dir,tostring(b)..":"..tostring(e.user))) or ("pg:guild:"..tostring(e.guildId)..":"..tostring(e.timestamp)..":"..tostring(amt)..":"..dir)
              local isNew,isOld=TML89_AddPersonalGold(TML,key,{timestamp=e.timestamp,user=my,source=source,amount=amt,direction=dir,note=note,guildId=e.guildId},true)
              if isNew then added=added+1 elseif isOld then updated=updated+1 end
            end
          end
          goldIdx=goldIdx+1; processed=processed+1
        end
        TML:V21694_SetStatus("personalGold", "Refreshing ledger: merging guild bank gold rows "..tostring(math.min(goldIdx,#goldList)).." / "..tostring(#goldList).."...", "Scanning", true)
        return goldIdx > #goldList
      end
      return true
    end
    function task:finish()
      salesChunker:finish(TML)
      local retained=Count94(TML.saved.retainedPersonalGoldEvents); local current=Count94(TML.saved.currentScan.personalGold)
      TML.saved.ledgerMeta.personalGold={currentRows=current,newRows=added,updatedRows=updated,retainedRows=retained,reviewRows=review,lastScan=Now94(),salesRows=salesChunker.total,guildGoldRows=goldChunker.scanned}
      TML.saved.scanStatus.personalGold="Ledger refresh complete without freezing: "..tostring(current).." current rows / "..tostring(retained).." all-time loaded. Sales rows read: "..tostring(salesChunker.total).."."
      if TML.MarkScanned then TML:MarkScanned(current>0 and "Scanned" or "No New Rows", current>0) end
    end
    return self:V21694_StartTask(task)
  end
  function TML:ScanPersonalGoldLedger() return self:V21694_StartPersonalGoldScan() end

  function TML:V21694_InitNetWorthSnapshot()
    local nw
    if self.V21683_NewNetWorth then nw = self:V21683_NewNetWorth() else nw = {scanned=true,total=0,character=0,carriedGold=tonumber(self:GetCarriedGoldLive()) or 0,bankedGold=tonumber(self:GetBankGoldLive()) or 0,carriedItems=0,bankedItems=0,craftBag=0,unpriced=0,unpricedItems={},top={},currencies={},lastScan=Now94(),craftBagStatus="Not scanned",crownRate=tonumber(self.saved and self.saved.crownRate),crownGold=nil,pricedStacks=0,seenStacks=0,itemMap={},unpricedMap={}} end
    local accountLoc={_G.CURRENCY_LOCATION_ACCOUNT,nil}; local charBankLoc={_G.CURRENCY_LOCATION_CHARACTER,_G.CURRENCY_LOCATION_BANK,_G.CURRENCY_LOCATION_ACCOUNT,nil}
    nw.currencies={{"Crowns",WCurrencyAny({"CURT_CROWNS","CURT_CROWN_CROWNS"},accountLoc)},{"Crown Gems",WCurrencyAny({"CURT_CROWN_GEMS"},accountLoc)},{"Writ Vouchers",WCurrencyAny({"CURT_WRIT_VOUCHERS","CURT_WRIT_VOUCHER"},charBankLoc)},{"Alliance Points",WCurrencyAny({"CURT_ALLIANCE_POINTS"},charBankLoc)},{"Tel Var Stones",WCurrencyAny({"CURT_TELVAR_STONES"},charBankLoc)},{"Gold Bars",WCurrencyAny({"CURT_TRADE_BARS","CURT_GOLD_BARS","CURT_EVENT_TICKETS","CURT_EVENT_TICKET"},accountLoc)},{"Undaunted Keys",WCurrencyAny({"CURT_UNDAUNTED_KEYS","CURT_UNDAUNTED_KEY"},charBankLoc)},{"Seals",WCurrencyAny({"CURT_SEALS_OF_ENDEAVOR","CURT_ENDEAVOR_SEALS","CURT_SEAL_OF_ENDEAVOR"},accountLoc)},{"Archival Fortunes",WCurrencyAny({"CURT_ARCHIVAL_FORTUNES","CURT_ARCHIVAL_FORTUNE"},charBankLoc)},{"Tome Points",WCurrencyAny({"CURT_TOME_POINTS","CURT_TAMRIEL_TOME_POINTS","CURT_TAMRIEL_TOMES"},charBankLoc)}}
    return nw
  end

  function TML:V21694_CraftSlotList()
    local list = {}; local bagId = _G.BAG_VIRTUAL
    if not bagId then return list end
    local seen = {}
    if SHARED_INVENTORY then
      for _,method in ipairs({"GenerateFullSlotData","GetBagCache","GetOrCreateBagCache"}) do
        if type(SHARED_INVENTORY[method]) == "function" then
          local ok,data
          if method == "GenerateFullSlotData" then ok,data = pcall(function() return SHARED_INVENTORY:GenerateFullSlotData(nil, bagId) end) else ok,data = pcall(function() return SHARED_INVENTORY[method](SHARED_INVENTORY, bagId) end) end
          if ok and type(data) == "table" then
            for slotKey,slotData in pairs(data) do
              local slotIndex = tonumber(slotData and (slotData.slotIndex or slotData.slotId or slotData.slot or slotKey)) or tonumber(slotKey)
              local key = tostring(slotIndex or slotKey)
              if not seen[key] then seen[key]=true; list[#list+1]={bagId=bagId,slot=slotIndex,slotData=slotData,bucket="craftBag",loc="Craft Bag"} end
            end
          end
        end
      end
    end
    if #list == 0 and type(GetBagSize) == "function" then
      local ok,size=pcall(GetBagSize,bagId); size=ok and tonumber(size) or 0
      for slot=0,math.max(0,size-1) do list[#list+1]={bagId=bagId,slot=slot,slotData=nil,bucket="craftBag",loc="Craft Bag"} end
    end
    return list
  end

  function TML:ScanNetWorth()
    self:EnsureDataDefaults()
    self.saved.networth = nil
    local nw = self:V21694_InitNetWorthSnapshot()
    local slots = {}
    local function addBag(bag,bucket,loc)
      if bag ~= nil and type(GetBagSize) == "function" then local ok,size=pcall(GetBagSize,bag); size=ok and tonumber(size) or 0; for slot=0,math.max(0,size-1) do slots[#slots+1]={bagId=bag,slot=slot,slotData=nil,bucket=bucket,loc=loc} end end
    end
    addBag(_G.BAG_BACKPACK,"carriedItems","Backpack")
    addBag(_G.BAG_BANK,"bankedItems","Bank")
    addBag(_G.BAG_SUBSCRIBER_BANK,"bankedItems","Bank")
    local craftStart = #slots + 1
    local craft = self:V21694_CraftSlotList(); for _,s in ipairs(craft) do slots[#slots+1]=s end
    local idx = 1; local seenCraft = {}; local seenSlot = {}; local totalSlots = #slots
    local task = {name="Net Worth Scan",statusKey="networth",tool="net_worth"}
    function task:step()
      local processed=0
      while idx <= totalSlots and processed < P43.BAG_PER_TICK do
        local s=slots[idx]
        local link = TML.V21683_SlotLink and TML:V21683_SlotLink(s.bagId,s.slot,s.slotData) or (type(GetItemLink)=="function" and select(2,pcall(GetItemLink,s.bagId,s.slot)))
        if link and link ~= "" then
          local qty = TML.V21683_SlotQty and TML:V21683_SlotQty(s.bagId,s.slot,s.slotData) or 1
          local uniqueKey = tostring(s.bagId)..":"..tostring(s.slot)..":"..tostring(link)
          if s.bucket == "craftBag" then uniqueKey = tostring(link) end
          if not seenSlot[uniqueKey] and not (s.bucket=="craftBag" and seenCraft[tostring(link)]) then
            seenSlot[uniqueKey]=true; if s.bucket=="craftBag" then seenCraft[tostring(link)]=true end
            if TML.V21683_AddNWItem then TML:V21683_AddNWItem(nw,link,qty,s.bucket,s.loc) end
          end
        end
        idx = idx + 1; processed = processed + 1
      end
      local zone = idx < craftStart and "inventory/bank" or "craft bag"
      TML:V21694_SetStatus("networth", "Scanning Net Worth "..zone..": "..tostring(math.min(idx,totalSlots)).." / "..tostring(totalSlots).." slots. No guild history is scanned here.", "Scanning", true)
      return idx > totalSlots
    end
    function task:finish()
      local crowns=nil; for _,cur in ipairs(nw.currencies or {}) do if cur[1]=="Crowns" then crowns=tonumber(cur[2]) end end
      if nw.crownRate and nw.crownRate > 0 and crowns then nw.crownGold = math.floor(crowns * nw.crownRate) end
      if TML.V21683_FinalizeNetWorth then TML:V21683_FinalizeNetWorth(nw) end
      nw.character = (tonumber(nw.carriedGold) or 0) + (tonumber(nw.carriedItems) or 0)
      nw.total = nw.character + (tonumber(nw.bankedGold) or 0) + (tonumber(nw.bankedItems) or 0) + (tonumber(nw.craftBag) or 0) + (tonumber(nw.crownGold) or 0)
      nw.craftBagStatus = "Scanned in chunks"
      TML.saved.networth = nw
      TML.saved.goldSnapshots = TML.saved.goldSnapshots or {}; TML.saved.goldSnapshots.last = {carriedGold=nw.carriedGold, bankedGold=nw.bankedGold, timestamp=Now94()}
      TML.saved.scanStatus.networth = "Scan complete without freezing: "..tostring(#(nw.top or {})).." priced top items / "..tostring(nw.unpriced or 0).." unpriced. Guild sales were not scanned."
      if TML.MarkScanned then TML:MarkScanned("Scanned", true) end
    end
    return self:V21694_StartTask(task)
  end

  function TML:ScanGuildBankItems(g)
    self:EnsureDataDefaults(); g=g or self:GetGuild(); if not g or not g.id or g.id==0 then return 0 end
    local cat=self:GetHistoryCategory("bankedItem")
    if type(GetGuildHistoryBankedItemEventInfo) ~= "function" or not cat then self.saved.scanStatus.bank="Guild bank item API unavailable"; return 0 end
    local guild=g; local newest,oldest,idx=nil,nil,nil; local scanned,saved,skipped=0,0,0
    local task={name="Guild Bank Item Scan",statusKey="bank",tool=self.state and self.state.activeTool or "guild_bank"}
    function task:step()
      if not idx then
        if TML.RequestHistory then pcall(function() TML:RequestHistory(guild.id,cat,WORKING_HISTORY_DAYS) end) end
        local ok,n,o=pcall(TML.GetHistoryIndices,TML,guild.id,cat,WORKING_HISTORY_DAYS); if ok then newest=tonumber(n); oldest=tonumber(o) end
        if not newest or not oldest or oldest < newest then return true end
        idx=newest
      end
      local processed=0
      while idx <= oldest and processed < P43.ROWS_PER_TICK do
        local vals={pcall(GetGuildHistoryBankedItemEventInfo,guild.id,idx)}; local ok=table.remove(vals,1)
        if ok then
          local eventId,timestamp,isRedacted,eventType,displayName,itemLink,quantity=vals[1],vals[2],vals[3],vals[4],vals[5],vals[6],vals[7]
          local note=""; local itemName=""
          for _,v in ipairs(vals) do
            if type(v)=="string" then
              if v:find("|H",1,true) then itemLink=v elseif displayName==nil or displayName=="" then displayName=v elseif itemName=="" and not v:find("@",1,true) then itemName=v else note=note.." "..v end
            elseif type(v)=="number" then if v>1000000000 then timestamp=v elseif v>0 and v<=100000 and (not quantity or quantity==0) then quantity=v end end
          end
          scanned=scanned+1
          if not isRedacted and displayName and displayName~="" and ((itemLink and itemLink~="") or itemName~="") then local action=(TML.IsBankItemWithdraw and TML:IsBankItemWithdraw(eventType,note)) and "withdraw" or "deposit"; TML:AddBankItem(guild.id,eventId or idx,displayName,itemLink,quantity or 1,timestamp or Now94(),action,itemName); saved=saved+1 else skipped=skipped+1 end
        else skipped=skipped+1 end
        idx=idx+1; processed=processed+1
      end
      TML:V21694_SetStatus("bank", "Scanning guild bank items: "..tostring(math.min(idx or 0,oldest or 0)).." / "..tostring(oldest or 0).." rows. Saved: "..tostring(saved)..".", "Scanning", true)
      return idx and oldest and idx > oldest
    end
    function task:finish()
      TML.saved.scanStatus.bank="Scan complete without freezing: "..tostring(saved).." / "..tostring(scanned).." bank item rows, skipped "..tostring(skipped).."."
      if TML.MarkScanned then TML:MarkScanned(saved>0 and "Scanned" or "No Data", saved>0) end
    end
    return self:V21694_StartTask(task)
  end
  function TML:ScanSelectedGuildBank() return self:ScanGuildBankItems(self:GetGuild()) end

  function TML:ScanBookkeeper()
    local g = self:GetGuild()
    if not g or not g.id or g.id == 0 then return 0 end
    local phase = "roster"; local salesChunker = self:V21694_MakeSalesChunker({g}, true); local goldChunker = self:V21694_MakeGuildGoldChunker({g}, true)
    local task={name="Bookkeeper Scan",statusKey="bookkeeper",tool="bookkeeper"}
    function task:step()
      if phase=="roster" then if TML.ScanRoster then pcall(function() TML:ScanRoster(g) end) end; phase="sales"; return false
      elseif phase=="sales" then local done=salesChunker:step(TML,P43.ROWS_PER_TICK); TML:V21694_SetStatus("bookkeeper","Bookkeeper scan: sales chunk...","Scanning",true); if done then phase="gold" end; return false
      elseif phase=="gold" then local done=goldChunker:step(TML,P43.ROWS_PER_TICK); TML:V21694_SetStatus("bookkeeper","Bookkeeper scan: gold chunk...","Scanning",true); if done then goldChunker:finish(TML); phase="bank" end; return false
      elseif phase=="bank" then if TML.ScanRaffleEntries then pcall(function() TML:ScanRaffleEntries(true) end) end; return true end
      return true
    end
    function task:finish() salesChunker:finish(TML); TML.saved.scanStatus.bookkeeper="Bookkeeper scan complete without one-frame lock. Sales/gold processed in chunks." end
    return self:V21694_StartTask(task)
  end

